def detect_peaks(senal, prominence=None, height=None, distance=None):
    """
    [C-5.2] FunciÃ³n canÃ³nica Ãºnica para detecciÃ³n de picos en toda seÃ±al 1D.
    """
    peaks, _ = find_peaks(senal, prominence=prominence, height=height,
                          distance=distance)
    return peaks


def _calcular_tiempo_rampa(bpm1, bpm2, n_clics):
    """
    [C-7.3] Calcula la duraciÃ³n exacta de la rampa sumando los perÃ­odos
    interpolados linealmente en BPM, uno por cada click de la rampa
    (incluye el punto final en bpm2).
    """
    if n_clics <= 1:
        return 0.0
    divisor = n_clics - 1
    i = np.arange(n_clics)
    bpm_actual = bpm1 + (bpm2 - bpm1) * (i / divisor)
    periodos = 60.0 / bpm_actual
    return float(np.sum(periodos))


def convert_numpy_to_python(obj):
    """
    [C-9.5] Convierte tipos NumPy a tipos Python nativos.
    np.nan e np.inf â†’ None (JSON null estÃ¡ndar).
    """
    if isinstance(obj, np.ndarray):
        return [convert_numpy_to_python(v) for v in obj.tolist()]
    elif isinstance(obj, np.integer):
        return int(obj)
    elif isinstance(obj, np.floating):
        val = float(obj)
        return None if (np.isnan(val) or np.isinf(val)) else val
    elif isinstance(obj, np.bool_):
        return bool(obj)
    elif isinstance(obj, dict):
        return {k: convert_numpy_to_python(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple)):
        return [convert_numpy_to_python(v) for v in obj]
    elif isinstance(obj, float):
        return None if (np.isnan(obj) or np.isinf(obj)) else obj
    return obj


def calcular_estadisticas(arr_ms, nombre=""):
    """
    EstadÃ­sticas descriptivas de un array de valores en ms.
    Retorna dict con mean, std, median, min, max, n.
    """
    a = np.asarray(arr_ms, dtype=float)
    a = a[~np.isnan(a)]
    if a.size == 0:
        return {}
    return {
        'mean_ms':   float(np.mean(a)),
        'std_ms':    float(np.std(a)),
        'median_ms': float(np.median(a)),
        'min_ms':    float(np.min(a)),
        'max_ms':    float(np.max(a)),
        'n':         int(a.size)
    }


def graficar_cambios_bpm(metadata, start_time=0, ax=None):
    """
    [C-10.3] Calcula tiempos de cambio de BPM y los dibuja sobre ax si
    GRAFICAR es True. No produce efectos laterales si ax=None.

    Returns:
        float (PA) | tuple[float,float] (PR) | None (ISO)
    """
    tipo = metadata.get('tipo_metronomo', 'ISO')
    if tipo == 'PA':
        cambio = metadata['clics_1'] * (60.0 / metadata['bpm_1']) + start_time
        if GRAFICAR and ax is not None:
            ax.axvline(x=cambio, color='r', linestyle='--', label='Cambio de BPM')
        return cambio
    elif tipo == 'PR':
        cambio1 = metadata['clics_1'] * (60.0 / metadata['bpm_1']) + start_time
        tr      = _calcular_tiempo_rampa(metadata['bpm_1'], metadata['bpm_2'],
                                         metadata['clics_rampa'])
        cambio2 = cambio1 + tr
        if GRAFICAR and ax is not None:
            ax.axvline(x=cambio1, color='r', linestyle='--', label='1er cambio BPM')
            ax.axvline(x=cambio2, color='g', linestyle='--', label='2do cambio BPM')
        return cambio1, cambio2
    return None
# ==============================================================================
# FUNCIONES AUXILIARES INTERNAS
# ==============================================================================

def _ioi_from_resp_times(resp_times_s):
    """
    Calcula los IOI (Inter-Onset Intervals) en ms a partir de los tiempos
    de respuesta en segundos.
    Returns np.ndarray en ms, o vacÃ­o si hay menos de 2 respuestas.
    """
    if len(resp_times_s) < 2:
        return np.array([])
    return np.diff(np.asarray(resp_times_s)) * 1000.0


# ==============================================================================
# [TB-2] COEFICIENTE DE VARIACIÃ“N DEL IOI
# ==============================================================================

def calcular_cv_ioi(resp_times_s):
    """
    [TB-2] Calcula el coeficiente de variaciÃ³n (CV) de los IOI.

    CV = std(IOI) / mean(IOI)

    Alta CV indica control motor inestable (Grondin, 2008).
    Referencia: documento "Cuantificadores" â€” TEMPORAL BÃSICO.

    Args:
        resp_times_s : array de tiempos de respuesta en segundos.
    Returns:
        dict con 'cv', 'mean_ioi_ms', 'std_ioi_ms', 'n_ioi'.
        cv = None si hay menos de 2 IOI.
    """
    ioi = _ioi_from_resp_times(resp_times_s)
    if ioi.size < 2:
        return {'cv': None, 'mean_ioi_ms': None, 'std_ioi_ms': None, 'n_ioi': int(ioi.size)}

    m = float(np.mean(ioi))
    s = float(np.std(ioi))
    cv = round(s / m, 4) if m > 0 else None

    return {
        'cv':          cv,
        'mean_ioi_ms': round(m, 3),
        'std_ioi_ms':  round(s, 3),
        'n_ioi':       int(ioi.size)
    }


# ==============================================================================
# [AD-1] COEFICIENTE DE CORRECCIÃ“N (Î±)
# ==============================================================================

def calcular_alpha_correccion(asinc_ms):
    """
    [AD-1] Calcula el coeficiente de correcciÃ³n temporal Î± mediante regresiÃ³n
    lineal entre asincronÃ­as consecutivas:

        asincronÃ­a_{n+1} = Î± * asincronÃ­a_n + c

    InterpretaciÃ³n (Wing & Kristofferson, 1973):
      Î± â‰ˆ -0.5 : control adaptativo ideal (correcciÃ³n proporcional).
      Î± â‰ˆ  0   : inercia temporal (sin correcciÃ³n).
      Î± â‰ˆ -1   : sobrecorrecciÃ³n (oscilaciÃ³n).
      Î± >  0   : deriva sistemÃ¡tica.

    Args:
        asinc_ms : array de asincronÃ­as en ms (ordenadas cronolÃ³gicamente).
    Returns:
        dict con 'alpha', 'intercept', 'r_squared', 'n'.
        Todos None si hay menos de 3 asincronÃ­as vÃ¡lidas.
    """
    a = np.asarray(asinc_ms, dtype=float)
    a = a[~np.isnan(a)]

    if len(a) < 3:
        return {'alpha': None, 'intercept': None, 'r_squared': None, 'n': int(len(a))}

    x = a[:-1]   # asincronÃ­a_n
    y = a[1:]    # asincronÃ­a_{n+1}

    slope, intercept, r_value, p_value, _ = linregress(x, y)

    return {
        'alpha':      round(float(slope), 4),
        'intercept':  round(float(intercept), 3),
        'r_squared':  round(float(r_value**2), 4),
        'p_value':    round(float(p_value), 4),
        'n':          int(len(x))
    }

# ==============================================================================
# [AD-2] TIEMPO DE RESTABLECIMIENTO (Tr) POST-PERTURBACIÃ“N
# ==============================================================================

def construir_asyn_por_estimulo(output, n_stims):
    """
    Convierte el output de compute_asyn (un valor de asincronÃ­a por respuesta)
    en un array indexado por estÃ­mulo, con NaN donde no hubo respuesta asignada.
    """
    asyn_por_stim = np.full(n_stims, np.nan)
    valid = output['assigned_stim'] >= 0
    idx_validos = output.loc[valid, 'assigned_stim'].astype(int).values
    asyn_por_stim[idx_validos] = output.loc[valid, 'asyn'].values
    return asyn_por_stim


def _reasignar_o_descartar_tras_hueco(asyn_por_stim, stim_times, umbral_ms=300.0,
                                       min_huecos_antes=1, umbral_residuo_plausible_ms=200.0):
    """
    Un valor de asincronÃ­a AISLADO, con magnitud extrema, que aparece
    justo despuÃ©s de uno o mÃ¡s huecos (NaN) consecutivos generalmente NO
    es ruido -- es una respuesta REAL asignada al estÃ­mulo equivocado.

    Motivo (confirmado con evidencia directa): cuando se pierden 2+
    respuestas seguidas, el matching ordinal (que no reasigna por
    cercanÃ­a temporal, ver docstring de compute_asyn_ordinal) puede
    terminar atribuyendo un tap real -- pero que en realidad le
    correspondÃ­a a uno de los estÃ­mulos DENTRO del hueco -- al primer
    estÃ­mulo DESPUÃ‰S del hueco. En una sesiÃ³n real, track y audio
    coincidieron en un valor de ~-640ms justo ahÃ­ (ambas fuentes de
    acuerdo, descarta que sea ruido) -- y al reconstruir el tiempo real
    de esa respuesta (stim_time_asignado + asyn/1000) y compararlo contra
    CADA estÃ­mulo del hueco, resultÃ³ estar a solo ~107ms del primer
    estÃ­mulo del hueco (contra 643ms del estÃ­mulo donde habÃ­a quedado
    mal asignada) -- confirmando que la respuesta es real, solo estaba
    en el lugar equivocado.

    Se reconstruye el tiempo real de la respuesta y se busca, entre los
    estÃ­mulos del hueco inmediatamente anterior, cuÃ¡l da el residuo mÃ¡s
    chico. Si ese residuo es plausible (por debajo de
    umbral_residuo_plausible_ms), se reasigna ahÃ­. Si NINGÃšN estÃ­mulo del
    hueco da un residuo plausible, se descarta (NaN) en vez de forzar una
    reasignaciÃ³n dudosa -- ante la duda, no inventar.
    """
    asyn = np.asarray(asyn_por_stim, dtype=float).copy()
    stim_times = np.asarray(stim_times, dtype=float)
    n = len(asyn)
    mask_hueco = np.isnan(asyn)
    for i in range(1, n):
        if mask_hueco[i] or abs(asyn[i]) <= umbral_ms:
            continue
        idx_hueco = []
        j = i - 1
        while j >= 0 and mask_hueco[j]:
            idx_hueco.append(j)
            j -= 1
        if len(idx_hueco) < min_huecos_antes:
            continue
        idx_hueco = idx_hueco[::-1]   # orden temporal (mÃ¡s antiguo primero)

        resp_time = stim_times[i] + asyn[i] / 1000.0
        residuos_ms = np.abs((resp_time - stim_times[idx_hueco]) * 1000.0)
        j_mejor = int(np.argmin(residuos_ms))
        mejor_residuo = residuos_ms[j_mejor]

        if mejor_residuo <= umbral_residuo_plausible_ms:
            idx_destino = idx_hueco[j_mejor]
            asyn[idx_destino] = (resp_time - stim_times[idx_destino]) * 1000.0
            asyn[i] = np.nan
        else:
            asyn[i] = np.nan
    return asyn


def calcular_tiempo_restablecimiento(asinc_ms, stim_times_s,
                                      t_perturbacion_s,
                                      ventana_baseline_n=15,
                                      sigma_factor=1.0,
                                      n_consecutivos=3):
    a = np.asarray(asinc_ms, dtype=float)
    t = np.asarray(stim_times_s, dtype=float)

    resultado_vacio = {
        'Tr_beats': None, 'Tr_ms': None,
        'mu_baseline_ms': None, 'sigma_baseline_ms': None,
        'idx_perturbacion': None, 'lim_inf_ms': None,
        'lim_sup_ms': None, 'n_baseline_valido': 0
    }

    if len(a) != len(t) or len(a) < ventana_baseline_n + n_consecutivos:
        return resultado_vacio

    idx_pert = int(np.searchsorted(t, t_perturbacion_s))
    if idx_pert < ventana_baseline_n:
        idx_pert = ventana_baseline_n
    if idx_pert >= len(a):
        resultado_vacio['idx_perturbacion'] = idx_pert
        return resultado_vacio

    baseline = a[max(0, idx_pert - ventana_baseline_n): idx_pert]
    baseline = baseline[~np.isnan(baseline)]
    n_baseline_valido = len(baseline)

    if n_baseline_valido < 3:
        resultado_vacio['idx_perturbacion'] = idx_pert
        return resultado_vacio

    mu_b    = float(np.mean(baseline))
    sigma_b = float(np.std(baseline))
    lim_inf = mu_b - sigma_factor * sigma_b
    lim_sup = mu_b + sigma_factor * sigma_b

    post     = a[idx_pert:]
    en_rango = (post >= lim_inf) & (post <= lim_sup) & ~np.isnan(post)

    Tr_beats = None
    for k in range(len(en_rango) - n_consecutivos + 1):
        if np.all(en_rango[k: k + n_consecutivos]):
            Tr_beats = k + 1
            break

    Tr_ms = None
    if Tr_beats is not None and idx_pert + Tr_beats < len(t):
        Tr_ms = float((t[idx_pert + Tr_beats] - t[idx_pert]) * 1000.0)

    return {
        'Tr_beats':          Tr_beats,
        'Tr_ms':             round(Tr_ms, 2)    if Tr_ms    is not None else None,
        'mu_baseline_ms':    round(mu_b, 3),
        'sigma_baseline_ms': round(sigma_b, 3),
        'lim_inf_ms':        round(lim_inf, 3),
        'lim_sup_ms':        round(lim_sup, 3),
        'idx_perturbacion':  idx_pert,
        'n_baseline_valido': n_baseline_valido
    }


def _calcular_tr_por_seccion(seccion_asinc, seccion_stim, sigma_factor=1.0, n_consecutivos=3):
    """
    Tr para un tramo de BPM fijo (PA/PR), usando como baseline la segunda
    mitad del propio tramo (se asume estable hacia el final de la secciÃ³n).
    A diferencia de calcular_tiempo_restablecimiento (que usa una ventana
    fija ANTES de la perturbaciÃ³n), acÃ¡ la perturbaciÃ³n es el inicio del
    tramo y el baseline se toma DEL MISMO tramo, por eso va aparte.
    """
    seccion_asinc = np.asarray(seccion_asinc, dtype=float)
    mitad = len(seccion_asinc) // 2
    baseline = seccion_asinc[mitad:]
    baseline = baseline[~np.isnan(baseline)]

    mu_base    = float(np.nanmean(baseline)) if len(baseline) else np.nan
    sigma_base = float(np.nanstd(baseline))  if len(baseline) else np.nan
    lim_inf    = mu_base - sigma_factor * sigma_base
    lim_sup    = mu_base + sigma_factor * sigma_base

    en_rango = (seccion_asinc >= lim_inf) & (seccion_asinc <= lim_sup) & ~np.isnan(seccion_asinc)

    Tr_beats = None
    for k in range(len(en_rango) - (n_consecutivos - 1)):
        if np.all(en_rango[k:k + n_consecutivos]):
            Tr_beats = k + 1
            break

    Tr_ms = None
    if Tr_beats is not None and Tr_beats < len(seccion_stim):
        Tr_ms = (seccion_stim[Tr_beats] - seccion_stim[0]) * 1000.0

    # â”€â”€ Deriva de perÃ­odo (drift): pendiente de la asincronÃ­a vs. tiempo a
    # lo largo de TODA la secciÃ³n (BPM1, BPM2 o ISO completa), sin
    # discriminar por Tr. FenÃ³meno distinto de Tr: Tr mide la velocidad de
    # reajuste de FASE tras la perturbaciÃ³n; esto mide si el PERÃODO del
    # sujeto queda descalibrado respecto al del estÃ­mulo de forma sostenida
    # a lo largo de todo el tramo.
    mask_v  = ~np.isnan(seccion_asinc)
    deriva_ms_s = None
    deriva_r    = None
    if mask_v.sum() >= 3:
        slope, intercept, r_value, p_value, _ = linregress(seccion_stim[mask_v], seccion_asinc[mask_v])
        deriva_ms_s = float(slope)
        deriva_r    = float(r_value)

    return {
        'Tr_beats':          Tr_beats,
        'Tr_ms':             round(Tr_ms, 2) if Tr_ms is not None else None,
        'mu_baseline_ms':    round(mu_base, 3)    if not np.isnan(mu_base)    else None,
        'sigma_baseline_ms': round(sigma_base, 3) if not np.isnan(sigma_base) else None,
        'lim_inf_ms':        round(lim_inf, 3)    if not np.isnan(lim_inf)    else None,
        'lim_sup_ms':        round(lim_sup, 3)    if not np.isnan(lim_sup)    else None,
        'idx_perturbacion':  0,
        'n_baseline_valido': int(len(baseline)),
        'deriva_ms_s':       round(deriva_ms_s, 4) if deriva_ms_s is not None else None,
        'deriva_r':          round(deriva_r, 4)    if deriva_r    is not None else None,
    }




# ==============================================================================
# [AD-3] PENDIENTE DE ADAPTACIÃ“N (slope) DURANTE RAMPA PR
# ==============================================================================

def calcular_pendiente_adaptacion(asinc_ms, stim_times_s,
                                   t_rampa_ini_s, t_rampa_fin_s):
    """
    [AD-3] Calcula la pendiente de adaptaciÃ³n durante la rampa de un metrÃ³nomo PR:
    regresiÃ³n lineal de asincronÃ­a vs. tiempo dentro del tramo de rampa.

    InterpretaciÃ³n (Droit-Volet & Meck, 2007):
      Pendiente negativa â†’ el sujeto se adelanta progresivamente (anticipa bien).
      Pendiente â‰ˆ 0      â†’ no hay seguimiento de la rampa.
      Pendiente positiva â†’ el sujeto se atrasa progresivamente (reacciÃ³n tardÃ­a).

    Args:
        asinc_ms       : array de asincronÃ­as en ms (cronolÃ³gico).
        stim_times_s   : array de tiempos de estÃ­mulos en segundos (misma longitud).
        t_rampa_ini_s  : tiempo de inicio de la rampa [s].
        t_rampa_fin_s  : tiempo de fin de la rampa [s].
    Returns:
        dict con 'slope_ms_per_s', 'r_squared', 'n', 'mean_asinc_rampa_ms'.
        None si no hay datos en el tramo.
    """
    a = np.asarray(asinc_ms, dtype=float)
    t = np.asarray(stim_times_s, dtype=float)

    mask_rampa = (t >= t_rampa_ini_s) & (t <= t_rampa_fin_s) & ~np.isnan(a)

    if np.sum(mask_rampa) < 3:
        return {'slope_ms_per_s': None, 'r_squared': None,
                'n': int(np.sum(mask_rampa)), 'mean_asinc_rampa_ms': None}

    t_r = t[mask_rampa]
    a_r = a[mask_rampa]

    slope, _, r_value, p_value, _ = linregress(t_r, a_r)

    return {
        'slope_ms_per_s':      round(float(slope), 4),
        'r_squared':           round(float(r_value**2), 4),
        'p_value':             round(float(p_value), 4),
        'n':                   int(np.sum(mask_rampa)),
        'mean_asinc_rampa_ms': round(float(np.mean(a_r)), 3)
    }


# ==============================================================================
# â”€â”€ Cruce descendente entre cada pico alto y su pico bajo â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# ==============================================================================

def encontrar_cruce_descendente(signal_values, peak_a_idx, peak_b_idx, umbral, margen_extra=15):
    """
    Dentro del segmento entre un pico alto y su pico bajo,
    encuentra el Ãºltimo Ã­ndice donde la seÃ±al cruza el umbral en bajada.

    Si ese segmento no tiene ningÃºn cruce (tap de amplitud chica que no
    llega al umbral global), amplÃ­a la ventana unos frames mÃ¡s allÃ¡ del
    pico bajo y toma el PRIMER cruce descendente ahÃ­ -- en vez de saltar
    directo al pico bajo, que puede quedar bastante corrido en el tiempo.
    Solo si ni ampliando la ventana aparece un cruce, se devuelve NaN --
    no se inventa un punto por encima del umbral, que violarÃ­a la propia
    definiciÃ³n de "cruce descendente".
    """
    segment = signal_values[peak_a_idx:peak_b_idx+1]
    sobre_umbral = segment >= umbral
    cruces = np.where(np.diff(sobre_umbral.astype(int)) == -1)[0]  # bajadas

    if len(cruces) > 0:
        # Tomar el Ãºltimo cruce descendente (el mÃ¡s cercano al pico bajo)
        cruce_idx = cruces[-1]
        y1 = segment[cruce_idx]
        y2 = segment[cruce_idx + 1]
        fraccion = 0.0 if abs(y1 - y2) < 1e-9 else (y1 - umbral) / (y1 - y2)
        return peak_a_idx + cruce_idx + fraccion

    # Sin cruce en el segmento normal: ampliar la ventana mÃ¡s allÃ¡ del pico
    # bajo y buscar el PRIMER cruce descendente ahÃ­.
    fin_extendido = min(peak_b_idx + margen_extra, len(signal_values) - 1)
    segment_ext = signal_values[peak_a_idx:fin_extendido + 1]
    sobre_umbral_ext = segment_ext >= umbral
    cruces_ext = np.where(np.diff(sobre_umbral_ext.astype(int)) == -1)[0]

    if len(cruces_ext) > 0:
        cruce_idx = cruces_ext[0]   # el PRIMERO, no el Ãºltimo
        y1 = segment_ext[cruce_idx]
        y2 = segment_ext[cruce_idx + 1]
        fraccion = 0.0 if abs(y1 - y2) < 1e-9 else (y1 - umbral) / (y1 - y2)
        return peak_a_idx + cruce_idx + fraccion

    return np.nan


def calibrar_deriva_reloj_camara(audio_relevant, sample_rate, stim_times,
                                  banda_hz=(1800, 2200), min_clicks=15,
                                  ventana_pareo_s=0.15, umbral_onset=0.3,
                                  n_mad_outlier=4.0):
    """
    Mide el sesgo de TASA del reloj de la cÃ¡mara comparando el estÃ­mulo
    real (stim_times, del .wav -- ya confirmado preciso contra el tiempo
    real, error ~0.02%) contra ese mismo estÃ­mulo tal como lo capta el
    micrÃ³fono de la cÃ¡mara, aislado en una banda angosta alrededor de la
    frecuencia caracterÃ­stica del click del metrÃ³nomo (~2000Hz) -- mucho
    mÃ¡s limpio que detectar el bleed sobre el resto del espectro.

    Se usa el ONSET del click (primer cruce de umbral_onset hacia arriba),
    no su pico -- el click no es un pulso instantÃ¡neo, dura varias
    decenas de ms con oscilaciones internas de amplitud parecida, y
    quedarse con "el punto mÃ¡s alto" hace que el punto elegido salte
    entre distintas partes internas del mismo click de sesiÃ³n a sesiÃ³n
    (o incluso beat a beat), degradando mucho la precisiÃ³n (confirmado:
    rÂ² subiÃ³ de ~0.75 a ~0.997 al cambiar de pico a onset, en una sesiÃ³n
    de prueba real). El onset (arranque) es mucho mÃ¡s estable porque no
    depende de cuÃ¡l oscilaciÃ³n interna resultÃ³ mÃ¡s alta.

    [Se probÃ³ restringir el ajuste a los primeros N estÃ­mulos (zona mÃ¡s
    confiable), pero empeorÃ³ el rÂ² -- no por peor calidad de datos, sino
    porque un rango de TIEMPO chico hace que el mismo ruido de mediciÃ³n
    (unos pocos ms por click) pese mucho mÃ¡s relativo al rango total, y
    rÂ² cae aunque la pendiente en sÃ­ sea igual de vÃ¡lida. Con TODA la
    sesiÃ³n (rango de tiempo amplio), ese mismo ruido pesa menos, dando un
    rÂ² mejor -- siempre que se filtren los puntos realmente contaminados
    (zonas de bleed dÃ©bil, tÃ­picamente la secciÃ³n de menor BPM en PA/PR)
    en vez de simplemente recortar la ventana temporal.]

    El filtrado de contaminados se hace por RESIDUO respecto a un ajuste
    robusto (Theil-Sen -- mediana de pendientes por pares, poco sensible
    a un grupo de outliers), no por umbral de amplitud: se calcula esa
    recta robusta, se mide cuÃ¡nto se aleja cada punto de ella, y se
    descartan los que superan n_mad_outlier veces la MAD de los
    residuos. El ajuste final (el que se reporta) es un mÃ­nimos cuadrados
    estÃ¡ndar sobre los puntos que sobrevivieron ese filtro.

    Devuelve dict con slope_ms_s, r2, n_detectados, aplicable (bool).
    Si hay menos de min_clicks puntos limpios tras el filtro, o el ajuste
    es de mala calidad (rÂ² bajo), aplicable=False y no debe usarse la
    correcciÃ³n.
    """
    nyquist = sample_rate / 2
    b_bp, a_bp = signal.butter(4, [banda_hz[0]/nyquist, banda_hz[1]/nyquist], btype='band')
    audio_banda = signal.filtfilt(b_bp, a_bp, audio_relevant)
    pico_max = np.max(np.abs(audio_banda))
    envolvente = np.abs(audio_banda) / pico_max if pico_max > 0 else np.abs(audio_banda)

    ventana_muestras = int(sample_rate * ventana_pareo_s)
    offsets_ms, tiempos_s = [], []
    for t in stim_times:
        idx_centro = int(t * sample_rate)
        ini, fin = max(0, idx_centro - ventana_muestras), idx_centro + ventana_muestras
        if fin > len(envolvente):
            fin = len(envolvente)
        seg = envolvente[ini:fin]
        if len(seg) == 0 or seg.max() < umbral_onset:
            continue
        cruces_onset = np.where(seg >= umbral_onset)[0]
        idx_onset = ini + cruces_onset[0]   # PRIMER cruce hacia arriba, no el pico
        t_onset_s = idx_onset / sample_rate
        offsets_ms.append((t_onset_s - t) * 1000)
        tiempos_s.append(t)

    n = len(offsets_ms)
    if n < min_clicks:
        print(f"  [CalibraciÃ³n de reloj] Solo {n} clicks detectados en banda "
              f"{banda_hz[0]}-{banda_hz[1]}Hz (mÃ­nimo {min_clicks}) -- no se aplica correcciÃ³n.")
        return {'slope_ms_s': None, 'r2': None, 'n_detectados': n, 'aplicable': False}

    offsets_arr = np.asarray(offsets_ms)
    tiempos_arr = np.asarray(tiempos_s)

    # Ajuste robusto inicial (Theil-Sen) solo para IDENTIFICAR outliers --
    # no es el que se reporta ni se usa para corregir.
    slope_rob, intercept_rob, _, _ = theilslopes(offsets_arr, tiempos_arr)
    residuos = offsets_arr - (slope_rob * tiempos_arr + intercept_rob)
    mad = np.median(np.abs(residuos - np.median(residuos)))
    umbral_residuo = max(3.0, n_mad_outlier * mad)   # piso de 3ms para no ser demasiado estricto en sesiones muy limpias
    mask_inliers = np.abs(residuos - np.median(residuos)) <= umbral_residuo
    n_outliers = int((~mask_inliers).sum())

    n_inliers = int(mask_inliers.sum())
    if n_inliers < min_clicks:
        print(f"  [CalibraciÃ³n de reloj] Tras descartar outliers quedaron {n_inliers} puntos "
              f"(mÃ­nimo {min_clicks}) -- no se aplica correcciÃ³n.")
        return {'slope_ms_s': None, 'r2': None, 'n_detectados': n_inliers, 'aplicable': False}

    slope, intercept, r_value, _, _ = linregress(tiempos_arr[mask_inliers], offsets_arr[mask_inliers])
    r2 = r_value ** 2
    aplicable = r2 >= 0.8

    print(f"  [CalibraciÃ³n de reloj] n={n} detectados | outliers descartados={n_outliers} "
          f"(residuo > {umbral_residuo:.1f}ms) | n usados={n_inliers} | pendiente={slope:+.4f} ms/s | "
          f"rÂ²={r2:.4f} | {'SE APLICA' if aplicable else 'NO se aplica (rÂ² bajo)'}")

    return {'slope_ms_s': float(slope), 'intercept_ms': float(intercept),
            'r2': r2, 'n_detectados': n_inliers, 'aplicable': aplicable}


def _ajustar_recta_robusta(tiempos_arr, offsets_arr, min_clicks=15, n_mad_outlier=4.0,
                            umbral_r2=0.8, umbral_residuo_absoluto_ms=25.0, etiqueta=''):
    """
    Mismo criterio robusto que calibrar_deriva_reloj_camara (Theil-Sen
    para identificar outliers + descarte por MAD + ajuste final por
    mÃ­nimos cuadrados) pero aplicado sobre offsets YA DETECTADOS, en vez
    de detectar clicks desde cero con el mÃ©todo de umbral/onset.

    Se separÃ³ como funciÃ³n aparte porque calibrar_deriva_reloj_camara
    usa su propio detector interno (umbral absoluto + onset), que es
    frÃ¡gil ante cualquier sonido fuerte dentro de la ventana que se le
    pase -- normaliza contra el pico mÃ¡ximo de TODO lo que recibe, asÃ­
    que un solo evento ruidoso (golpe, ruido de fondo, no
    necesariamente de la secciÃ³n vecina) puede tapar el resto (confirmado
    con evidencia directa: "0 clicks detectados" en una secciÃ³n real
    incluso despuÃ©s de recortar el audio a la ventana de esa secciÃ³n,
    mientras que _detectar_offset_audio_bleed -- Viterbi + envolvente de
    Hilbert, mucho mÃ¡s robusto a este tipo de interferencia -- sÃ­
    encontraba seÃ±al limpia ahÃ­ sin problema). Reutilizar esos mismos
    offsets ya detectados, en vez de re-detectar con el mÃ©todo viejo,
    evita heredar esa fragilidad.

    [aplicable] NO depende solo de rÂ² -- se acepta tambiÃ©n si el RUIDO
    RESIDUAL ABSOLUTO es chico (std de los residuos, en ms, no relativo a
    la pendiente). Motivo (confirmado con evidencia directa, mismo
    fenÃ³meno ya documentado en calibrar_deriva_reloj_camara): en una
    secciÃ³n de tiempo CORTA, el drift de reloj explica muy poca variaciÃ³n
    total (unos pocos ms en 15-20s), asÃ­ que aunque los datos sean tan
    consistentes como en una secciÃ³n mÃ¡s larga, el rÂ² de una regresiÃ³n
    lineal sale bajo simplemente porque hay poco que "explicar" -- no
    porque los datos sean malos (confirmado visualmente: BPM2 con
    rÂ²=0.25 pero datos apretados en una banda de ~20ms, indistinguibles a
    ojo de BPM1, que sÃ­ pasaba con rÂ²=0.997 solo por tener una ventana de
    tiempo mÃ¡s larga). El criterio de residuo absoluto captura
    directamente "Â¿son consistentes los datos?" sin depender de cuÃ¡nto
    dura la secciÃ³n.

    Devuelve el mismo formato que calibrar_deriva_reloj_camara, mÃ¡s
    'mask_inliers': array booleano del MISMO largo que offsets_arr
    (posiciones originales), True donde el punto se usÃ³ en el ajuste
    final (pasÃ³ el filtro de outliers) -- Ãºtil para excluir esos mismos
    outliers tambiÃ©n de otros usos posteriores de estos offsets, no solo
    del cÃ¡lculo de la pendiente.
    """
    mask_validos = ~np.isnan(offsets_arr)
    n_validos = int(mask_validos.sum())
    mask_inliers_completa = np.zeros(len(offsets_arr), dtype=bool)
    if n_validos < min_clicks:
        print(f"  [Ajuste robusto{f' {etiqueta}' if etiqueta else ''}] Solo {n_validos} puntos vÃ¡lidos "
              f"(mÃ­nimo {min_clicks}) -- no se aplica.")
        return {'slope_ms_s': None, 'r2': None, 'n_detectados': n_validos, 'aplicable': False,
                'mask_inliers': mask_inliers_completa}

    t_validos = tiempos_arr[mask_validos]
    o_validos = offsets_arr[mask_validos]

    slope_rob, intercept_rob, _, _ = theilslopes(o_validos, t_validos)
    residuos = o_validos - (slope_rob * t_validos + intercept_rob)
    mediana_res = np.median(residuos)
    mad = np.median(np.abs(residuos - mediana_res))
    umbral_residuo = max(3.0, n_mad_outlier * mad)
    mask_inliers = np.abs(residuos - mediana_res) <= umbral_residuo
    n_outliers = int((~mask_inliers).sum())
    n_inliers = int(mask_inliers.sum())

    idx_validos = np.where(mask_validos)[0]
    mask_inliers_completa[idx_validos[mask_inliers]] = True

    if n_inliers < min_clicks:
        print(f"  [Ajuste robusto{f' {etiqueta}' if etiqueta else ''}] Tras descartar outliers quedaron "
              f"{n_inliers} puntos (mÃ­nimo {min_clicks}) -- no se aplica.")
        return {'slope_ms_s': None, 'r2': None, 'n_detectados': n_inliers, 'aplicable': False,
                'mask_inliers': mask_inliers_completa}

    slope, intercept, r_value, _, _ = linregress(t_validos[mask_inliers], o_validos[mask_inliers])
    r2 = r_value ** 2
    residuos_finales = o_validos[mask_inliers] - (intercept + slope * t_validos[mask_inliers])
    std_residuo_final = float(np.std(residuos_finales))

    pasa_r2 = r2 >= umbral_r2
    pasa_residuo_absoluto = std_residuo_final <= umbral_residuo_absoluto_ms
    aplicable = pasa_r2 or pasa_residuo_absoluto

    if pasa_r2:
        motivo = 'rÂ² alto'
    elif pasa_residuo_absoluto:
        motivo = f'residuo absoluto chico ({std_residuo_final:.1f}ms <= {umbral_residuo_absoluto_ms}ms)'
    else:
        motivo = f'rÂ² bajo y residuo absoluto grande ({std_residuo_final:.1f}ms)'

    print(f"  [Ajuste robusto{f' {etiqueta}' if etiqueta else ''}] n={n_validos} detectados | "
          f"outliers descartados={n_outliers} (residuo > {umbral_residuo:.1f}ms) | n usados={n_inliers} | "
          f"pendiente={slope:+.4f} ms/s | rÂ²={r2:.4f} | std_residuo={std_residuo_final:.1f}ms | "
          f"{'SE APLICA' if aplicable else 'NO se aplica'} ({motivo})")

    return {'slope_ms_s': float(slope), 'intercept_ms': float(intercept),
            'r2': r2, 'n_detectados': n_inliers, 'aplicable': aplicable,
            'mask_inliers': mask_inliers_completa}



def _limites_secciones_tiempo(metadata):
    """
    Devuelve [(label, t_ini, t_fin), ...] en segundos, relativo al inicio
    de la sesiÃ³n (mismo cero que stim_times) -- segÃºn el tipo de
    metrÃ³nomo. Para PR, la rampa queda como SU PROPIA secciÃ³n (aunque no
    tenga un tempo fijo, igual conviene calibrar su sesgo por separado en
    vez de mezclarla con BPM1 o BPM2).
    """
    tipo = metadata.get('tipo_metronomo', 'ISO')
    if tipo == 'ISO':
        return [('ISO', 0.0, np.inf)]
    elif tipo == 'PA':
        bpm_1 = metadata['bpm_1']
        dur_1 = metadata['clics_1'] * (60.0 / bpm_1)
        return [('bpm1', 0.0, dur_1), ('bpm2', dur_1, np.inf)]
    else:  # PR
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        clics_1, clics_r = metadata['clics_1'], metadata['clics_rampa']
        dur_1 = clics_1 * (60.0 / bpm_1)
        dur_r = _calcular_tiempo_rampa(bpm_1, bpm_2, clics_r)
        return [('bpm1', 0.0, dur_1), ('rampa', dur_1, dur_1 + dur_r),
                ('bpm2', dur_1 + dur_r, np.inf)]


# ==============================================================================
# [FIX-RAMPA] CORRECCIÃ“N DE stim_times POR DIVERGENCIA .wav vs ESTÃMULO REAL
# ==============================================================================

def _detectar_offset_audio_bleed(stim_times, audio_relevant, sample_rate,
                                  banda_hz=(1800, 2200), ventana_pareo_s=0.4,
                                  pct_pico_minimo=0.15, frac_isi_max=0.45,
                                  n_candidatos_max=4, peso_continuidad=1.0,
                                  peso_amplitud=5.0):
    """
    [FIX-RAMPA] Para cada estÃ­mulo del .wav, detecta el offset [ms] entre
    el bleed del metrÃ³nomo en el audio de la cÃ¡mara (banda ~2000Hz) y ese
    estÃ­mulo, usando una decodificaciÃ³n TIPO VITERBI sobre varios
    candidatos por beat -- no "el pico mÃ¡s potente" de forma
    independiente beat a beat.

    Motivo del rediseÃ±o: la versiÃ³n anterior (pico mÃ¡s alto dentro de una
    ventana, elegido de forma aislada por beat) es un criterio SIN
    MEMORIA -- cualquier sonido que por azar suene mÃ¡s fuerte que el
    click real dentro de esa ventana (el golpe del tapping, un eco, ruido
    de fondo) le "gana" al click verdadero, sin que el algoritmo tenga
    forma de saberlo. Ajustar la ventana (ISI local) y suavizar despuÃ©s
    (mediana mÃ³vil) redujo la frecuencia de estos saltos, pero no la
    causa: seguÃ­an apareciendo saltos aislados en sesiones nuevas
    (confirmado repetidamente: valores como +50.9ms o +28.3ms rodeados de
    vecinos en +14ms o +2-5ms, en sesiones PA/PR distintas) porque el
    suavizado posterior no puede recuperar una elecciÃ³n ya equivocada si
    el pico "ganador" quedÃ³ lejos del real.

    Este mÃ©todo en cambio:
      1. Para cada beat, detecta varios picos CANDIDATOS (no solo el mÃ¡s
         alto) dentro de su ventana local (find_peaks con una prominencia
         mÃ­nima), hasta n_candidatos_max, ordenados por amplitud.
      2. Resuelve, para TODA la secuencia a la vez, quÃ© candidato elegir
         en cada beat, minimizando un costo conjunto:
           costo = -peso_amplitud*log(amplitud_normalizada)      [preferir picos fuertes]
                 + peso_continuidad*(offset_i - offset_(i-1))Â² / Î”t  [preferir secuencias suaves]
         Un pico aislado mÃ¡s fuerte pero inconsistente con sus vecinos
         deja de "ganar" automÃ¡ticamente -- compite contra la opciÃ³n de
         mantener continuidad con el resto de la secuencia. La divisiÃ³n
         por Î”t tolera mÃ¡s diferencia cuando hay huecos entre beats con
         detecciÃ³n vÃ¡lida (ej. tramos de bleed dÃ©bil).
      3. Se resuelve con programaciÃ³n dinÃ¡mica (Viterbi): O(n_beats Ã—
         n_candidatosÂ²), backtracking desde el Ãºltimo beat con datos.

    Se descartan directamente (sin candidatos) los beats donde ningÃºn
    pico local supera pct_pico_minimo del pico mÃ¡ximo de TODA la sesiÃ³n
    -- ahÃ­ no hay bleed real detectable.

    La ventana de bÃºsqueda se LIMITA dinÃ¡micamente a frac_isi_max del ISI
    LOCAL de cada beat (ver historial: una ventana fija resultaba mÃ¡s
    ancha que el propio ISI en tempos rÃ¡pidos, mezclando con el click
    vecino; y usar el ISI mÃ­nimo GLOBAL en vez de local limitaba de mÃ¡s
    la ventana en tramos lentos de sesiones con tempo mixto como PR).

    NOTA: esta funciÃ³n queda disponible como herramienta de DIAGNÃ“STICO
    manual (no se llama automÃ¡ticamente desde run_analysis). El pipeline
    usa siempre el .wav como Ãºnica referencia para stim_times -- ver
    discusiÃ³n en el historial sobre por quÃ© se decidiÃ³ no corregir
    automÃ¡ticamente (riesgo de bugs sucesivos en cada intento de
    correcciÃ³n beat-a-beat o por secciÃ³n, sin evidencia todavÃ­a de que el
    problema sea sistemÃ¡tico en la mayorÃ­a de las sesiones).

    Devuelve array de offsets en ms, mismo largo que stim_times, con NaN
    donde no hubo ningÃºn candidato confiable.
    """
    nyquist = sample_rate / 2
    b_bp, a_bp = signal.butter(4, [banda_hz[0]/nyquist, banda_hz[1]/nyquist], btype='band')
    audio_banda = signal.filtfilt(b_bp, a_bp, audio_relevant)
    # Envolvente SUAVE (Hilbert), no |seÃ±al| cruda -- la seÃ±al filtrada
    # rectificada oscila a casi el doble de la frecuencia de la banda
    # (rizado de ~4kHz dentro de cada click), y find_peaks sobre esa seÃ±al
    # cruda detecta DECENAS de micro-picos por click (el rizado), no un
    # pico limpio -- confirmado con un test sintÃ©tico: con un click
    # espurio mÃ¡s fuerte cerca, los "4 candidatos mÃ¡s fuertes" resultaban
    # ser todos micro-picos del rizado del click espurio, sin que el click
    # real llegara siquiera a figurar entre los candidatos. La envolvente
    # de Hilbert sigue la forma real de amplitud sin ese rizado, dando
    # como mucho un puÃ±ado de picos genuinamente distintos por ventana.
    envolvente = np.abs(signal.hilbert(audio_banda))
    pico_global = np.max(envolvente)

    n = len(stim_times)
    offsets_ms = np.full(n, np.nan)
    if pico_global <= 0 or n == 0:
        return offsets_ms

    # ISI local por beat: distancia al vecino mÃ¡s cercano (anterior o
    # siguiente), no un Ãºnico mÃ­nimo para toda la sesiÃ³n.
    isi_local_s = np.full(n, np.inf)
    if n >= 2:
        diffs = np.diff(stim_times)
        isi_local_s[0] = diffs[0]
        isi_local_s[-1] = diffs[-1]
        if n > 2:
            isi_local_s[1:-1] = np.minimum(diffs[:-1], diffs[1:])

    ventana_local_s = np.minimum(ventana_pareo_s, frac_isi_max * isi_local_s)
    n_reducidos = int(np.sum(ventana_local_s < ventana_pareo_s))
    if n_reducidos > 0:
        print(f"  [FIX-RAMPA] Ventana de bÃºsqueda reducida (ISI local mÃ¡s angosto que "
              f"{ventana_pareo_s*1000:.0f}ms) en {n_reducidos} de {n} beats -- "
              f"evita solapar con el click vecino en tramos de tempo rÃ¡pido.")

    umbral_prominencia = pct_pico_minimo * pico_global
    distancia_min_muestras = max(1, int(sample_rate * 0.01))   # 10ms: separa clicks distintos, no ripple

    # --- Paso 1: candidatos por beat (no solo el mÃ¡s fuerte) -----------------
    candidatos_offset = []
    candidatos_amp = []
    for i, t in enumerate(stim_times):
        ventana_muestras = int(sample_rate * ventana_local_s[i])
        idx_centro = int(t * sample_rate)
        ini, fin = max(0, idx_centro - ventana_muestras), min(len(envolvente), idx_centro + ventana_muestras)
        seg = envolvente[ini:fin]
        if len(seg) == 0:
            candidatos_offset.append(np.array([])); candidatos_amp.append(np.array([]))
            continue
        picos_idx, _ = find_peaks(seg, prominence=umbral_prominencia * 0.5,
                                   height=umbral_prominencia, distance=distancia_min_muestras)
        if len(picos_idx) == 0:
            candidatos_offset.append(np.array([])); candidatos_amp.append(np.array([]))
            continue
        amps = seg[picos_idx]
        orden = np.argsort(amps)[::-1][:n_candidatos_max]
        picos_idx_top = picos_idx[orden]
        t_pico = (ini + picos_idx_top) / sample_rate
        candidatos_offset.append((t_pico - t) * 1000.0)
        candidatos_amp.append(amps[orden] / pico_global)

    # --- Paso 2: Viterbi -- camino mÃ¡s coherente entre candidatos ------------
    dp = [None] * n
    back = [None] * n
    prev_idx_arr = [-1] * n

    primer_valido = next((i for i in range(n) if len(candidatos_offset[i]) > 0), None)
    if primer_valido is None:
        return offsets_ms   # ningÃºn candidato en toda la sesiÃ³n

    dp[primer_valido] = np.array([-peso_amplitud * np.log(a + 1e-6) for a in candidatos_amp[primer_valido]])
    back[primer_valido] = [-1] * len(candidatos_offset[primer_valido])
    ultimo_valido = primer_valido

    for i in range(primer_valido + 1, n):
        if len(candidatos_offset[i]) == 0:
            continue
        prev_idx_arr[i] = ultimo_valido
        costos_prev = dp[ultimo_valido]
        offsets_prev = candidatos_offset[ultimo_valido]
        dt = max(stim_times[i] - stim_times[ultimo_valido], 0.1)

        dp_i = np.empty(len(candidatos_offset[i]))
        back_i = [0] * len(candidatos_offset[i])
        for k, (off_k, amp_k) in enumerate(zip(candidatos_offset[i], candidatos_amp[i])):
            costo_amplitud = -peso_amplitud * np.log(amp_k + 1e-6)
            costos_transicion = costos_prev + peso_continuidad * ((off_k - offsets_prev) ** 2) / dt
            j = int(np.argmin(costos_transicion))
            dp_i[k] = costos_transicion[j] + costo_amplitud
            back_i[k] = j
        dp[i] = dp_i
        back[i] = back_i
        ultimo_valido = i

    # --- Backtracking ----------------------------------------------------------
    idx_validos = [i for i in range(n) if dp[i] is not None]
    i_cur = idx_validos[-1]
    k_cur = int(np.argmin(dp[i_cur]))
    offsets_ms[i_cur] = candidatos_offset[i_cur][k_cur]
    while prev_idx_arr[i_cur] != -1:
        i_prev = prev_idx_arr[i_cur]
        k_prev = back[i_cur][k_cur]
        offsets_ms[i_prev] = candidatos_offset[i_prev][k_prev]
        i_cur, k_cur = i_prev, k_prev

    return offsets_ms



def _calibrar_sesgo_track_audio(signal_values, tip_peaks_a, tip_peaks_b, frame_ts_real_ms, fps,
                                 tapping_signal, metadata, sample_rate, stim_times, start_time,
                                 pct_fijo=15, ventana_pareo_s=0.15, min_pares_seccion=5):
    """
    El umbral de cruce queda FIJO (pct_fijo% del recorrido de cada tap,
    igual para todas las sesiones) -- mantiene la estabilidad conocida de
    ese criterio, sin la variabilidad de sesiÃ³n a sesiÃ³n que tenÃ­a elegir
    un % distinto cada vez.

    En cambio, se calibra un SESGO CONSTANTE (mediana del offset
    track-audio) POR SECCIÃ“N (BPM1/rampa/BPM2, o toda la sesiÃ³n en ISO) y
    se corrige sumÃ¡ndolo a resp_times -- el desfasaje track-audio puede
    depender del tempo (por ejemplo, cÃ³mo desacelera el dedo antes de
    tocar puede variar con la velocidad del tapping), asÃ­ que un Ãºnico
    sesgo global serÃ­a un compromiso entre tramos, no lo mejor para cada
    uno. Si una secciÃ³n no junta suficientes pares (p.ej. la rampa, corta),
    cae al sesgo GLOBAL de toda la sesiÃ³n como respaldo.

    A diferencia de cambiar el porcentaje del umbral (que mueve sesgo y
    ruido juntos, mezclados, porque ambos dependen de en quÃ© punto de la
    curva se mide), sumar una constante corrige el sesgo SIN afectar el
    ruido/std en absoluto -- no toca la detecciÃ³n en sÃ­, solo desplaza el
    resultado ya calculado.

    Devuelve un array (uno por tap, mismo largo que tip_peaks_a/b) con el
    sesgo en segundos a sumarle a cada tap, o None si no hay audio
    suficiente para calibrar nada (ni siquiera el global).
    """
    try:
        tramos_seg = _segmentar_tapping(tapping_signal, metadata, sample_rate)
    except Exception:
        return None
    resp_audio_list = []
    for tramo in tramos_seg:
        offset = tramo['offset_muestras']
        t_s = tramo['tapping_peaks'] / sample_rate + (offset / sample_rate if offset > 0 else 0.0)
        resp_audio_list.append(t_s)
    resp_audio_ref = np.sort(np.concatenate(resp_audio_list)) if resp_audio_list else np.array([])

    if len(resp_audio_ref) < 10:
        return None

    n_taps = min(len(tip_peaks_a), len(tip_peaks_b))
    tiempos = np.full(n_taps, np.nan)
    for i in range(n_taps):
        # Ciclo faltante (ver tip_peaks_a_pareo/tip_peaks_b_pareo en
        # run_analysis) -- se deja como NaN, no hay pico real del cual
        # partir para calcular un cruce.
        if tip_peaks_a[i] is None or tip_peaks_b[i] is None:
            continue
        if isinstance(tip_peaks_a[i], float) and np.isnan(tip_peaks_a[i]):
            continue
        if isinstance(tip_peaks_b[i], float) and np.isnan(tip_peaks_b[i]):
            continue
        pa, pb = int(tip_peaks_a[i]), int(tip_peaks_b[i])
        if pa >= pb:
            continue
        seg = signal_values[pa:pb + 1]
        if seg.max() <= seg.min():
            continue
        umbral_tap = seg.min() + (seg.max() - seg.min()) * (pct_fijo / 100.0)
        cruce = encontrar_cruce_descendente(signal_values, pa, pb, umbral_tap)
        t_ms = np.interp(cruce, np.arange(len(frame_ts_real_ms)), frame_ts_real_ms)
        tiempos[i] = t_ms / 1000.0 - start_time

    def _diffs_en_rango(t_ini, t_fin):
        diffs = []
        for t in tiempos:
            if np.isnan(t) or t < t_ini or t >= t_fin:
                continue
            idx_cercano = np.argmin(np.abs(resp_audio_ref - t))
            dist = resp_audio_ref[idx_cercano] - t   # audio - track: positivo si el track estÃ¡ adelantado
            if abs(dist) < ventana_pareo_s:
                diffs.append(dist)
        return diffs

    diffs_global = _diffs_en_rango(-np.inf, np.inf)
    if len(diffs_global) < 10:
        return None
    sesgo_global = float(np.median(diffs_global))

    secciones = _limites_secciones_tiempo(metadata)
    sesgo_por_tap = np.full(n_taps, sesgo_global)   # default: sesgo global para toda la sesiÃ³n

    for label, t_ini, t_fin in secciones:
        diffs_sec = _diffs_en_rango(t_ini, t_fin)
        if len(diffs_sec) >= min_pares_seccion:
            sesgo_sec = float(np.median(diffs_sec))
        else:
            sesgo_sec = sesgo_global   # secciÃ³n sin datos suficientes: usa el respaldo global
        mask_sec = (~np.isnan(tiempos)) & (tiempos >= t_ini) & (tiempos < t_fin)
        sesgo_por_tap[mask_sec] = sesgo_sec
        print(f"  [Sesgo track-audio] {label}: sesgo={sesgo_sec*1000:+.1f}ms "
              f"({'calibrado con n=' + str(len(diffs_sec)) if len(diffs_sec) >= min_pares_seccion else 'respaldo global, pocos pares'})")

    return sesgo_por_tap


def _calcular_resp_times_por_cruce(df, tip_peaks_a, tip_peaks_b, fps, start_time,
                                    tapping_signal=None, metadata=None, sample_rate=None,
                                    stim_times=None,
                                    signal_col='tip_y', frac_margen=0.15, pct_fijo=15,
                                    tolerancia_meseta_frac=0.3):
    """resp_times_video: tiempos absolutos [s]. resp_times_s: relativos al inicio del metrÃ³nomo.

    El cruce base se calcula con un umbral fijo al pct_fijo% del recorrido
    de CADA tap individual (0=piso/mesa, 100=techo/aire) -- 100%
    independiente del audio.

    Si hay audio disponible, se calibra ademÃ¡s un sesgo por secciÃ³n (ver
    _calibrar_sesgo_track_audio) y se aplica -- pero SOLO si desplaza el
    cruce hacia ADELANTE en el tiempo (mÃ¡s tarde), nunca hacia atrÃ¡s.
    Esto acota el riesgo del matching de audio, que puede fallar
    silenciosamente (confirmado con evidencia directa: un caso donde
    compute_asyn_ordinal asignÃ³ un "tiempo de audio" con prominencia real
    de solo 0.003, sin corresponder a ningÃºn pico detectado, mientras el
    pico real mÃ¡s cercano -- prominencia 0.74 -- estaba a ~95ms de
    diferencia): en el peor caso, esa correcciÃ³n se ignora para ese beat
    (queda el cruce base, sin empeorar), nunca puede mover un tap a un
    tiempo peor que el que ya tenÃ­a.

    [MESETA SUPERFICIAL] detect_valley_center (que produce tip_peaks_b) no
    valida que el mÃ­nimo local encontrado represente un apoyo real contra
    la mesa -- solo busca "el punto mÃ¡s bajo disponible" entre dos picos
    altos, sin importar quÃ© tan bajo sea. Si en un ciclo puntual el dedo
    no llegÃ³ a bajar lo suficiente (confirmado visualmente: justo en una
    perturbaciÃ³n de tempo, un "pico bajo" quedÃ³ muy por encima del umbral
    normal de la sesiÃ³n, muy por arriba de todos los demÃ¡s), ese mÃ­nimo
    NO es un contacto real -- es simplemente el punto mÃ¡s bajo de un ciclo
    que no bajÃ³ del todo. Usarlo igual para calcular un cruce producirÃ­a
    un tiempo de respuesta engaÃ±oso justo en el tramo mÃ¡s sensible para
    Tr (la reacciÃ³n a la perturbaciÃ³n).

    Se detecta esto comparando el PISO de cada tap (seg.min(), ya
    calculado para el umbral por-tap) contra el piso "normal" de la
    sesiÃ³n (mediana de todos los pisos, robusta a unos pocos casos
    anÃ³malos): si un tap se queda a mÃ¡s de tolerancia_meseta_frac del
    rango de amplitud tÃ­pico por encima de ese piso normal, se considera
    que no hubo apoyo real, y ESE BEAT SE EXCLUYE de resp_times (no se
    inventa un cruce) -- queda como "sin respuesta detectada" para ese
    estÃ­mulo, en vez de contaminar la asincronÃ­a con un valor distorsionado.
    """
    signal_values = df[signal_col].ffill().bfill().to_numpy()
    n_pares = min(len(tip_peaks_a), len(tip_peaks_b))
    frame0 = int(df['frame'].iloc[0])

    ts_real_ms = df['frame_ts_real_ms'].to_numpy() \
        if 'frame_ts_real_ms' in df.columns and not df['frame_ts_real_ms'].isna().all() else None

    def _es_hueco(v):
        return v is None or (isinstance(v, float) and np.isnan(v))

    umbral_por_tap = np.full(n_pares, np.nan)
    piso_por_tap   = np.full(n_pares, np.nan)
    techo_por_tap  = np.full(n_pares, np.nan)
    cruces_b = []
    for i in range(n_pares):
        # Ciclo faltante (pico alto no detectado, ver comentario en
        # run_analysis donde se arman tip_peaks_a_pareo/tip_peaks_b_pareo)
        # -- se preserva como NaN en su posiciÃ³n, no se inventa nada.
        if _es_hueco(tip_peaks_a[i]) or _es_hueco(tip_peaks_b[i]):
            cruces_b.append(np.nan)
            continue
        pa, pb = int(tip_peaks_a[i]), int(tip_peaks_b[i])
        if pa >= pb:
            cruces_b.append(float(pb))
            continue
        seg = signal_values[pa:pb + 1]
        piso_por_tap[i]  = seg.min()
        techo_por_tap[i] = seg.max()
        umbral_tap = seg.min() + (seg.max() - seg.min()) * (pct_fijo / 100.0) \
                    if seg.max() > seg.min() else seg.min()
        umbral_por_tap[i] = umbral_tap
        cruces_b.append(encontrar_cruce_descendente(signal_values, pa, pb, umbral_tap))
    cruces_b = np.array(cruces_b, dtype=float)
    umbral = umbral_base = float(np.nanmean(umbral_por_tap))
    print(f"  Umbral fijo por tap ({pct_fijo}% del recorrido) | promedio de referencia={umbral:.4f}")

    # --- [MESETA SUPERFICIAL] Detectar taps cuyo "pico bajo" no bajÃ³ lo
    # suficiente como para representar un apoyo real -----------------------
    piso_normal  = float(np.nanmedian(piso_por_tap))
    techo_normal = float(np.nanmedian(techo_por_tap))
    amplitud_normal = techo_normal - piso_normal
    mask_meseta_candidata = np.zeros(n_pares, dtype=bool)
    if amplitud_normal > 0:
        umbral_meseta = piso_normal + tolerancia_meseta_frac * amplitud_normal
        mask_meseta_candidata = piso_por_tap > umbral_meseta

    # --- Diferenciar, entre los candidatos a meseta, cuÃ¡les corresponden a
    # un movimiento REAL pero incompleto (MediaPipe detectÃ³ la mano en
    # todos esos frames, y aun asÃ­ no bajÃ³ lo suficiente) de cuÃ¡les
    # simplemente no tienen dato de MediaPipe ahÃ­ -- son dos situaciones
    # distintas con consecuencias distintas: la primera es una decisiÃ³n
    # real ("no hubo apoyo"), que debe bloquear el respaldo de audio (ver
    # fusiÃ³n en run_analysis). La segunda es simple falta de dato -- track
    # nunca "decidiÃ³" nada, no debe bloquear nada, y debe completarse con
    # audio como cualquier otro hueco (sin distinguir si es un beat
    # aislado o varios seguidos -- el criterio es el mismo en ambos
    # casos, por diseÃ±o).
    #
    # Regla: si CUALQUIER frame dentro de la ventana del tap no tuvo
    # detecciÃ³n real de MediaPipe (no un porcentaje, un umbral arbitrario
    # que generarÃ­a casos lÃ­mite ambiguos) -- ese candidato se excluye
    # igual (no se puede confiar en el piso medido, que en ese tramo viene
    # de un relleno artificial, no de una mediciÃ³n real) pero NO cuenta
    # como meseta superficial.
    #
    # Restringido a SOLO los candidatos que ya superaban el umbral de
    # meseta (no se evalÃºa en taps que de todas formas iban a usarse) --
    # evita que esto interfiera con casos ya manejados por otros
    # mecanismos (ej. un track con valor presente pero mal ubicado por un
    # error de tracking distinto, ver fusiÃ³n track+audio).
    mask_sin_tracking_real = np.zeros(n_pares, dtype=bool)
    if 'sin_tracking' in df.columns:
        sin_tracking_arr = df['sin_tracking'].to_numpy()
        for i in np.where(mask_meseta_candidata)[0]:
            if _es_hueco(tip_peaks_a[i]) or _es_hueco(tip_peaks_b[i]):
                continue
            pa, pb = int(tip_peaks_a[i]), int(tip_peaks_b[i])
            if pa >= pb or pb >= len(sin_tracking_arr):
                continue
            if sin_tracking_arr[pa:pb + 1].any():
                mask_sin_tracking_real[i] = True

    mask_meseta_superficial = mask_meseta_candidata & ~mask_sin_tracking_real
    n_sin_tracking_real = int(mask_sin_tracking_real.sum())
    if n_sin_tracking_real > 0:
        print(f"  [Meseta superficial] {n_sin_tracking_real} de {n_pares} taps NO cuentan como "
              f"meseta superficial -- MediaPipe no tuvo detecciÃ³n real en algÃºn frame de esa "
              f"ventana (no una decisiÃ³n real de 'sin apoyo'). Pueden completarse con audio.")

    n_meseta_superficial = int(np.sum(mask_meseta_superficial))
    if n_meseta_superficial > 0:
        print(f"  [Meseta superficial] {n_meseta_superficial} de {n_pares} taps no bajaron lo "
              f"suficiente (piso > {tolerancia_meseta_frac*100:.0f}% del rango tÃ­pico por encima "
              f"del piso normal, CON detecciÃ³n real de MediaPipe en toda la ventana) -- se "
              f"excluyen de resp_times (sin apoyo real detectado).")

    if ts_real_ms is not None:
        # Timestamp real capturado por frame (cap.get(CAP_PROP_POS_MSEC)) en vez
        # de derivarlo de fps fijo -- elimina la deriva residual que quedaba
        # incluso despuÃ©s de corregir fps con la duraciÃ³n de audio (confirmado
        # rÂ²=1.0000 entre timestamp real y frame/fps: es una recta con offset
        # y pendiente ligeramente distintos, no jitter real).
        print("  [resp_times_video: usando TIMESTAMP REAL por frame, no fps fijo]")
        resp_times_video = np.full(len(cruces_b), np.nan)
        mask_cruce_valido = ~np.isnan(cruces_b)
        resp_times_video[mask_cruce_valido] = np.interp(
            cruces_b[mask_cruce_valido], np.arange(len(ts_real_ms)), ts_real_ms) / 1000.0
    else:
        print("  [resp_times_video: SIN timestamp real -- usando frame/fps fijo, el fix NO se aplicÃ³]")
        resp_times_video = frame0 / fps + cruces_b / fps

    if (tapping_signal is not None and metadata is not None
            and sample_rate is not None and stim_times is not None and ts_real_ms is not None):
        sesgo_por_tap = _calibrar_sesgo_track_audio(
            signal_values, tip_peaks_a, tip_peaks_b, ts_real_ms, fps,
            tapping_signal, metadata, sample_rate, stim_times, start_time, pct_fijo=pct_fijo)
        if sesgo_por_tap is not None:
            # Solo adelante: se descarta (clip a 0) cualquier correcciÃ³n
            # que empujarÃ­a el cruce hacia atrÃ¡s en el tiempo.
            sesgo_solo_adelante = np.clip(sesgo_por_tap, 0.0, None)
            n_clipeados = int(np.sum(sesgo_por_tap < 0))
            if n_clipeados > 0:
                print(f"  [Sesgo track-audio] {n_clipeados} de {len(sesgo_por_tap)} taps tenÃ­an "
                      f"correcciÃ³n hacia atrÃ¡s -- se ignorÃ³ para esos (se descartan, no se aplican).")
            resp_times_video = resp_times_video + sesgo_solo_adelante

    # cruces_b y resp_times_video quedan COMPLETOS (sin filtrar) para que
    # los grÃ¡ficos de diagnÃ³stico puedan seguir mostrando quÃ© se detectÃ³ en
    # cada tap, incluidos los descartados.
    #
    # El filtro por meseta superficial deja un HUECO (NaN) en su propia
    # posiciÃ³n, en vez de ELIMINAR la entrada del array. Motivo (confirmado
    # con evidencia directa: un salto artificial de ~250-300ms sostenido en
    # toda la asincronÃ­a posterior a un tap superficial descartado): el
    # matching que consume esto es ORDINAL, 1:1 con stim_times por
    # posiciÃ³n (ver docstring de procesar_asincronias_sesion). Si se
    # ELIMINA una entrada, todas las respuestas siguientes se corren un
    # lugar hacia atrÃ¡s en el array -- quedan comparadas contra el
    # estÃ­mulo equivocado durante el resto de la sesiÃ³n, no solo en el
    # beat puntual sin apoyo real. Dejar un NaN en su lugar preserva la
    # posiciÃ³n de TODO lo que sigue.
    resp_times_video_confiable = resp_times_video.copy()
    resp_times_video_confiable[mask_meseta_superficial] = np.nan
    resp_times_video_confiable[mask_sin_tracking_real] = np.nan

    resp_times_s = resp_times_video_confiable - start_time
    # Mantener el hueco (NaN) en vez de perderlo -- el filtro de "antes del
    # inicio" solo debe sacar tiempos negativos REALES, no los NaN que
    # representan "sin respuesta" en esa posiciÃ³n. Se deja como NaN en su
    # misma posiciÃ³n (no se elimina la entrada) -- eliminarla correrÃ­a la
    # alineaciÃ³n posicional respecto a mask_meseta_superficial (y a
    # cualquier otro array que dependa de la misma indexaciÃ³n por tap),
    # el mismo tipo de bug ya corregido antes en el matching ordinal.
    mask_pre_inicio = (resp_times_s < 0) & ~np.isnan(resp_times_s)
    resp_times_s = np.where(mask_pre_inicio, np.nan, resp_times_s)
    return resp_times_video, resp_times_s, cruces_b, umbral, umbral_base, mask_meseta_superficial



def generar_senal_ideal(df, metadata, fps):
    """Sinusoide ideal en Y, calibrada sobre std(tip_y)."""
    tipo = metadata.get('tipo_metronomo', 'ISO')
    n = len(df)
    t = np.arange(n) / fps
    A = df['tip_y'].std()
    offset = df['tip_y'].mean()
    if tipo == 'ISO':
        ideal_y = offset + A * np.sin(2 * np.pi * (metadata['bpm'] / 60.0) * t)
    elif tipo == 'PA':
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        t_c = metadata['clics_1'] * (60.0 / bpm_1)
        ideal_y = np.where(t <= t_c,
                            offset + A * np.sin(2 * np.pi * (bpm_1 / 60.0) * t),
                            offset + A * np.sin(2 * np.pi * (bpm_2 / 60.0) * t))
    elif tipo == 'PR':
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        dur_1 = metadata['clics_1'] * (60.0 / bpm_1)
        dur_r = _calcular_tiempo_rampa(bpm_1, bpm_2, metadata['clics_rampa'])
        t_r_f = dur_1 + dur_r
        bpm_i = np.where(t <= dur_1, bpm_1,
                 np.where(t <= t_r_f,
                          bpm_1 + (bpm_2 - bpm_1) * (t - dur_1) / (t_r_f - dur_1),
                          bpm_2))
        fase = np.cumsum(2 * np.pi * (bpm_i / 60.0) / fps)
        ideal_y = offset + A * np.sin(fase)
    else:
        ideal_y = np.full(n, offset)
    df['ideal_y'] = ideal_y
    df['ideal_x'] = df['tip_x'].mean()
    return df


def calcular_metricas_movimiento(df, landmark_name, fps, window_length=9, polyorder=3):
    """FunciÃ³n pura: suavidad, armonÃ­a y curvatura. No modifica el DataFrame."""
    xc, yc = f'{landmark_name}_x', f'{landmark_name}_y'
    if xc not in df.columns or yc not in df.columns:
        return np.nan, np.nan, np.nan
    wl = int(window_length)
    if wl % 2 == 0: wl += 1
    if wl <= polyorder: wl = polyorder + 2
    x = df[xc].ffill().bfill().values
    y = df[yc].ffill().bfill().values
    vx = savgol_filter(x, wl, polyorder, deriv=1, delta=1/fps)
    vy = savgol_filter(y, wl, polyorder, deriv=1, delta=1/fps)
    ax_ = savgol_filter(x, wl, polyorder, deriv=2, delta=1/fps)
    ay_ = savgol_filter(y, wl, polyorder, deriv=2, delta=1/fps)
    jx = savgol_filter(x, wl, polyorder, deriv=3, delta=1/fps)
    jy = savgol_filter(y, wl, polyorder, deriv=3, delta=1/fps)
    smoothness = float(np.sqrt(ax_**2 + ay_**2).std())
    harmony = float(np.sqrt(jx**2 + jy**2).std())
    speed = np.sqrt(vx**2 + vy**2)
    mask = speed > 1e-6
    curv = np.zeros(len(x))
    curv[mask] = np.abs(vx[mask]*ay_[mask] - vy[mask]*ax_[mask]) / speed[mask]**3
    curvature = float(np.mean(curv))
    return smoothness, harmony, curvature


def _separar_estimulo_respuesta_audio(tapping_signal, stim_times, sample_rate,
                                       prom=0.1, distancia_candidatos_s=0.05,
                                       ventana_pareo_s=0.25):
    """
    Dentro de la ventana de cada estÃ­mulo esperado (stim_times), si el
    audio del video muestra 2+ picos cercanos, el mÃ¡s TEMPRANO se
    interpreta como el click del metrÃ³nomo sangrando en el micrÃ³fono de
    la cÃ¡mara, y el mÃ¡s TARDÃO como la respuesta real del sujeto -- el
    orden temporal es mÃ¡s robusto que separar por amplitud (que varÃ­a con
    la fuerza del golpe de cada sujeto/tap).

    Si solo aparece un pico en la ventana, se toma como respuesta (no hay
    forma de saber si es bleed puro sin respuesta, o la respuesta sin
    bleed detectable).

    Devuelve:
      picos_estimulo_audio_s : tiempos [s] del bleed del metrÃ³nomo en el
                                audio del video (para verificar el punto
                                de arranque asumido contra stim_times).
      picos_respuesta_audio_s: tiempos [s] de la respuesta real del sujeto.
    """
    candidatos = detect_peaks(tapping_signal, prominence=prom,
                              distance=max(1, int(sample_rate * distancia_candidatos_s)))
    candidatos_s = candidatos / sample_rate

    picos_estimulo, picos_respuesta = [], []
    for t_stim in stim_times:
        cercanos = np.sort(candidatos_s[np.abs(candidatos_s - t_stim) < ventana_pareo_s])
        if len(cercanos) == 0:
            continue
        elif len(cercanos) == 1:
            picos_respuesta.append(cercanos[0])
        else:
            picos_estimulo.append(cercanos[0])     # el mÃ¡s temprano
            picos_respuesta.append(cercanos[-1])   # el mÃ¡s tardÃ­o

    return np.array(picos_estimulo), np.array(picos_respuesta)


def _umbral_kmeans(valores, iters=25):
    """
    Umbral que separa dos grupos en una distribuciÃ³n (K-means 1D, 2
    clusters), robusto a puntos de ruido intermedios entre ambos grupos.
    """
    valores = np.asarray(valores, dtype=float)
    umbral = np.median(valores)
    for _ in range(iters):
        bajo = valores[valores <= umbral]
        alto = valores[valores > umbral]
        if len(bajo) == 0 or len(alto) == 0:
            break
        nuevo = (bajo.mean() + alto.mean()) / 2
        if abs(nuevo - umbral) < 1e-9:
            break
        umbral = nuevo
    return umbral


def _detectar_respuesta_audio_por_prominencia(tapping_signal, sample_rate,
                                               techo_prominencia=0.25,
                                               piso_prominencia=0.1,
                                               distancia_candidatos_s=0.05):
    """
    Detecta la respuesta real (golpe del dedo) en el audio del video,
    separÃ¡ndola del remanente del metrÃ³nomo (bleed/eco que sobrevive al
    filtro bandstop) con DOS niveles de prominencia:

    1) Se descartan los picos "fuertes" (prominencia >= techo_prominencia):
       en la prÃ¡ctica, casi siempre son el bleed directo del metrÃ³nomo.
    2) De los que quedan ("dÃ©biles"), se separan en dos sub-grupos por
       K-means 1D sobre su propia prominencia -- el remanente del
       metrÃ³nomo (eco/resonancia) sigue siendo, en promedio, mÃ¡s fuerte
       que el golpe real incluso dentro de la banda dÃ©bil. Se conserva
       el sub-grupo de mayor prominencia media.

    Validado empÃ­ricamente (sesiÃ³n PR de prueba): con distancia de
    candidatos de 50ms (en vez de 100ms, que tapaba la mitad de las
    respuestas reales al fusionarlas con el bleed del metrÃ³nomo, ambos a
    ~80-130ms entre sÃ­), cubre ~79% de los beats con track, 100% de esos
    dentro de Â±50ms del track, mediana ~-6ms, std ~17ms.
    """
    candidatos, props = find_peaks(
        tapping_signal, prominence=piso_prominencia,
        distance=max(1, int(sample_rate * distancia_candidatos_s)))
    prominencias = props['prominences']

    mask_debiles = prominencias < techo_prominencia
    if mask_debiles.sum() < 4:
        return candidatos[mask_debiles]   # muy pocos para subdividir mÃ¡s

    umbral_interno = _umbral_kmeans(prominencias[mask_debiles])
    mask_final = mask_debiles & (prominencias >= umbral_interno)
    return candidatos[mask_final]


def _segmentar_tapping(tapping_signal, metadata, sample_rate, prom=0.1):
    """Segmenta la seÃ±al de tapping (audio) en tramos por BPM."""
    tipo = metadata.get('tipo_metronomo', 'ISO')
    tramos = []
    if tipo == 'ISO':
        bpm = metadata['bpm']
        d = int(sample_rate * (60.0 / bpm - 0.1))
        taps = detect_peaks(tapping_signal, prominence=prom, distance=d)
        tramos.append({'label': f"{bpm} bpm", 'bpm': bpm,
                       'tapping_peaks': taps, 'offset_muestras': 0})
    elif tipo == 'PA':
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        tc = metadata['clics_1'] * (60.0 / bpm_1)
        tap1 = tapping_signal[:int((tc - 0.15) * sample_rate)]
        tap2 = tapping_signal[int(tc * sample_rate):]
        tramos.append({'label': f"{bpm_1} bpm", 'bpm': bpm_1,
                       'tapping_peaks': detect_peaks(tap1, prominence=prom,
                                                     distance=int(sample_rate*(60/bpm_1-0.1))),
                       'offset_muestras': 0})
        tramos.append({'label': f"{bpm_2} bpm", 'bpm': bpm_2,
                       'tapping_peaks': detect_peaks(tap2, prominence=prom,
                                                     distance=int(sample_rate*(60/bpm_2-0.1))),
                       'offset_muestras': int(tc * sample_rate)})
    elif tipo == 'PR':
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        clics_1, clics_r = metadata['clics_1'], metadata['clics_rampa']
        dur_1 = clics_1 * (60.0 / bpm_1)
        dur_r = _calcular_tiempo_rampa(bpm_1, bpm_2, clics_r)
        t_r_f = dur_1 + dur_r
        d_min = int(sample_rate * (60.0 / max(bpm_1, bpm_2) - 0.1))
        taps_all = detect_peaks(tapping_signal, prominence=prom, distance=d_min)
        tt = taps_all / sample_rate
        t1 = taps_all[tt <= dur_1]
        tr = taps_all[(tt > dur_1) & (tt <= t_r_f)]
        t2 = taps_all[tt > t_r_f]
        bpm_r = (bpm_1 + bpm_2) / 2.0
        tramos.append({'label': f"{bpm_1} bpm (inicio)", 'bpm': bpm_1,
                       'tapping_peaks': t1, 'offset_muestras': 0})
        tramos.append({'label': "Rampa", 'bpm': bpm_r,
                       'tapping_peaks': tr, 'offset_muestras': 0})
        tramos.append({'label': f"{bpm_2} bpm (final)", 'bpm': bpm_2,
                       'tapping_peaks': t2, 'offset_muestras': 0})
    return tramos



def calcular_repetidos_tramo(tapping_peaks, bpm, sample_rate):
    """Cuenta tappeos dobles dentro de un tramo (picos separados < mitad del perÃ­odo)."""
    if len(tapping_peaks) <= 1:
        return 0
    ventana = (60.0 / bpm / 2.0) * sample_rate
    return int(np.sum(np.diff(tapping_peaks) < ventana))


def detect_peaks(signal, prominence=None, height=None, distance=None):
    peaks, _ = find_peaks(signal, prominence=prominence, height=height, distance=distance)
    return peaks

def detect_valley_center(signal_values, peak_a_idx, next_peak_a_idx, n_local=5, tolerancia_piso_frac=0.15):
    """
    Entre dos picos altos consecutivos, encuentra el centro de la meseta
    del piso real -- promediando los extremos temporales de los mÃ­nimos
    locales que estÃ©n CERCA del mÃ­nimo global de la ventana (dentro de
    tolerancia_piso_frac del rango de esa ventana), no simplemente "los
    n_local mÃ¡s bajos por valor".

    Motivo del filtro por cercanÃ­a (confirmado con evidencia directa en
    dos casos reales): con pocos mÃ­nimos locales en la ventana (menos que
    n_local), TODOS entran en el promedio aunque alguno sea un escalÃ³n
    intermedio de la bajada muy por encima del piso real -- ej. un
    mÃ­nimo a 0.4665 promediado con el piso genuino a 0.432 da un centro
    en 0.452, que no representa ni el escalÃ³n ni el piso. Filtrar
    primero por cercanÃ­a al mÃ­nimo global evita mezclar puntos que estÃ¡n
    a alturas muy distintas, aunque ambos sean tÃ©cnicamente "mÃ­nimos
    locales".
    """
    # Segmento entre los dos picos altos
    segment = signal_values[peak_a_idx:next_peak_a_idx]

    if len(segment) < 3:
        # Segmento muy corto: devolver el mÃ­nimo directo
        return peak_a_idx + np.argmin(segment)

    # Detectar mÃ­nimos locales dentro del segmento (picos de la seÃ±al invertida)
    local_mins, _ = find_peaks(-segment, prominence=0)

    if len(local_mins) == 0:
        return peak_a_idx + np.argmin(segment)

    # Filtrar por cercanÃ­a al mÃ­nimo GLOBAL de la ventana -- excluye
    # escalones intermedios de la bajada, que pueden ser "mÃ­nimos
    # locales" vÃ¡lidos pero muy por encima del piso real.
    valor_min_global = segment[local_mins].min()
    rango_ventana = segment.max() - valor_min_global
    umbral_piso = valor_min_global + tolerancia_piso_frac * rango_ventana if rango_ventana > 0 else valor_min_global
    candidatos = local_mins[segment[local_mins] <= umbral_piso]
    if len(candidatos) == 0:
        candidatos = local_mins   # respaldo -- no deberÃ­a pasar (el mÃ­nimo global siempre cumple el umbral)

    if len(candidatos) == 1:
        return peak_a_idx + candidatos[0]

    # De los candidatos cercanos al piso, tomar el mÃ¡s a la izquierda y el
    # mÃ¡s a la derecha (extremos temporales) y promediar.
    extremo_izq = candidatos.min()
    extremo_der = candidatos.max()

    # Promedio temporal entre ambos extremos
    centro_meseta = int(round((extremo_izq + extremo_der) / 2))
    return peak_a_idx + centro_meseta

# ==============================================================================
# [N-4] ALGORITMO MATRICIAL DE ASINCRONÃA (compute_asyn â€” Repp 2005)
# ==============================================================================

def compute_asyn(stim_times, resp_times, ISI):
    """
    [N-4] Calcula asincronÃ­as estÃ­mulo-respuesta usando un algoritmo matricial
    de asignaciÃ³n bidireccional (basado en Repp, 2005).

    Cada respuesta se asigna al estÃ­mulo mÃ¡s cercano dentro de una ventana de
    Â±ISI/2. En caso de ambigÃ¼edad (mÃºltiples respuestas al mismo estÃ­mulo o
    viceversa), la asignaciÃ³n se descarta para evitar falsos emparejamientos.

    Args:
        stim_times  : array de tiempos de estÃ­mulos [s].
        resp_times  : array de tiempos de respuestas [s].
        ISI         : intervalo entre estÃ­mulos [s] (define la ventana de match).
    Returns:
        pd.DataFrame con columnas:
          'asyn'          : asincronÃ­a en ms (NaN si no emparejada).
          'assigned_stim' : Ã­ndice del estÃ­mulo asignado (-1 si no emparejado).
    """
    if len(resp_times) == 0:
        return pd.DataFrame({'asyn': [], 'assigned_stim': []})

    asyn_max     = 0.5 * ISI
    n_stims      = len(stim_times)
    n_resps      = len(resp_times)
    asyn         = np.full(n_resps, np.nan)
    assigned_stim = -np.ones(n_resps, dtype=int)

    # Matriz de diferencias (resp - stim), NaN si > ventana
    differences = -np.subtract.outer(stim_times, resp_times).astype(float)
    differences[np.abs(differences) >= asyn_max] = np.nan

    # Para cada respuesta: estÃ­mulo mÃ¡s cercano
    minima_R = np.zeros((n_stims, n_resps), dtype=int)
    for r in range(n_resps):
        col = differences[:, r]
        if not np.all(np.isnan(col)):
            min_abs = np.nanmin(np.abs(col))
            idx     = np.where(np.abs(col) == min_abs)
            minima_R[idx, r] = 1

    # Para cada estÃ­mulo: respuesta mÃ¡s cercana
    minima_S = np.zeros((n_stims, n_resps), dtype=int)
    for s in range(n_stims):
        row = differences[s, :]
        if not np.all(np.isnan(row)):
            min_abs = np.nanmin(np.abs(row))
            idx     = np.where(np.abs(row) == min_abs)
            minima_S[s, idx] = 1

    # Eliminar ambigÃ¼edades (consecutivos 1's en fila/columna)
    def _quitar_ambiguos(mat):
        shift = mat + np.roll(mat, (0, 1), (0, 1)) + np.roll(mat, (0, -1), (0, 1))
        mat[shift >= 2] = 0
        return mat

    minima_R = _quitar_ambiguos(minima_R)
    minima_S = _quitar_ambiguos(minima_S)

    # IntersecciÃ³n: pares mutuamente mÃ¡s cercanos
    inter   = minima_R * minima_S
    SR_idxs = np.where(inter == 1)
    S_idx   = SR_idxs[0]
    R_idx   = SR_idxs[1]

    assigned_stim[R_idx] = S_idx
    if S_idx.size > 0 and R_idx.size > 0:
        lin_ind     = np.ravel_multi_index((S_idx, R_idx), differences.shape)
        asyn[R_idx] = differences.ravel()[lin_ind] * 1000.0   # â†’ ms

    return pd.DataFrame({'asyn': asyn, 'assigned_stim': assigned_stim})


def compute_asyn_cercania(stim_times, resp_times, ventana_max_s):
    """
    Empareja cada respuesta con el estÃ­mulo mÃ¡s cercano dentro de una
    ventana, sin el rechazo estricto de ambigÃ¼edad bidireccional que usa
    compute_asyn (pensado para tolerar tappeos de mÃ¡s/de menos).

    Pensado para conjuntos de respuesta DISPERSOS y ya limpios (por
    ejemplo, audio filtrado por prominencia) donde no todos los estÃ­mulos
    tienen respuesta -- ahÃ­ el rechazo de ambigÃ¼edad de compute_asyn
    descarta muchos mÃ¡s pares vÃ¡lidos de los necesarios. Si dos
    respuestas compiten por el mismo estÃ­mulo, gana la mÃ¡s cercana.

    Devuelve directamente un array de asincronÃ­a [ms] indexado por
    estÃ­mulo (len == len(stim_times)), con NaN donde no hubo match.
    """
    stim_times = np.asarray(stim_times, dtype=float)
    resp_times = np.asarray(resp_times, dtype=float)
    n_stim = len(stim_times)

    asyn_por_stim = np.full(n_stim, np.nan)
    mejor_dist = np.full(n_stim, np.inf)

    for r in resp_times:
        idx = int(np.argmin(np.abs(stim_times - r)))
        dist = abs(stim_times[idx] - r)
        if dist <= ventana_max_s and dist < mejor_dist[idx]:
            mejor_dist[idx] = dist
            asyn_por_stim[idx] = (r - stim_times[idx]) * 1000.0

    return asyn_por_stim


def compute_asyn_ordinal(stim_times, resp_times, max_offset=None):
    """
    Empareja estÃ­mulo-respuesta por ORDEN temporal (1:1 secuencial), no por
    proximidad con ventana de ambigÃ¼edad como compute_asyn.

    Apropiado cuando la cantidad de respuestas es similar a la de estÃ­mulos,
    incluso con desfasajes grandes (antifase): cada respuesta se asocia al
    estÃ­mulo que le corresponde en la secuencia, no al mÃ¡s cercano en el
    tiempo -- asÃ­ una asincronÃ­a cercana a Â±ISI/2 sostenida no se pierde
    como NaN, queda como un valor grande pero real.

    No es apto para sesiones con tappeos de mÃ¡s/de menos frecuentes (ahÃ­
    compute_asyn, con su rechazo de ambigÃ¼edad, sigue siendo mÃ¡s seguro).

    Prueba distintos offsets de alineaciÃ³n (resp[i] <-> stim[i+offset]) y
    se queda con el que minimiza la asincronÃ­a absoluta media, para tolerar
    alguna respuesta de mÃ¡s/menos al principio o al final de la secciÃ³n.

    max_offset=None (por defecto) usa un rango PROPORCIONAL a la cantidad
    de datos disponibles, no un nÃºmero fijo chico -- confirmado con
    evidencia directa: una sesiÃ³n con varios beats sin respuesta al
    principio (el sujeto tardÃ³ en reaccionar) necesitaba un offset de 4
    para alinear correctamente, mientras el lÃ­mite fijo anterior (3) ni
    siquiera podÃ­a evaluar esa opciÃ³n, sin importar lo mal que ajustaran
    las alternativas dentro de su rango. Pensado para ser robusto tambiÃ©n
    con sujetos patolÃ³gicos (reacciones tardÃ­as, mÃ¡s beats sin respuesta
    al inicio de lo habitual en sujetos sanos) -- el costo de evaluar mÃ¡s
    offsets es insignificante (operaciÃ³n lineal), asÃ­ que no hay razÃ³n
    para mantener un lÃ­mite artificialmente bajo.

    resp_times puede contener NaN en posiciones puntuales (respuesta
    descartada por no representar un apoyo real, ver
    _calcular_resp_times_por_cruce) -- esas posiciones se ignoran para
    elegir el offset (no contaminan el costo), pero SÃ conservan su
    assigned_stim (a quÃ© estÃ­mulo le tocarÃ­a esa posiciÃ³n segÃºn el
    offset elegido) -- necesario para que el llamador pueda distinguir
    "hubo un tap acÃ¡ pero se descartÃ³" de "no hubo ningÃºn tap cerca de
    este estÃ­mulo", cosas semÃ¡nticamente distintas para decidir si vale
    la pena un respaldo de audio. asyn queda NaN en esas posiciones de
    todos modos (no se inventa un valor).
    """
    stim_times = np.asarray(stim_times)
    resp_times = np.asarray(resp_times)
    n_stim, n_resp = len(stim_times), len(resp_times)
    if max_offset is None:
        max_offset = max(10, max(n_stim, n_resp) // 2)

    if n_stim == 0 or n_resp == 0:
        return pd.DataFrame({'asyn': np.full(n_resp, np.nan),
                             'assigned_stim': -np.ones(n_resp, dtype=int)})

    mask_resp_valida = ~np.isnan(resp_times)

    mejor_offset, mejor_costo = 0, np.inf
    for offset in range(-max_offset, max_offset + 1):
        i_resp = np.arange(n_resp)
        i_stim = i_resp + offset
        valido = (i_stim >= 0) & (i_stim < n_stim) & mask_resp_valida
        if valido.sum() == 0:
            continue
        diffs = resp_times[i_resp[valido]] - stim_times[i_stim[valido]]
        costo = np.mean(np.abs(diffs))
        if costo < mejor_costo:
            mejor_costo  = costo
            mejor_offset = offset

    asyn = np.full(n_resp, np.nan)
    assigned_stim = -np.ones(n_resp, dtype=int)
    i_resp = np.arange(n_resp)
    i_stim = i_resp + mejor_offset
    # assigned_stim se asigna para TODAS las posiciones alineables (con o
    # sin hueco) -- asyn solo se calcula donde hay respuesta real.
    valido_assign = (i_stim >= 0) & (i_stim < n_stim)
    valido_asyn = valido_assign & mask_resp_valida
    assigned_stim[valido_assign] = i_stim[valido_assign]
    asyn[valido_asyn] = (resp_times[i_resp[valido_asyn]] - stim_times[i_stim[valido_asyn]]) * 1000.0

    return pd.DataFrame({'asyn': asyn, 'assigned_stim': assigned_stim})


def compute_asyn_ordinal_segmentado(stim_times, resp_times, max_offset=None,
                                     umbral_salto_ms=100, ventana_deteccion=5):
    """
    Como compute_asyn_ordinal, pero detecta si hay un SALTO DE NIVEL
    SOSTENIDO en la asincronÃ­a resultante -- indicio de que una respuesta
    se perdiÃ³ (o sobrÃ³ una) justo ahÃ­, corriendo la correspondencia
    estÃ­mulo-respuesta un lugar para todo lo que sigue -- y, si lo
    encuentra, parte la sesiÃ³n en dos en ese punto y vuelve a matchear
    cada mitad por separado, con su propio offset.

    Un offset Ãºnico para toda la sesiÃ³n no puede corregir esto (solo
    puede elegir UN offset fijo); si el sujeto perdiÃ³ una respuesta a
    mitad de sesiÃ³n, ese Ãºnico offset deja de ser vÃ¡lido de ahÃ­ en
    adelante, y aparece como un escalÃ³n artificial en la asincronÃ­a
    (confirmado en una sesiÃ³n de prueba: salto abrupto y sostenido justo
    en el cambio de tempo de una sesiÃ³n PA, ~200ms de escalÃ³n).

    max_offset=None se propaga sin resolver hacia compute_asyn_ordinal
    (tanto para la sesiÃ³n completa como para cada mitad tras un split) --
    cada llamada calcula su propio rango proporcional a SU tamaÃ±o, mÃ¡s
    apropiado que heredar un Ãºnico valor fijo para segmentos de tamaÃ±os
    distintos.

    "Sostenido" (no un outlier de un solo beat) se define comparando la
    mediana de ventana_deteccion beats antes vs. despuÃ©s de cada punto
    candidato -- un ruido de un solo beat no genera ese patrÃ³n, un
    desfasaje de Ã­ndice sÃ­.

    Registra el resultado en ULTIMO_SALTO_SEGMENTADO (global del mÃ³dulo),
    para que run_analysis lo pueda guardar en metadata/CSV -- no queda
    solo en el print de consola.
    """
    global ULTIMO_SALTO_SEGMENTADO
    stim_times = np.asarray(stim_times, dtype=float)
    resp_times = np.asarray(resp_times, dtype=float)
    n_stim = len(stim_times)

    output_global = compute_asyn_ordinal(stim_times, resp_times, max_offset=max_offset)
    asyn_global = construir_asyn_por_estimulo(output_global, n_stim)

    idx_validos = np.where(~np.isnan(asyn_global))[0]
    if len(idx_validos) < 2 * ventana_deteccion:
        ULTIMO_SALTO_SEGMENTADO = {'detectado': False, 'idx_estimulo': None,
                                    'tiempo_s': None, 'magnitud_ms': None}
        return output_global   # muy pocos datos para buscar un salto con confianza

    mejor_salto_idx, mejor_salto_mag = None, 0.0
    for k in range(ventana_deteccion, len(idx_validos) - ventana_deteccion):
        antes = asyn_global[idx_validos[k - ventana_deteccion:k]]
        despues = asyn_global[idx_validos[k:k + ventana_deteccion]]
        salto = np.median(despues) - np.median(antes)
        if abs(salto) > umbral_salto_ms and abs(salto) > mejor_salto_mag:
            mejor_salto_mag = abs(salto)
            mejor_salto_idx = idx_validos[k]

    if mejor_salto_idx is None:
        ULTIMO_SALTO_SEGMENTADO = {'detectado': False, 'idx_estimulo': None,
                                    'tiempo_s': None, 'magnitud_ms': None}
        return output_global   # no se detectÃ³ ningÃºn salto sostenido

    # Partir la sesiÃ³n en dos por POSICIÃ“N (no por tiempo), usando el offset
    # global que ya calculÃ³ compute_asyn_ordinal para toda la sesiÃ³n.
    #
    # ANTES se partÃ­a comparando el TIEMPO de cada respuesta contra
    # t_corte = stim_times[mejor_salto_idx] -- pero una respuesta real
    # cuya asincronÃ­a la corre unos pocos ms para el lado "equivocado" del
    # corte (ej. -63ms, mucho menor que un ISI completo) terminaba del
    # lado errÃ³neo aunque su POSICIÃ“N en la secuencia claramente
    # correspondÃ­a al otro lado. Confirmado con evidencia directa en
    # CUATRO sesiones distintas (Med11, Med9, la PA-33 y esta PA+10): en
    # todos los casos, la respuesta real de un beat justo en el punto de
    # corte quedaba huÃ©rfana (sin assigned_stim en ningÃºn tramo) por este
    # motivo -- no un caso aislado, un problema estructural del mÃ©todo de
    # particiÃ³n.
    #
    # La posiciÃ³n SÃ es inequÃ­voca: cada posiciÃ³n de respuesta j, bajo el
    # offset global ya encontrado (constante para toda la sesiÃ³n, antes de
    # partir), se alinearÃ­a con el estÃ­mulo (j + offset_global) -- sin
    # necesidad de aproximar por tiempo, y sin ambigÃ¼edad para los huecos
    # (NaN), que ya tienen su posiciÃ³n bien definida de por sÃ­.
    assigned_arr = output_global['assigned_stim'].values
    idx_asignados_global = np.where(assigned_arr >= 0)[0]
    if len(idx_asignados_global) > 0:
        offset_global = int(assigned_arr[idx_asignados_global[0]] - idx_asignados_global[0])
    else:
        offset_global = 0   # respaldo extremo -- no deberÃ­a pasar si hubo suficientes datos para llegar acÃ¡

    t_corte = stim_times[mejor_salto_idx]
    i_resp_todos = np.arange(len(resp_times))
    i_stim_equivalente = i_resp_todos + offset_global   # dÃ³nde caerÃ­a cada posiciÃ³n de respuesta bajo el offset global, SIN recortar al rango vÃ¡lido -- eso es justo lo que necesitamos para comparar contra mejor_salto_idx sin perder a los que caen apenas antes/despuÃ©s del final de la sesiÃ³n.

    mask_stim_1 = stim_times < t_corte
    mask_stim_2 = ~mask_stim_1
    mask_resp_1 = i_stim_equivalente < mejor_salto_idx
    mask_resp_2 = ~mask_resp_1

    idx_stim_1 = np.where(mask_stim_1)[0]
    idx_stim_2 = np.where(mask_stim_2)[0]

    output_1 = compute_asyn_ordinal(stim_times[mask_stim_1], resp_times[mask_resp_1], max_offset=max_offset)
    output_2 = compute_asyn_ordinal(stim_times[mask_stim_2], resp_times[mask_resp_2], max_offset=max_offset)

    # Reexpresar assigned_stim en Ã­ndice GLOBAL (no relativo a cada mitad).
    output_1 = output_1.copy()
    output_2 = output_2.copy()
    output_1['assigned_stim'] = output_1['assigned_stim'].apply(
        lambda i: int(idx_stim_1[i]) if 0 <= i < len(idx_stim_1) else -1)
    output_2['assigned_stim'] = output_2['assigned_stim'].apply(
        lambda i: int(idx_stim_2[i]) if 0 <= i < len(idx_stim_2) else -1)

    ULTIMO_SALTO_SEGMENTADO = {'detectado': True, 'idx_estimulo': int(mejor_salto_idx),
                                'tiempo_s': round(float(t_corte), 3),
                                'magnitud_ms': round(float(mejor_salto_mag), 1)}
    print(f"  [Matching segmentado] Salto sostenido detectado en estÃ­mulo idx={mejor_salto_idx} "
          f"(t={t_corte:.2f}s) | magnitud={mejor_salto_mag:.1f}ms -- re-matcheado en 2 tramos "
          f"({mask_stim_1.sum()} + {mask_stim_2.sum()} estÃ­mulos)")

    return pd.concat([output_1, output_2], ignore_index=True)


# ==============================================================================
# [N-5][N-6] NORMALIZACIÃ“N AL EJE ISO (PA/PR)
# ==============================================================================



def transform_to_iso(stim_times, target_bpm):
    """Convierte tiempos variables a un eje de tiempo ISO constante."""
    target_isi = 60.0 / target_bpm # Se fija un ISI predeterminado (120bmp = 0.5s)

    # Empeiza en stim_times[0] y despues se suma target_isi N veces.
    norm_stim_times = stim_times[0] + np.arange(len(stim_times)) * target_isi

    return norm_stim_times, target_isi





def map_resp_to_iso(resp_times, stim_times_orig, stim_times_iso):
    """
    Mapea las respuestas del sujeto al nuevo eje de tiempo ISO.
    Usa interpolaciÃ³n lineal por tramos entre estÃ­mulos como anclas.
    Las respuestas fuera del rango de los estÃ­mulos se extrapolan linealmente
    con la pendiente del tramo mÃ¡s cercano (en lugar de clampear)
    """
    resp_times = np.asarray(resp_times)
    stim_times_orig = np.asarray(stim_times_orig)
    stim_times_iso = np.asarray(stim_times_iso)

    # InterpolaciÃ³n interna: correcta por defecto
    resp_iso = np.interp(resp_times, stim_times_orig, stim_times_iso)

    # ExtrapolaciÃ³n izquierda (respuestas antes del primer estÃ­mulo)
    mask_left = resp_times < stim_times_orig[0]
    if np.any(mask_left) and len(stim_times_orig) >= 2:
        slope_left = ((stim_times_iso[1] - stim_times_iso[0]) /
                      (stim_times_orig[1] - stim_times_orig[0]))
        resp_iso[mask_left] = (stim_times_iso[0] +
                               slope_left * (resp_times[mask_left] - stim_times_orig[0]))

    # ExtrapolaciÃ³n derecha (respuestas despuÃ©s del Ãºltimo estÃ­mulo)
    mask_right = resp_times > stim_times_orig[-1]
    if np.any(mask_right) and len(stim_times_orig) >= 2:
        slope_right = ((stim_times_iso[-1] - stim_times_iso[-2]) /
                       (stim_times_orig[-1] - stim_times_orig[-2]))
        resp_iso[mask_right] = (stim_times_iso[-1] +
                                slope_right * (resp_times[mask_right] - stim_times_orig[-1]))

    n_left = np.sum(mask_left)
    n_right = np.sum(mask_right)
    if n_left > 0:
        print(f"  [map_resp_to_iso] {n_left} respuestas extrapoladas ANTES del primer estÃ­mulo.")
    if n_right > 0:
        print(f"  [map_resp_to_iso] {n_right} respuestas extrapoladas DESPUÃ‰S del Ãºltimo estÃ­mulo.")

    return resp_iso



def procesar_asincronias_sesion(stim_times, resp_times, metadata, target_bpm, usar_ordinal=False):
    tipo_metronomo = metadata.get('tipo_metronomo', 'ISO')

    if usar_ordinal:
        # Matching por orden secuencial en tiempo real (sin pasar por el eje
        # ISO): apropiado cuando la respuesta es 1:1 con el estÃ­mulo (video,
        # donde tip_peaks_b ya trae un valle por ciclo), incluso con
        # desfasajes grandes tipo antifase.
        #
        # VersiÃ³n SEGMENTADA (probando): si hay un salto de nivel sostenido
        # en la asincronÃ­a (tÃ­pico de una respuesta perdida/de mÃ¡s justo en
        # un cambio de tempo, corriendo el offset para todo lo que sigue),
        # re-matchea por separado antes/despuÃ©s del salto en vez de un
        # Ãºnico offset para toda la sesiÃ³n.
        output = compute_asyn_ordinal_segmentado(stim_times, resp_times)
        return output, resp_times, stim_times

    if tipo_metronomo == 'ISO':
        ISI = 60.0 / metadata['bpm']
        output = compute_asyn(stim_times, resp_times, ISI)
        return output, resp_times, stim_times

    else:
        # elif tipo_metronomo == 'PA' or tipo_metronomo == 'PR':
        stim_times_iso, ISI = transform_to_iso(stim_times, target_bpm)
        resp_times_iso = map_resp_to_iso(resp_times, stim_times, stim_times_iso)
        output = compute_asyn(stim_times_iso, resp_times_iso, ISI)
        return output, resp_times_iso, stim_times_iso




# ==============================================================================
# [N-8] CONSTRUCCIÃ“N UNIFICADA DE stim_times (tiempos de estÃ­mulos en segundos)
# ==============================================================================

def _construir_stim_times(metronome_clean, metadata, sample_rate):
    """
    [N-8] Detecta los picos del metrÃ³nomo y construye el array unificado de
    tiempos absolutos de estÃ­mulos en segundos para los tres tipos.

    Returns:
        stim_times : np.ndarray de tiempos de estÃ­mulos [s].
        peaks_por_tramo : dict con los arrays de picos por tramo (para JSON).
    """
    tipo = metadata.get('tipo_metronomo', 'ISO')

    if tipo == 'ISO':
        bpm      = metadata['bpm']
        distance = int(sample_rate * (60.0 / bpm - 0.1))
        peaks    = detect_peaks(metronome_clean, distance=distance)
        stim_times = peaks / sample_rate
        return stim_times, {'iso': peaks.tolist()}

    elif tipo == 'PA':
        bpm_1, bpm_2 = metadata['bpm_1'], metadata['bpm_2']
        clics_1      = metadata['clics_1']
        tiempo_corte = clics_1 * (60.0 / bpm_1)
        t1_fin       = tiempo_corte - 0.15

        metro_1 = metronome_clean[:int(t1_fin * sample_rate)]
        metro_2 = metronome_clean[int(tiempo_corte * sample_rate):]

        p1 = detect_peaks(metro_1, distance=int(sample_rate * (60.0 / bpm_1 - 0.1)))
        p2 = detect_peaks(metro_2, distance=int(sample_rate * (60.0 / bpm_2 - 0.1)))

        t1 = p1 / sample_rate
        t2 = p2 / sample_rate + tiempo_corte
        stim_times = np.concatenate([t1, t2])

        # p2 se detectÃ³ sobre metro_2 (el audio ya recortado), asÃ­ que sus Ã­ndices
        # son relativos al corte. Los pasamos a Ã­ndice absoluto (relativo al
        # audio completo) antes de guardarlos, para que 'pa_2' quede en la
        # misma unidad/base que 'pa_1', 'pr_1', 'pr_rampa' y 'pr_2'.
        p2_absoluto = p2 + int(tiempo_corte * sample_rate)
        return stim_times, {'pa_1': p1.tolist(), 'pa_2': p2_absoluto.tolist()}

    elif tipo == 'PR':
        bpm_1, bpm_2       = metadata['bpm_1'], metadata['bpm_2']
        clics_1, clics_r   = metadata['clics_1'], metadata['clics_rampa']
        dur_1              = clics_1 * (60.0 / bpm_1)
        dur_rampa          = _calcular_tiempo_rampa(bpm_1, bpm_2, clics_r)
        t_rampa_fin        = dur_1 + dur_rampa

        d_min  = int(sample_rate * (60.0 / max(bpm_1, bpm_2) - 0.1))
        p_all  = detect_peaks(metronome_clean, distance=d_min)
        pt     = p_all / sample_rate

        p1     = p_all[pt <= dur_1]
        p_r    = p_all[(pt > dur_1) & (pt <= t_rampa_fin)]
        p2     = p_all[pt > t_rampa_fin]

        stim_times = np.concatenate([p1 / sample_rate,
                                     p_r / sample_rate,
                                     p2  / sample_rate])
        return stim_times, {'pr_1': p1.tolist(),
                            'pr_rampa': p_r.tolist(),
                            'pr_2': p2.tolist()}

    return np.array([]), {}

def revert_to_original(iso_times, stim_times_iso, stim_times_orig):
    """
    Revierte tiempos del eje ISO al eje de tiempo real del video.
    Usa la misma lÃ³gica de extrapolaciÃ³n que map_resp_to_iso para
    no clampear fuera del rango de los estÃ­mulos.
    """
    iso_times       = np.asarray(iso_times)
    stim_times_iso  = np.asarray(stim_times_iso)
    stim_times_orig = np.asarray(stim_times_orig)

    # InterpolaciÃ³n interna
    revertidos = np.interp(iso_times, stim_times_iso, stim_times_orig)

    # ExtrapolaciÃ³n izquierda
    mask_left = iso_times < stim_times_iso[0]
    if np.any(mask_left) and len(stim_times_iso) >= 2:
        slope_left = ((stim_times_orig[1] - stim_times_orig[0]) /
                      (stim_times_iso[1]  - stim_times_iso[0]))
        revertidos[mask_left] = (stim_times_orig[0] +
                                 slope_left * (iso_times[mask_left] - stim_times_iso[0]))

    # ExtrapolaciÃ³n derecha
    mask_right = iso_times > stim_times_iso[-1]
    if np.any(mask_right) and len(stim_times_iso) >= 2:
        slope_right = ((stim_times_orig[-1] - stim_times_orig[-2]) /
                       (stim_times_iso[-1]  - stim_times_iso[-2]))
        revertidos[mask_right] = (stim_times_orig[-1] +
                                  slope_right * (iso_times[mask_right] - stim_times_iso[-1]))

    return revertidos





# ==============================================================================
# [C-9.1] FUNCIÃ“N UNIFICADA DE GUARDADO JSON
# ==============================================================================

def guardar_sesion(datos_sesion, nombre_archivo, output_dir=OUTPUT_DIR):
    """
    [C-9.1] Serializa el diccionario de resultados a JSON estÃ¡ndar (sin NaN/inf).
    """
    datos_conv = convert_numpy_to_python(datos_sesion)
    ruta = os.path.join(output_dir, nombre_archivo)
    try:
        with open(ruta, 'w', encoding='utf-8') as f:
            json.dump(datos_conv, f, indent=4, ensure_ascii=False, allow_nan=False)
        print(f"JSON guardado en: {ruta}")
        return datos_conv
    except (ValueError, TypeError) as e:
        print(f"Error de serializaciÃ³n JSON: {e}")
        return None
    except OSError as e:
        print(f"Error al escribir el archivo: {e}")
        return None


# ==============================================================================
# [C-9.4] EXPORTACIÃ“N A CSV (una fila por sesiÃ³n)
# ==============================================================================

def _calcular_stim_times_hibrido_rampa(stim_times, metadata, audio_relevant, sample_rate,
                                        offsets_audio_ms=None, n_ancla=5, slope_drift_ms_s=None):
    """
    [HÃBRIDO-RAMPA] Corrige ÃšNICAMENTE la secciÃ³n 'rampa' (solo PR),
    interpolando linealmente el offset audio-vs-.wav entre dos anclas
    robustas -- la mediana de los Ãºltimos n_ancla offsets confiables de
    BPM1 (evaluada en el borde fin-bpm1/inicio-rampa) y la mediana de
    los primeros n_ancla offsets confiables de BPM2 (evaluada en el
    borde fin-rampa/inicio-bpm2).

    BPM1 y BPM2 NO se tocan acÃ¡ -- la rampa es una EXCEPCIÃ“N deliberada
    al test de paralelismo (ver calcular_stim_times_sincronizacion): se
    sabe que ahÃ­ el desfasaje NO es constante (crece de forma progresiva
    durante el cambio de tempo), asÃ­ que siempre usa este mÃ©todo de
    hibridaciÃ³n en vez del test general, sin importar si BPM1/BPM2
    pasaron o no ese test.

    [slope_drift_ms_s] Si se pasa, se resta ANTES de calcular las anclas
    -- mismo motivo que en el caso audio_directo (ver
    calcular_stim_times_sincronizacion): las anclas se miden en offsets
    CRUDOS, tomados cerca del final de BPM1 / inicio de BPM2, es decir ya
    con bastante drift de cÃ¡mara acumulado desde el inicio de la sesiÃ³n.
    Si no se resta, ese drift queda contado dos veces -- una vez acÃ¡ (al
    desplazar rampa/BPM2 por la ancla) y otra vez en la correcciÃ³n de
    resp_times_s (que corrige el mismo drift del lado de la respuesta).
    Si no se pasa (None), no se resta nada (comportamiento anterior,
    conservado por compatibilidad).

    Se probÃ³ seguir la forma "natural" del audio crudo dentro de la
    rampa (suavizada) en vez de una recta simple, pero el anÃ¡lisis de
    excedente por click (ver historial) mostrÃ³ que la desviaciÃ³n real es
    casi constante (std bajo) -- no hay curvatura genuina que valga la
    pena preservar, asÃ­ que se prefiere la recta simple, mÃ¡s robusta a
    ruido puntual.

    Si no hay suficientes beats confiables (< 2) en alguna ancla, no se
    aplica ninguna correcciÃ³n a la rampa (se devuelve stim_times sin
    cambios ahÃ­) -- nunca se inventa una correcciÃ³n sin datos.

    Devuelve (stim_times_resultado, reporte), donde stim_times_resultado
    es IGUAL a stim_times excepto en los Ã­ndices de la rampa, y reporte
    es un dict (o None si no aplica/no es PR) para auditar quÃ© se hizo.
    """
    stim_times = np.asarray(stim_times, dtype=float)

    if metadata.get('tipo_metronomo') != 'PR':
        return stim_times.copy(), None

    if offsets_audio_ms is None:
        offsets_audio_ms = _detectar_offset_audio_bleed(stim_times, audio_relevant, sample_rate)

    if slope_drift_ms_s is not None:
        offsets_audio_ms = offsets_audio_ms - slope_drift_ms_s * stim_times

    secciones = _limites_secciones_tiempo(metadata)
    labels_disponibles = {label for label, _, _ in secciones}
    if not {'bpm1', 'rampa', 'bpm2'}.issubset(labels_disponibles):
        return stim_times.copy(), None

    idx_por_seccion = {label: np.where((stim_times >= t_ini) & (stim_times < t_fin))[0]
                       for label, t_ini, t_fin in secciones}
    limites_por_seccion = {label: (t_ini, t_fin) for label, t_ini, t_fin in secciones}

    stim_times_resultado = stim_times.copy()

    idx_bpm1 = idx_por_seccion['bpm1']
    offsets_bpm1_validos = []
    for idx in idx_bpm1[::-1]:
        if not np.isnan(offsets_audio_ms[idx]):
            offsets_bpm1_validos.append(offsets_audio_ms[idx])
        if len(offsets_bpm1_validos) >= n_ancla:
            break

    idx_bpm2 = idx_por_seccion['bpm2']
    offsets_bpm2_validos = []
    for idx in idx_bpm2:
        if not np.isnan(offsets_audio_ms[idx]):
            offsets_bpm2_validos.append(offsets_audio_ms[idx])
        if len(offsets_bpm2_validos) >= n_ancla:
            break

    reporte = {'n_ancla_bpm1': len(offsets_bpm1_validos), 'n_ancla_bpm2': len(offsets_bpm2_validos)}

    if len(offsets_bpm1_validos) < 2 or len(offsets_bpm2_validos) < 2:
        reporte['decision'] = 'sin_datos_suficientes'
        print(f"  [HÃBRIDO-RAMPA] Datos insuficientes para anclar (bpm1 n={len(offsets_bpm1_validos)}, "
              f"bpm2 n={len(offsets_bpm2_validos)}, mÃ­nimo 2 c/u) -- rampa queda como .wav sin cambios.")
        return stim_times_resultado, reporte

    ancla1_offset_ms = float(np.median(offsets_bpm1_validos))
    ancla1_t = limites_por_seccion['bpm1'][1]
    ancla2_offset_ms = float(np.median(offsets_bpm2_validos))
    ancla2_t = limites_por_seccion['bpm2'][0]

    idx_rampa = idx_por_seccion['rampa']
    t_rampa = stim_times[idx_rampa]
    offset_interpolado_ms = np.interp(t_rampa, [ancla1_t, ancla2_t], [ancla1_offset_ms, ancla2_offset_ms])
    stim_times_resultado[idx_rampa] = t_rampa + offset_interpolado_ms / 1000.0

    reporte.update({
        'ancla1_t': round(ancla1_t, 3), 'ancla1_offset_ms': round(ancla1_offset_ms, 1),
        'ancla2_t': round(ancla2_t, 3), 'ancla2_offset_ms': round(ancla2_offset_ms, 1),
        'decision': 'aplicado',
    })
    print(f"  [HÃBRIDO-RAMPA] ancla1(fin bpm1)={ancla1_offset_ms:+.1f}ms (n={len(offsets_bpm1_validos)}) | "
          f"ancla2(inicio bpm2)={ancla2_offset_ms:+.1f}ms (n={len(offsets_bpm2_validos)}) -- "
          f"rampa interpolada entre anclas.")

    return stim_times_resultado, reporte


# ==============================================================================
# [SINCRONIZACIÃ“N] TEST DE PARALELISMO + AUDIO/HÃBRIDO/WAV, POR SECCIÃ“N
# ==============================================================================

def calcular_stim_times_sincronizacion(stim_times, metadata, audio_relevant, sample_rate,
                                        n_ancla=5, umbral_diferencia_slope_ms_s=1.0):
    """
    [SINCRONIZACIÃ“N] Decide, para toda la sesiÃ³n, si usar el estÃ­mulo
    detectado en el audio de la cÃ¡mara o el .wav para sincronizar -- y
    construye stim_times_sync con esa decisiÃ³n ya aplicada.

    Test de paralelismo -- POR SECCIÃ“N, no combinado (rediseÃ±ado):
      Se ajusta calibrar_deriva_reloj_camara de forma INDEPENDIENTE en
      cada secciÃ³n NO-rampa (en ISO es la Ãºnica secciÃ³n; en PA/PR es
      BPM1 y BPM2 por separado). Confirmado con evidencia directa: un
      Ãºnico ajuste combinado sobre TODOS los puntos no-rampa juntos podÃ­a
      fallar (rÂ² bajo) aunque cada secciÃ³n, analizada sola, fuera
      perfectamente lineal (rÂ²>0.99 cada una) -- porque habÃ­a un ESCALÃ“N
      DE NIVEL constante entre secciones (ej. +17ms de mediana en BPM1 vs
      -4ms en BPM2) que el ajuste combinado interpretaba como ruido/no-
      linealidad, cuando en realidad ambas secciones compartÃ­an
      prÃ¡cticamente la MISMA pendiente (mismo drift de reloj de cÃ¡mara,
      esperable al ser la misma cÃ¡mara) con un desfasaje de NIVEL real
      entre ellas (intercepto distinto, no la pendiente).

      Se consideran "paralelas" -- caso favorable para usar audio -- si:
        1. Cada secciÃ³n, ajustada SOLA, es 'aplicable' (rÂ²>=0.8 individual).
        2. Si hay mÃ¡s de una secciÃ³n no-rampa (PA/PR), sus pendientes
           (slope_ms_s) difieren en menos de umbral_diferencia_slope_ms_s
           -- confirma que es el MISMO drift de reloj en ambas, no una
           divergencia real de tasa entre tramos.
      (En ISO, con una sola secciÃ³n no-rampa, el criterio 2 no aplica --
      basta con que esa Ãºnica secciÃ³n pase el criterio 1.)

    SegÃºn el resultado:

      PARALELO (todas las secciones pasan):
        Se usa el estÃ­mulo de audio DIRECTO -- el valor CRUDO detectado
        por beat (_detectar_offset_audio_bleed), no una versiÃ³n suavizada
        -- para TODA la sesiÃ³n, incluida la RAMPA en PR. Para los beats
        SIN detecciÃ³n confiable (outlier puntual descartado, o sin
        ninguna detecciÃ³n) DENTRO de una secciÃ³n ya confirmada paralela,
        se usa la PREDICCIÃ“N DEL MODELO ajustado de esa secciÃ³n (intercept
        + slope*t) en vez de dejarlos sin corregir -- ya que la secciÃ³n
        demostrÃ³ seguir ese modelo de forma confiable, es una mejor
        estimaciÃ³n que no aplicar ninguna correcciÃ³n ahÃ­. Solo quedan
        realmente sin estÃ­mulo sincronizado (NaN) los beats de una secciÃ³n
        que no llegÃ³ a tener modelo ajustable (muy pocos puntos vÃ¡lidos en
        total) -- ahÃ­ sÃ­, nunca se inventa un valor.

      NO PARALELO (alguna secciÃ³n falla su ajuste propio, o las
      pendientes entre secciones difieren demasiado -- divergencia real,
      no solo drift de reloj compartido):
        - PR: se usa el mÃ©todo HÃBRIDO clÃ¡sico -- BPM1 sin cambios (.wav),
          rampa interpolada linealmente entre las anclas de audio en los
          bordes (fin-bpm1/inicio-bpm2), y BPM2 con un desplazamiento
          CONSTANTE igual a la segunda ancla.
        - PA/ISO (no tienen rampa): .wav SIN NINGÃšN CAMBIO.

    Devuelve (stim_times_sync, metodo_por_beat, reporte):
      - stim_times_sync : array, mismo largo que stim_times (NaN donde no
        hay estÃ­mulo sincronizado confiable).
      - metodo_por_beat : array de strings, uno por beat:
          'audio_directo' | 'audio_directo_modelo' | 'hibrido_rampa' | 'hibrido_bpm2_ancla' |
          'wav_fallback' | 'sin_datos'
      - reporte : dict con el detalle de la decisiÃ³n (calibraciÃ³n por
        secciÃ³n, comparaciÃ³n de pendientes, anclas si aplica) para
        auditar en metadata/JSON.
    """
    stim_times = np.asarray(stim_times, dtype=float)
    n = len(stim_times)
    tipo = metadata.get('tipo_metronomo', 'ISO')

    secciones = _limites_secciones_tiempo(metadata)
    idx_por_seccion = {label: np.where((stim_times >= t_ini) & (stim_times < t_fin))[0]
                       for label, t_ini, t_fin in secciones}
    labels_no_rampa = [label for label in idx_por_seccion if label != 'rampa']

    reporte = {'secciones_no_rampa': labels_no_rampa}

    # --- Test de paralelismo: una calibraciÃ³n INDEPENDIENTE por secciÃ³n ------
    # Se usa _detectar_offset_audio_bleed (Viterbi + envolvente de Hilbert)
    # para la detecciÃ³n, no calibrar_deriva_reloj_camara -- ese detector mÃ¡s
    # viejo (umbral absoluto + onset, normalizado contra el pico mÃ¡ximo de
    # TODO lo que recibe) es frÃ¡gil ante cualquier sonido fuerte dentro de la
    # ventana que se le pase, sea de la secciÃ³n vecina o de ruido genuino
    # dentro de la propia secciÃ³n (golpe, ruido de fondo). Confirmado con
    # evidencia directa en una sesiÃ³n real: incluso recortando el audio a la
    # ventana propia de la secciÃ³n (con margen de seguridad hacia los
    # bordes), calibrar_deriva_reloj_camara seguÃ­a dando "0 clicks
    # detectados" en una secciÃ³n con bleed real perfectamente detectable --
    # mientras que _detectar_offset_audio_bleed encontraba esa misma seÃ±al
    # sin problema (mediana de offset calculable, consistente). En vez de
    # seguir parcheando el detector viejo, se reutiliza acÃ¡ el mismo
    # detector robusto ya validado en el resto del pipeline, con el mismo
    # criterio de ajuste (Theil-Sen + descarte de outliers por MAD) que
    # calibrar_deriva_reloj_camara aplica sobre SUS puntos -- ver
    # _ajustar_recta_robusta.
    offsets_audio_ms = _detectar_offset_audio_bleed(stim_times, audio_relevant, sample_rate)

    def _detectar_salto_offset(tiempos, offsets, min_puntos_lado=5, umbral_salto_ms=15.0,
                                mejora_sse_minima=0.35):
        """
        Prueba distintos puntos de corte candidatos; para cada uno, ajusta
        una recta INDEPENDIENTE a cada mitad y compara el error de ajuste
        (SSE) de esas dos rectas contra el de UNA sola recta para toda la
        secciÃ³n -- no busca especÃ­ficamente un escalÃ³n de nivel.

        Motivo del rediseÃ±o (confirmado con evidencia directa): la versiÃ³n
        anterior medÃ­a el salto de nivel extrapolado en el punto de corte
        (nivel_der - nivel_izq) -- funciona bien para un escalÃ³n genuino,
        pero es CIEGA a un cambio de PENDIENTE sin escalÃ³n (ej. una
        "joroba": sube y despuÃ©s baja) -- ahÃ­ las dos rectas se encuentran
        suavemente en el vÃ©rtice, dando un salto de nivel cercano a cero
        aunque el patrÃ³n sea clarÃ­simo a simple vista (rÂ²â‰ˆ0.005 al
        ajustar una sola recta a sube-baja). Ese caso nunca iba a superar
        ningÃºn umbral de salto, sin importar cuÃ¡ntas veces se reintentara.

        Comparar el error de ajuste total (una recta vs. dos) detecta
        AMBOS casos con el mismo mecanismo: un escalÃ³n deja mucho error
        sin explicar con una sola recta (la mayorÃ­a de los puntos quedan
        lejos de la lÃ­nea promedio entre ambos niveles), y una joroba
        tambiÃ©n (una recta no puede seguir un sube-baja) -- en los dos
        casos, partir en dos reduce el error drÃ¡sticamente. El umbral ya
        no es una magnitud en ms (no tiene sentido para un cambio de
        pendiente puro, sin escalÃ³n) sino una MEJORA RELATIVA de ajuste
        (fracciÃ³n del error total que se explica de mÃ¡s al partir en
        dos) -- escala mejor entre secciones con distinta amplitud/ruido.
        """
        tiempos = np.asarray(tiempos, dtype=float)
        offsets = np.asarray(offsets, dtype=float)
        idx_validos = np.where(~np.isnan(offsets))[0]
        n_validos = len(idx_validos)
        if n_validos < 2 * min_puntos_lado:
            return None, None

        t_v = tiempos[idx_validos]
        o_v = offsets[idx_validos]

        try:
            slope_total, intercept_total, _, _, _ = linregress(t_v, o_v)
        except ValueError:
            return None, None
        sse_total = float(np.sum((o_v - (intercept_total + slope_total * t_v)) ** 2))
        if sse_total <= 0:
            return None, None

        mejor_idx, mejor_mejora, mejor_salto_ms = None, 0.0, 0.0
        for k in range(min_puntos_lado, n_validos - min_puntos_lado):
            t_izq, o_izq = t_v[:k], o_v[:k]
            t_der, o_der = t_v[k:], o_v[k:]
            try:
                slope_izq, intercept_izq, _, _, _ = linregress(t_izq, o_izq)
                slope_der, intercept_der, _, _, _ = linregress(t_der, o_der)
            except ValueError:
                continue
            sse_izq = np.sum((o_izq - (intercept_izq + slope_izq * t_izq)) ** 2)
            sse_der = np.sum((o_der - (intercept_der + slope_der * t_der)) ** 2)
            sse_dos = float(sse_izq + sse_der)
            mejora = (sse_total - sse_dos) / sse_total
            if mejora > mejor_mejora:
                t_corte = t_v[k]
                nivel_izq = intercept_izq + slope_izq * t_corte
                nivel_der = intercept_der + slope_der * t_corte
                mejor_mejora   = mejora
                mejor_idx      = idx_validos[k]
                mejor_salto_ms = abs(nivel_der - nivel_izq)

        if mejor_idx is None or mejor_mejora < mejora_sse_minima:
            return None, None
        # magnitud devuelta: si hay escalÃ³n real, su valor en ms (informativo,
        # igual que antes); si es un cambio de pendiente puro (saltoâ‰ˆ0), se
        # devuelve la mejora de ajuste escalada a un nÃºmero visible en el
        # print, para no mostrar "magnitud=0.0ms" en un corte que sÃ­ es real.
        magnitud_reportada = mejor_salto_ms if mejor_salto_ms >= umbral_salto_ms else mejor_mejora * 100
        return mejor_idx, magnitud_reportada


    min_puntos_subseccion = 8   # no dividir si alguna mitad quedarÃ­a demasiado chica para calibrar
    saltos_internos_detectados = {}
    idx_forzar_interpolacion_borde = []   # bloques que tocan el final de la sesiÃ³n -- se fuerzan a interpolaciÃ³n mÃ¡s abajo, no se excluyen de la calibraciÃ³n
    # Cola de labels a revisar -- RECURSIVA: cada vez que una secciÃ³n se
    # divide en dos, ambas mitades nuevas vuelven a la cola para chequear si
    # necesitan partirse de nuevo. Un solo corte no alcanza para patrones
    # con mÃ¡s de un cambio de nivel (ej. una "joroba": sube y despuÃ©s baja)
    # -- confirmado con evidencia directa: una subsecciÃ³n con ese patrÃ³n
    # daba rÂ²â‰ˆ0.005 (una recta ajustada a sube-baja da pendiente casi plana
    # y pÃ©simo ajuste) porque el detector de un solo corte no encontraba
    # NINGÃšN punto candidato que superara el umbral de 15ms -- cualquier
    # corte que probara dejaba puntos altos Y bajos mezclados de al menos
    # un lado, diluyendo la magnitud medida del salto. Revisando cada
    # mitad por separado, cada joroba/valle se resuelve con su propio corte
    # en vez de necesitar que uno solo alcance para todo el patrÃ³n.
    cola_por_revisar = list(labels_no_rampa)
    while cola_por_revisar:
        label = cola_por_revisar.pop(0)
        if label not in idx_por_seccion:
            continue   # salvaguarda -- no deberÃ­a pasar, pero evita KeyError si ya fue reemplazada
        idx = idx_por_seccion[label]
        idx_corte_local, magnitud = _detectar_salto_offset(stim_times[idx], offsets_audio_ms[idx])
        if idx_corte_local is None:
            continue
        if idx_corte_local < min_puntos_subseccion or (len(idx) - idx_corte_local) < min_puntos_subseccion:
            # Se excluye SIEMPRE el bloque demasiado chico para dividir del
            # cÃ¡lculo de pendiente de su secciÃ³n -- estÃ© en el borde de la
            # sesiÃ³n (donde antes ya se hacÃ­a) o en el MEDIO (confirmado con
            # evidencia directa: un escalÃ³n real de ~15-20ms a mitad de una
            # subsecciÃ³n, con solo 5 puntos de un lado, no tocaba ningÃºn
            # borde de la sesiÃ³n -- antes ese caso quedaba sin ningÃºn
            # tratamiento, arrastrando el escalÃ³n directo al ajuste general
            # de la secciÃ³n, rÂ²=0.842 en vez del que tendrÃ­a sola la parte
            # limpia). No hay motivo real para tratar distinto un bloque
            # chico segÃºn si toca el borde de la grabaciÃ³n o no -- en
            # ambos casos, la razÃ³n para excluirlo es la misma: muy pocos
            # puntos como para confiar en su propia pendiente, pero
            # suficiente evidencia (el salto detectado) para saber que no
            # comparte la tendencia del resto.
            #
            # IMPORTANTE: el bloque se MANTIENE en idx_por_seccion (para
            # que reciba el residuo calculado con la pendiente ya
            # calibrada de la mayorÃ­a limpia) -- no se excluye de la
            # secciÃ³n. Confirmado con evidencia directa que excluirlo
            # del todo lo dejaba HUÃ‰RFANO: fuera de cualquier secciÃ³n, el
            # loop de residuo nunca lo tocaba (se quedaba con el offset
            # crudo sin corregir) y tampoco pasaba por ningÃºn chequeo de
            # outlier ni relleno por interpolaciÃ³n -- peor que no haber
            # hecho nada. En cambio, se registra para forzarlo a
            # interpolaciÃ³n mÃ¡s abajo (mismo mecanismo que ya existe para
            # outliers aislados/cerca del borde), reusando toda esa
            # lÃ³gica en vez de dejarlo sin ningÃºn tratamiento.
            lado_chico_es_final = (len(idx) - idx_corte_local) < min_puntos_subseccion
            bloque_chico = idx[idx_corte_local:] if lado_chico_es_final else idx[:idx_corte_local]
            idx_forzar_interpolacion_borde.append(bloque_chico)
            print(f"  [SINCRONIZACIÃ“N] Salto de nivel interno detectado en '{label}' "
                  f"(t={stim_times[idx[idx_corte_local]]:.2f}s, magnitud={magnitud:.1f} ""[ms si es escalon, %mejora de ajuste si es cambio de pendiente]) -- "
                  f"el bloque ({len(bloque_chico)} beats) es demasiado chico para calibrar solo -- "
                  f"se calibra '{label}' con el resto y se fuerza a interpolaciÃ³n (no se confÃ­a en "
                  f"su offset crudo).")
            continue
        idx_a, idx_b = idx[:idx_corte_local], idx[idx_corte_local:]
        label_a, label_b = f"{label}_a", f"{label}_b"
        del idx_por_seccion[label]
        idx_por_seccion[label_a] = idx_a
        idx_por_seccion[label_b] = idx_b
        pos = labels_no_rampa.index(label)
        labels_no_rampa[pos:pos + 1] = [label_a, label_b]
        saltos_internos_detectados[label] = {
            'idx_corte_local': int(idx_corte_local), 't_corte': float(stim_times[idx[idx_corte_local]]),
            'magnitud_ms': float(magnitud), 'label_a': label_a, 'label_b': label_b}
        print(f"  [SINCRONIZACIÃ“N] Salto de nivel interno detectado en '{label}' "
              f"(t={stim_times[idx[idx_corte_local]]:.2f}s, magnitud={magnitud:.1f} ""[ms si es escalon, %mejora de ajuste si es cambio de pendiente]) -- "
              f"dividida en '{label_a}' ({len(idx_a)} beats) y '{label_b}' ({len(idx_b)} beats).")
        # Revisar cada mitad nueva de nuevo -- puede necesitar otro corte
        # mÃ¡s (ej. una joroba tiene un corte de subida Y uno de bajada).
        cola_por_revisar.append(label_a)
        cola_por_revisar.append(label_b)

    calibraciones_por_seccion = {}
    modelos_por_seccion = {}   # {label: (slope_ms_s, intercept_ms)} -- para rellenar outliers/faltantes
    mask_outliers_global = np.zeros(n, dtype=bool)   # True donde un beat quedÃ³ marcado outlier en el ajuste de su secciÃ³n

    # Ãndices registrados para interpolaciÃ³n forzada (borde de sesiÃ³n, ver
    # arriba) -- se excluyen del CÃLCULO de pendiente/rÂ² de su secciÃ³n
    # (no deben poder arrastrar el ajuste), pero SIGUEN en idx_por_seccion
    # para todo lo demÃ¡s (relleno por interpolaciÃ³n mÃ¡s abajo). Sin este
    # paso, "forzar interpolaciÃ³n" solo cambiaba cÃ³mo se rellenaba el
    # bloque al final, pero la pendiente/rÂ² de la secciÃ³n se seguÃ­a
    # calculando con esos mismos puntos contaminando el ajuste --
    # confirmado con evidencia directa: una secciÃ³n con un bloque de 5
    # puntos con escalÃ³n real al principio seguÃ­a dando rÂ²=0.412 (idÃ©ntico
    # a antes del fix) porque _ajustar_recta_robusta recibÃ­a igual los 20
    # puntos, no los 15 limpios.
    idx_forzados_borde_set = (set(np.concatenate(idx_forzar_interpolacion_borde))
                               if idx_forzar_interpolacion_borde else set())

    for label in labels_no_rampa:
        idx = idx_por_seccion[label]
        idx_para_calibrar = (np.array([i for i in idx if i not in idx_forzados_borde_set], dtype=idx.dtype)
                              if idx_forzados_borde_set else idx)
        # MÃ­nimo PROPORCIONAL al tamaÃ±o de la secciÃ³n, no fijo -- el 15
        # original venÃ­a heredado de calibrar_deriva_reloj_camara, pensado
        # para calibrar sobre TODA la sesiÃ³n (muchos mÃ¡s puntos
        # disponibles), no para una secciÃ³n individual corta. Confirmado
        # con evidencia directa: una secciÃ³n PA de solo 20 beats con 11
        # detecciones confiables (55%) quedaba rechazada por no llegar a
        # 15 -- un estÃ¡ndar mucho mÃ¡s duro (75% del total) que el mismo
        # 15 aplicado a una sesiÃ³n de 60-90 beats. Se exige la mitad de
        # los beats de la secciÃ³n, con un piso de 10 (para no confiar en
        # un ajuste con muy pocos puntos, sea cual sea el tamaÃ±o de la
        # secciÃ³n).
        #
        # EXCEPCIÃ“N: para una subsecciÃ³n nacida de un salto interno (ej.
        # bpm1_a/bpm1_b), se usa el mismo piso (min_puntos_subseccion) que
        # ya se usÃ³ para decidir si convenÃ­a dividir en primer lugar --
        # confirmado con evidencia directa: con el piso genÃ©rico de 10,
        # una subsecciÃ³n podÃ­a "aprobar" la divisiÃ³n (con, por ejemplo,
        # 12 puntos) pero fallar igual la calibraciÃ³n apenas 1-2 outliers
        # la dejaban por debajo de 10 -- dos umbrales pensados para lo
        # mismo (Â¿hay suficiente data para confiar en esta pieza?) que no
        # coincidÃ­an entre sÃ­.
        labels_de_split = {v for info in saltos_internos_detectados.values() for v in (info['label_a'], info['label_b'])}
        min_clicks_seccion = min_puntos_subseccion if label in labels_de_split else max(10, int(0.5 * len(idx_para_calibrar)))
        if len(idx_para_calibrar) < min_clicks_seccion:
            calibraciones_por_seccion[label] = {'aplicable': False, 'decision': 'sin_datos_suficientes',
                                                 'n_puntos': int(len(idx_para_calibrar))}
            continue
        calib = _ajustar_recta_robusta(stim_times[idx_para_calibrar], offsets_audio_ms[idx_para_calibrar],
                                        min_clicks=min_clicks_seccion, etiqueta=f'({label})')
        calibraciones_por_seccion[label] = {
            'slope_ms_s': calib.get('slope_ms_s'), 'r2': calib.get('r2'),
            'n_detectados': calib.get('n_detectados'), 'aplicable': bool(calib.get('aplicable')),
        }
        if calib.get('slope_ms_s') is not None:
            modelos_por_seccion[label] = (calib['slope_ms_s'], calib['intercept_ms'])
        # Beats con detecciÃ³n vÃ¡lida pero marcados OUTLIER por el ajuste
        # robusto de su propia secciÃ³n -- se excluyen tambiÃ©n de
        # stim_times_sync mÃ¡s abajo (no solo del cÃ¡lculo de la pendiente),
        # para no heredar mediciones puntuales poco confiables (ej. el
        # artefacto de borde al final de la sesiÃ³n, sin audio suficiente
        # despuÃ©s del Ãºltimo click -- confirmado con evidencia directa:
        # 3 beats finales con offset disparado a +550ms mientras el resto
        # de la sesiÃ³n rondaba Â±50ms).
        mask_inliers_seccion = calib.get('mask_inliers')
        if mask_inliers_seccion is not None:
            mask_validos_seccion = ~np.isnan(offsets_audio_ms[idx_para_calibrar])
            mask_outlier_seccion = mask_validos_seccion & ~mask_inliers_seccion
            mask_outliers_global[idx_para_calibrar[mask_outlier_seccion]] = True

    if 'rampa' in idx_por_seccion:
        idx_rampa = idx_por_seccion['rampa']
        if len(idx_rampa) >= 3:
            calib_rampa = _ajustar_recta_robusta(stim_times[idx_rampa], offsets_audio_ms[idx_rampa],
                                                  min_clicks=3, etiqueta='(rampa, solo outliers)')
            mask_inliers_rampa = calib_rampa.get('mask_inliers')
            if mask_inliers_rampa is not None:
                mask_validos_rampa = ~np.isnan(offsets_audio_ms[idx_rampa])
                mask_outlier_rampa = mask_validos_rampa & ~mask_inliers_rampa
                mask_outliers_global[idx_rampa[mask_outlier_rampa]] = True
            if calib_rampa.get('slope_ms_s') is not None:
                modelos_por_seccion['rampa'] = (calib_rampa['slope_ms_s'], calib_rampa['intercept_ms'])

        # --- Discontinuidad SOSTENIDA dentro de la propia rampa (distinta
        # de un outlier puntual) ------------------------------------------
        # Motivo (confirmado con evidencia directa): el detector de audio
        # puede "perder el rastro" del click real en un tramo de la rampa
        # (tempo cambiando rÃ¡pido, ventanas de bÃºsqueda mÃ¡s angostas) y
        # engancharse con el click vecino equivocado -- produciendo un
        # salto grande y SOSTENIDO (no un punto aislado que se corrige
        # solo) en el offset crudo. La rampa no pasa por el test de
        # paralelismo (tiene divergencia real esperada, no solo drift), asÃ­
        # que este tipo de salto no lo atrapa ningÃºn otro mecanismo.
        #
        # Se compara cada salto entre puntos consecutivos contra el paso
        # tÃ­pico del resto de la rampa (mediana de |diferencias|) -- un
        # salto mucho mayor que ese paso tÃ­pico no es la progresiÃ³n
        # esperada de la rampa, es una discontinuidad. Como no hay forma
        # de saber con certeza CUÃL lado es el correcto, se marca como
        # sospechoso el lado mÃ¡s CORTO (heurÃ­stica conservadora, revisable
        # si la evidencia sugiere lo contrario) -- que cae en el mismo
        # mecanismo de relleno por interpolaciÃ³n ya existente (no inventa
        # nada nuevo, solo reutiliza lo ya construido).
        offsets_rampa = offsets_audio_ms[idx_rampa]
        mask_validos_rampa2 = ~np.isnan(offsets_rampa)
        idx_validos_rampa = np.where(mask_validos_rampa2)[0]
        if len(idx_validos_rampa) >= 6:
            diffs_rampa = np.diff(offsets_rampa[idx_validos_rampa])
            paso_tipico = float(np.median(np.abs(diffs_rampa)))
            umbral_discontinuidad = max(5.0 * paso_tipico, 100.0)
            saltos_grandes = np.where(np.abs(diffs_rampa) > umbral_discontinuidad)[0]
            if len(saltos_grandes) > 0:
                # Tomar la discontinuidad de mayor magnitud como el corte.
                k = saltos_grandes[np.argmax(np.abs(diffs_rampa[saltos_grandes]))]
                pos_corte = idx_validos_rampa[k + 1]   # primer Ã­ndice (relativo a idx_rampa) del lado "de despuÃ©s"
                lado_antes = np.arange(0, pos_corte)
                lado_despues = np.arange(pos_corte, len(idx_rampa))
                lado_sospechoso = lado_despues if len(lado_despues) <= len(lado_antes) else lado_antes
                mask_outliers_global[idx_rampa[lado_sospechoso]] = True
                print(f"  [SINCRONIZACIÃ“N] Discontinuidad sostenida detectada dentro de la rampa "
                      f"(t={stim_times[idx_rampa[pos_corte]]:.2f}s, salto={abs(diffs_rampa[k]):.1f}ms, "
                      f"paso tÃ­pico={paso_tipico:.1f}ms) -- {len(lado_sospechoso)} beat(s) marcados "
                      f"como sospechosos (lado mÃ¡s corto), se rellenan por interpolaciÃ³n con los "
                      f"vecinos confiables de la rampa.")

    # --- PrÃ©stamo de pendiente entre hermanas de un salto interno -----------
    # Si una subsecciÃ³n nacida de un salto interno (ej. bpm1_b, con pocos
    # beats) no juntÃ³ suficientes puntos para pasar el test de calibraciÃ³n
    # por su cuenta, pero su HERMANA (bpm1_a, la otra mitad de la MISMA
    # secciÃ³n original) sÃ­ pasÃ³, se le presta esa pendiente -- mismo
    # criterio ya usado para la rampa (ver mÃ¡s abajo): son fragmentos
    # consecutivos de la MISMA grabaciÃ³n, comparten el mismo drift de
    # cÃ¡mara por definiciÃ³n fÃ­sica (es el mismo reloj, el mismo tramo
    # continuo, solo partido en dos por el salto de nivel detectado). Solo
    # se estima el NIVEL (intercept) propio con los pocos puntos que sÃ­
    # tiene esa subsecciÃ³n -- eso sÃ­ se puede hacer con poca data (una
    # mediana), a diferencia de estimar una pendiente propia confiable.
    #
    # TambiÃ©n se presta cuando AMBAS hermanas pasan su propio test
    # individual, pero con un desbalance grande de evidencia (una con
    # menos del 20% de los puntos de la otra) Y pendientes que difieren de
    # forma no trivial -- confirmado con evidencia directa: una subsecciÃ³n
    # de 10 puntos (tras outliers) dio una pendiente de -14.36ms/s, muy
    # por fuera de cualquier drift de cÃ¡mara fÃ­sicamente plausible visto
    # en esta conversaciÃ³n (~1.1-1.6ms/s en decenas de sesiones), mientras
    # su hermana con 105 puntos y rÂ²=1.0 daba +1.42ms/s -- perfectamente
    # normal. Pasar el propio umbral de rÂ² no alcanza para confiar en una
    # pendiente cuando hay diez veces menos evidencia respaldÃ¡ndola que la
    # alternativa disponible en la misma grabaciÃ³n.
    UMBRAL_RATIO_DESBALANCE = 0.20
    UMBRAL_DIFERENCIA_SLOPE_DESBALANCE_MS_S = 2.0
    for label_original, info_salto in saltos_internos_detectados.items():
        label_a, label_b = info_salto['label_a'], info_salto['label_b']
        # Con la divisiÃ³n RECURSIVA, label_a o label_b pueden haber sido
        # partidas de nuevo mÃ¡s adelante (ej. 'bpm2_a' -> 'bpm2_a_a' +
        # 'bpm2_a_b') -- en ese caso ya no son secciones "hoja" y no estÃ¡n
        # en idx_por_seccion. El prÃ©stamo de pendiente entre hermanas solo
        # tiene sentido entre hojas actuales; si alguna de las dos ya no lo
        # es, este registro quedÃ³ obsoleto y se salta (sus propios hijos ya
        # tienen su propia entrada en saltos_internos_detectados, con su
        # propio chequeo de prÃ©stamo).
        if label_a not in idx_por_seccion or label_b not in idx_por_seccion:
            continue
        for label_falla, label_ok in [(label_a, label_b), (label_b, label_a)]:
            calib_falla = calibraciones_por_seccion.get(label_falla, {})
            calib_ok = calibraciones_por_seccion.get(label_ok, {})
            if not calib_ok.get('aplicable'):
                continue   # la hermana tampoco sirve como fuente

            if not calib_falla.get('aplicable'):
                debe_prestar = True   # caso original: la subsecciÃ³n directamente fallÃ³
            else:
                # Ambas pasaron su propio test -- evaluar desbalance de evidencia
                n_falla = calib_falla.get('n_detectados') or 0
                n_ok = calib_ok.get('n_detectados') or 0
                slope_falla = calib_falla.get('slope_ms_s')
                slope_ok = calib_ok.get('slope_ms_s')
                debe_prestar = (
                    n_ok > 0 and n_falla < UMBRAL_RATIO_DESBALANCE * n_ok
                    and slope_falla is not None and slope_ok is not None
                    and abs(slope_falla - slope_ok) > UMBRAL_DIFERENCIA_SLOPE_DESBALANCE_MS_S
                )
                if debe_prestar:
                    print(f"  [SINCRONIZACIÃ“N] '{label_falla}' pasÃ³ su propio ajuste "
                          f"(n={n_falla}) pero con muchos menos puntos que '{label_ok}' "
                          f"(n={n_ok}) y una pendiente muy distinta ({slope_falla:+.2f} vs "
                          f"{slope_ok:+.2f} ms/s) -- se prefiere la de mayor evidencia.")
            if not debe_prestar:
                continue

            slope_prestada = calib_ok.get('slope_ms_s')
            if slope_prestada is None:
                continue
            idx_falla = idx_por_seccion[label_falla]
            offsets_falla = offsets_audio_ms[idx_falla]
            mask_validos_falla = ~np.isnan(offsets_falla)
            if mask_validos_falla.sum() < 3:
                continue   # ni para estimar un nivel propio hay suficientes datos -- se deja como estaba
            residuos_falla = (offsets_falla[mask_validos_falla]
                               - slope_prestada * stim_times[idx_falla][mask_validos_falla])
            intercept_prestado = float(np.median(residuos_falla))
            calibraciones_por_seccion[label_falla] = {
                'slope_ms_s': slope_prestada, 'r2': None,
                'n_detectados': int(mask_validos_falla.sum()), 'aplicable': True,
                'pendiente_prestada_de': label_ok,
            }
            modelos_por_seccion[label_falla] = (slope_prestada, intercept_prestado)
            print(f"  [SINCRONIZACIÃ“N] '{label_falla}' no tenÃ­a suficientes puntos para calibrar "
                  f"sola -- se le prestÃ³ la pendiente de '{label_ok}' ({slope_prestada:+.4f} ms/s, "
                  f"misma grabaciÃ³n, mismo drift de cÃ¡mara esperado). Nivel propio estimado con "
                  f"{int(mask_validos_falla.sum())} puntos.")

    # --- PrÃ©stamo de pendiente por CONSENSO DE MAYORÃA -----------------------
    # Generaliza el prÃ©stamo entre hermanas (arriba, restringido a pares
    # de una misma secciÃ³n dividida) a TODAS las secciones/subsecciones de
    # la sesiÃ³n: si la MAYORÃA (mÃ¡s de la mitad) coincide entre sÃ­ en su
    # pendiente, y solo una minorÃ­a se aparta -- aunque esa minorÃ­a haya
    # pasado su propio test individual --, se le presta la pendiente de
    # consenso de la mayorÃ­a, en vez de dejar que una Ãºnica secciÃ³n
    # minoritaria rechace toda la sesiÃ³n.
    #
    # Se exige mayorÃ­a ESTRICTA (mÃ¡s de la mitad, no la mitad exacta) a
    # propÃ³sito: con solo 2 secciones (el caso clÃ¡sico BPM1 vs BPM2 sin
    # ningÃºn salto interno), "mÃ¡s de la mitad" nunca se cumple si
    # difieren -- preserva sin cambios el comportamiento ya validado para
    # ese caso (una diferencia real de pendiente entre dos secciones debe
    # seguir cayendo a wav_fallback, no reinterpretarse como consenso).
    # ReciÃ©n con 3 o mÃ¡s secciones, donde una mayorÃ­a clara coincide entre
    # sÃ­, tiene sentido hablar de "consenso" -- confirmado con evidencia
    # directa: 3 de 4 subsecciones coincidiendo en ~1.46 ms/s mientras la
    # cuarta daba -5.95 ms/s (una diferencia fÃ­sica implausible para
    # drift de cÃ¡mara, y sin ningÃºn vecino que la respalde).
    labels_aplicables = [l for l in labels_no_rampa
                          if calibraciones_por_seccion.get(l, {}).get('aplicable')
                          and calibraciones_por_seccion[l].get('slope_ms_s') is not None]

    # --- Rescate por UN SOLO donante muy fuerte --------------------------------
    # Los mecanismos de consenso de arriba (mayorÃ­a, evidencia, cantidad
    # absoluta) exigen al menos 2 secciones aplicables para comparar entre
    # sÃ­ -- pero si de todas las secciones no-rampa, TODAS menos una
    # fallaron su propia calibraciÃ³n, no hay ninguna segunda secciÃ³n con
    # la que formar consenso, aunque la Ãºnica que sÃ­ calibrÃ³ tenga
    # evidencia sobresaliente. Confirmado con evidencia directa: 'bpm1_a'
    # y 'bpm1_b' fallaron las dos (ninguna hermana disponible para
    # prestar), dejando 'bpm2' como Ãºnica secciÃ³n aplicable -- con
    # rÂ²=0.9999 y n=33, muchÃ­sima mÃ¡s evidencia que cualquiera de las dos
    # fallidas, pero sin ningÃºn mecanismo que la usara como referencia
    # por no haber una segunda secciÃ³n "de acuerdo".
    #
    # Un umbral de calidad MÃS ALTO que el 'aplicable' genÃ©rico
    # (rÂ²>=0.95, no 0.8) y un piso de puntos (>=15) compensan que acÃ¡ la
    # secciÃ³n donante estÃ¡ sola -- sin otra que la corrobore, se le pide
    # mÃ¡s confianza propia antes de usarla como referencia para el resto.
    UMBRAL_R2_DONANTE_UNICO = 0.95
    MIN_N_DONANTE_UNICO = 15
    labels_fallidas_total = [l for l in labels_no_rampa if l not in labels_aplicables]
    if labels_fallidas_total:
        donante_unico, mejor_n_donante = None, 0
        for l in labels_aplicables:
            r2_l = calibraciones_por_seccion[l].get('r2')
            n_l = calibraciones_por_seccion[l].get('n_detectados') or 0
            if r2_l is not None and r2_l >= UMBRAL_R2_DONANTE_UNICO and n_l >= MIN_N_DONANTE_UNICO and n_l > mejor_n_donante:
                donante_unico, mejor_n_donante = l, n_l
        if donante_unico is not None:
            slope_prestada = calibraciones_por_seccion[donante_unico]['slope_ms_s']
            r2_donante = calibraciones_por_seccion[donante_unico].get('r2')
            for label_fallida in labels_fallidas_total:
                idx_f = idx_por_seccion[label_fallida]
                offsets_f = offsets_audio_ms[idx_f]
                mask_v = ~np.isnan(offsets_f)
                if mask_v.sum() < 3:
                    continue   # ni para estimar un nivel propio hay suficientes datos -- se deja como estaba
                residuos = offsets_f[mask_v] - slope_prestada * stim_times[idx_f][mask_v]
                intercept_f = float(np.median(residuos))
                calibraciones_por_seccion[label_fallida] = {
                    'slope_ms_s': slope_prestada, 'r2': None,
                    'n_detectados': int(mask_v.sum()), 'aplicable': True,
                    'pendiente_prestada_de': f"{donante_unico} (Ãºnico donante fuerte, rÂ²={r2_donante:.4f})",
                }
                modelos_por_seccion[label_fallida] = (slope_prestada, intercept_f)
                print(f"  [SINCRONIZACIÃ“N] '{label_fallida}' no calibrÃ³ sola y no habÃ­a otra secciÃ³n "
                      f"para formar consenso -- '{donante_unico}' tiene evidencia muy fuerte por su "
                      f"cuenta (rÂ²={r2_donante:.4f}, n={mejor_n_donante}) -- se le presta esa pendiente.")
            # Recomputar labels_aplicables -- ahora puede haber mÃ¡s
            # secciones aplicables que antes de este rescate, y los
            # bloques de consenso que siguen abajo necesitan verlo.
            labels_aplicables = [l for l in labels_no_rampa
                                  if calibraciones_por_seccion.get(l, {}).get('aplicable')
                                  and calibraciones_por_seccion[l].get('slope_ms_s') is not None]

    if len(labels_aplicables) == 2:
        l1, l2 = labels_aplicables
        slope1, slope2 = calibraciones_por_seccion[l1]['slope_ms_s'], calibraciones_por_seccion[l2]['slope_ms_s']
        if abs(slope1 - slope2) > umbral_diferencia_slope_ms_s:
            r2_1, r2_2 = calibraciones_por_seccion[l1].get('r2'), calibraciones_por_seccion[l2].get('r2')
            n1 = calibraciones_por_seccion[l1].get('n_detectados') or 0
            n2 = calibraciones_por_seccion[l2].get('n_detectados') or 0
            if r2_1 is not None and r2_2 is not None:
                fuerte, debil = (l1, l2) if r2_1 >= r2_2 else (l2, l1)
                criterio_str = f"rÂ²={r2_1:.4f} vs rÂ²={r2_2:.4f}"
            else:
                fuerte, debil = (l1, l2) if n1 >= n2 else (l2, l1)
                criterio_str = f"n={n1} vs n={n2}"
            slope_prestada = calibraciones_por_seccion[fuerte]['slope_ms_s']
            idx_debil = idx_por_seccion[debil]
            offsets_debil = offsets_audio_ms[idx_debil]
            mask_v = ~np.isnan(offsets_debil)
            if mask_v.sum() >= 3:
                residuos = offsets_debil[mask_v] - slope_prestada * stim_times[idx_debil][mask_v]
                intercept_debil = float(np.median(residuos))
                slope_original_debil = calibraciones_por_seccion[debil]['slope_ms_s']
                calibraciones_por_seccion[debil] = {
                    'slope_ms_s': slope_prestada, 'r2': None,
                    'n_detectados': int(mask_v.sum()), 'aplicable': True,
                    'pendiente_prestada_de': f"{fuerte} (Ãºnica alternativa con 2 secciones, {criterio_str})",
                }
                modelos_por_seccion[debil] = (slope_prestada, intercept_debil)
                print(f"  [SINCRONIZACIÃ“N] Con solo 2 secciones no-rampa, '{debil}' difiere de '{fuerte}' "
                      f"({slope_original_debil:+.4f} vs {slope_prestada:+.4f} ms/s, diferencia > "
                      f"{umbral_diferencia_slope_ms_s}ms/s) -- la mediana de 2 valores no puede detectar "
                      f"esto como minorÃ­a, se presta directo por mejor evidencia ({criterio_str}).")

    if len(labels_aplicables) >= 2:
        slopes_dict = {l: calibraciones_por_seccion[l]['slope_ms_s'] for l in labels_aplicables}
        mediana_slopes = float(np.median(list(slopes_dict.values())))
        labels_consenso = [l for l in labels_aplicables
                            if abs(slopes_dict[l] - mediana_slopes) <= umbral_diferencia_slope_ms_s]
        labels_minoria = [l for l in labels_aplicables if l not in labels_consenso]

        # MayorÃ­a por CANTIDAD de secciones (como antes) O por EVIDENCIA
        # COMBINADA (suma de puntos usados) cuando hay empate en cantidad --
        # confirmado con evidencia directa: 2 de 4 subsecciones (empate
        # exacto) coincidÃ­an casi perfecto en pendiente (+1.38 vs +1.40
        # ms/s, rÂ²>0.99 ambas) mientras las otras 2 divergÃ­an bastante
        # entre sÃ­ (-2.43 y +4.23 ms/s) -- un empate en CANTIDAD no refleja
        # que un lado tenga muchÃ­sima mÃ¡s evidencia real detrÃ¡s (28 puntos
        # vs 24, y sobre todo ajustes individuales mucho mÃ¡s sÃ³lidos).
        # Preferir audio_directo (rescatando con la pendiente mejor
        # respaldada) es sistemÃ¡ticamente mejor que rendirse al hÃ­brido/
        # wav_fallback por un empate tÃ©cnico en la cuenta de secciones.
        n_consenso = sum(calibraciones_por_seccion[l].get('n_detectados') or 0 for l in labels_consenso)
        n_minoria = sum(calibraciones_por_seccion[l].get('n_detectados') or 0 for l in labels_minoria)
        hay_mayoria_cantidad = len(labels_consenso) > len(labels_aplicables) / 2
        hay_mayoria_evidencia = (not hay_mayoria_cantidad) and n_consenso > n_minoria

        # Consenso por CANTIDAD ABSOLUTA -- independiente de la proporciÃ³n
        # respecto al total de secciones. Con MUCHAS hojas (divisiÃ³n
        # recursiva puede generar bastantes), exigir "mÃ¡s de la mitad" se
        # vuelve cada vez mÃ¡s difÃ­cil de cumplir aunque haya de sobra
        # evidencia sÃ³lida concentrada en unas pocas -- 3 secciones con
        # buen ajuste y bastante evidencia cada una ya alcanzan para
        # confiar en su pendiente, sin importar cuÃ¡ntas hojas mÃ¡s haya en
        # total. MIN_N_POR_SECCION_CONSENSO_ABSOLUTO exige que cada una de
        # esas 3+ secciones tenga suficientes puntos propios (no solo que
        # el conjunto sume mucho) -- para no dejar que muchas secciones
        # chicas y poco confiables, sumadas, cuenten como "consenso
        # absoluto".
        MIN_SECCIONES_CONSENSO_ABSOLUTO = 3
        MIN_N_POR_SECCION_CONSENSO_ABSOLUTO = 10
        hay_mayoria_absoluta = (
            len(labels_consenso) >= MIN_SECCIONES_CONSENSO_ABSOLUTO
            and all((calibraciones_por_seccion[l].get('n_detectados') or 0) >= MIN_N_POR_SECCION_CONSENSO_ABSOLUTO
                    for l in labels_consenso)
        )

        # Secciones que NO llegaron a calibrar en absoluto (sin pendiente
        # propia -- ni siquiera "minoritaria", directamente ninguna) --
        # confirmado con evidencia directa: dos secciones hermanas (12
        # puntos cada una) con un bloque interno grande excluido (6 y 7
        # puntos) se quedaban con muy pocos puntos propios (6 y 5) para
        # calibrar solas -- por debajo del piso. El prÃ©stamo entre
        # hermanas no tiene nada para prestarles (las dos fallaron juntas,
        # ninguna es la "hermana ok"), y como no tienen slope_ms_s, ni
        # siquiera entraban en labels_aplicables para el consenso de
        # arriba -- quedaban huÃ©rfanas aunque hubiera consenso fuerte
        # disponible en el resto de la sesiÃ³n (otras 2 secciones con
        # rÂ²>0.99 cada una). Se agregan acÃ¡ al mismo prÃ©stamo de consenso,
        # sea cual sea el motivo por el que no calibraron.
        labels_sin_calibrar = [l for l in labels_no_rampa if l not in labels_aplicables]

        if (labels_minoria or labels_sin_calibrar) and (hay_mayoria_cantidad or hay_mayoria_evidencia or hay_mayoria_absoluta):
            motivo_mayoria = ("cantidad" if hay_mayoria_cantidad
                               else f"evidencia combinada, {n_consenso} vs {n_minoria} puntos" if hay_mayoria_evidencia
                               else f"cantidad absoluta, {len(labels_consenso)} secciones con >= "
                                    f"{MIN_N_POR_SECCION_CONSENSO_ABSOLUTO} puntos cada una")
            slope_consenso = float(np.median([slopes_dict[l] for l in labels_consenso]))
            for label_minoria in labels_minoria + labels_sin_calibrar:
                idx_m = idx_por_seccion[label_minoria]
                offsets_m = offsets_audio_ms[idx_m]
                mask_v = ~np.isnan(offsets_m)
                if mask_v.sum() < 3:
                    continue   # ni para estimar un nivel propio hay suficientes datos -- se deja como estaba
                residuos_m = offsets_m[mask_v] - slope_consenso * stim_times[idx_m][mask_v]
                intercept_m = float(np.median(residuos_m))
                slope_original = slopes_dict.get(label_minoria)
                calibraciones_por_seccion[label_minoria] = {
                    'slope_ms_s': slope_consenso, 'r2': None,
                    'n_detectados': int(mask_v.sum()), 'aplicable': True,
                    'pendiente_prestada_de': f"consenso ({motivo_mayoria})",
                }
                modelos_por_seccion[label_minoria] = (slope_consenso, intercept_m)
                origen_str = (f"tenÃ­a su propia pendiente ({slope_original:+.4f} ms/s) pero se aparta"
                               if slope_original is not None else "no llegÃ³ a calibrar sola (muy pocos puntos)")
                print(f"  [SINCRONIZACIÃ“N] '{label_minoria}' {origen_str} del consenso del resto de la "
                      f"sesiÃ³n (por {motivo_mayoria}, ~{slope_consenso:+.4f} ms/s) -- se le presta "
                      f"esa pendiente de consenso.")

    reporte['calibracion_por_seccion'] = calibraciones_por_seccion
    reporte['n_outliers_puntuales_excluidos'] = int(mask_outliers_global.sum())
    reporte['mask_outliers_global'] = mask_outliers_global.copy()

    todas_aplicables = len(labels_no_rampa) > 0 and all(
        calibraciones_por_seccion[label].get('aplicable') for label in labels_no_rampa)

    diferencia_slope = None
    pendientes_consistentes = True
    if todas_aplicables and len(labels_no_rampa) >= 2:
        slopes = [calibraciones_por_seccion[label]['slope_ms_s'] for label in labels_no_rampa]
        diferencia_slope = float(max(slopes) - min(slopes))
        pendientes_consistentes = diferencia_slope <= umbral_diferencia_slope_ms_s
        reporte['diferencia_slope_ms_s'] = round(diferencia_slope, 4)

    paralelo = todas_aplicables and pendientes_consistentes

    # --- MÃ‰TODO INTERMEDIO: "audio directo por secciÃ³n" ---------------------
    # Si el paralelismo no se confirma (las pendientes difieren demasiado
    # entre secciones), pero CADA secciÃ³n tiene, por separado, un ajuste
    # FUERTE (rÂ² por encima de un umbral mÃ¡s alto que el mÃ­nimo genÃ©rico de
    # aplicable) -- hay evidencia real y confiable en cada una, aunque no
    # compartan la misma explicaciÃ³n. En vez de descartar todo a wav_fallback,
    # se corrige cada secciÃ³n con SU PROPIA pendiente (reutilizando toda la
    # lÃ³gica de residuo/relleno de abajo, que ya opera por-secciÃ³n).
    #
    # Motivo (confirmado con evidencia directa, sesiÃ³n real): BPM1 con
    # rÂ²=0.999 y BPM2 con rÂ²â‰ˆ0.88-0.93, pendientes genuinamente distintas
    # (no un salto puntual, la tendencia completa difiere de punta a
    # punta) -- ninguna de las dos es ruido, pero tampoco comparten
    # explicaciÃ³n fÃ­sica comÃºn. Se exige un umbral MÃS ALTO que el de
    # 'aplicable' genÃ©rico (0.9 en vez de 0.8) para compensar que acÃ¡ no
    # hay una segunda secciÃ³n que corrobore la pendiente -- cada secciÃ³n
    # estÃ¡ sola, asÃ­ que se le pide mÃ¡s confianza propia antes de usarla.
    # Una secciÃ³n con pendiente PRESTADA (r2=None, ya viene de un consenso
    # de mayorÃ­a u otra secciÃ³n confiable) cuenta como fuerte tambiÃ©n.
    UMBRAL_R2_FUERTE = 0.85
    todas_fuertes = len(labels_no_rampa) > 0 and all(
        calibraciones_por_seccion.get(label, {}).get('aplicable')
        and (calibraciones_por_seccion[label].get('r2') is None
             or calibraciones_por_seccion[label].get('r2') >= UMBRAL_R2_FUERTE)
        for label in labels_no_rampa)
    usar_audio_por_seccion = (not paralelo) and todas_fuertes

    resumen_str = " | ".join(
        f"{label}: rÂ²={calibraciones_por_seccion[label].get('r2')}"
        for label in labels_no_rampa)
    if paralelo:
        extra = f" | diferencia_slope={diferencia_slope:.3f}ms/s" if diferencia_slope is not None else ""
        print(f"  [SINCRONIZACIÃ“N] Paralelismo confirmado por secciÃ³n ({resumen_str}{extra}) -- "
              f"se usa AUDIO DIRECTO (crudo, por beat) en toda la sesiÃ³n.")
    elif usar_audio_por_seccion:
        print(f"  [SINCRONIZACIÃ“N] Paralelismo NO confirmado (pendientes difieren "
              f"{diferencia_slope:.3f}ms/s), pero cada secciÃ³n tiene un ajuste FUERTE por su cuenta "
              f"({resumen_str}, todas rÂ²â‰¥{UMBRAL_R2_FUERTE} o con pendiente prestada) -- se usa "
              f"AUDIO DIRECTO POR SECCIÃ“N (cada una con su propia pendiente, sin exigir que "
              f"coincidan entre sÃ­).")
    else:
        motivo = "alguna secciÃ³n no ajustÃ³ bien" if not todas_aplicables else \
                 f"pendientes difieren {diferencia_slope:.3f}ms/s (> {umbral_diferencia_slope_ms_s}ms/s)"
        print(f"  [SINCRONIZACIÃ“N] Paralelismo NO confirmado ({resumen_str}) -- {motivo}.")

    stim_times_sync = np.full(n, np.nan)
    metodo_por_beat = np.full(n, 'sin_datos', dtype=object)

    # slope_referencia: pendiente de la PRIMERA secciÃ³n no-rampa (ej. BPM1)
    # -- se usa tanto en el caso 'paralelo' (para el residuo de toda la
    # sesiÃ³n) como en el hÃ­brido de PR (para no duplicar el drift tambiÃ©n
    # en las anclas de rampa/bpm2, ver _calcular_stim_times_hibrido_rampa).
    slope_referencia = None
    if labels_no_rampa:
        primer_label = labels_no_rampa[0]
        if primer_label in modelos_por_seccion:
            slope_referencia = modelos_por_seccion[primer_label][0]

    if paralelo or usar_audio_por_seccion:
        # --- PARALELO (o audio-directo-por-secciÃ³n): audio como RESIDUO
        # sobre el drift de cÃ¡mara ya modelado, no el offset crudo completo.
        # Toda esta lÃ³gica ya opera por-secciÃ³n (modelos_por_seccion.get(label,...)
        # para cada secciÃ³n al restar la pendiente), asÃ­ que sirve sin cambios
        # para el caso "cada secciÃ³n con su propia pendiente" tambiÃ©n. -------
        # MOTIVO (confirmado con evidencia directa: dos correcciones
        # independientes del mismo drift de cÃ¡mara con pendientes casi
        # idÃ©nticas, ~1.16-1.18ms/s en una sesiÃ³n real): la respuesta de
        # video (resp_times_s) YA se corrige por ese mismo drift mÃ¡s
        # adelante en el pipeline (resp_times_s / (1+tasa), ver
        # calibrar_deriva_reloj_camara). Si acÃ¡ tambiÃ©n se suma el offset
        # de audio COMPLETO (que incluye esa misma pendiente de drift) a
        # stim_times, el drift queda contado dos veces -- restado del lado
        # de la respuesta, sumado del lado del estÃ­mulo -- generando una
        # tendencia sostenida en la asincronÃ­a que no es comportamiento
        # real, solo aritmÃ©tica duplicada (confirmado visualmente: una
        # sesiÃ³n ISO mostraba una "deriva" descendente en TODA la
        # asincronÃ­a, no en un tramo puntual).
        #
        # Se aplica el RESIDUO: offset_audio_crudo menos la parte explicada
        # por la PENDIENTE Ãºnicamente (no el intercept completo -- el
        # intercept representa una latencia base constante del propio
        # mÃ©todo de detecciÃ³n de audio, sin contraparte en la correcciÃ³n de
        # resp_times_s, asÃ­ que no hay nada que duplicar ahÃ­).
        #
        # Para la RAMPA se usa la pendiente de la PRIMERA secciÃ³n no-rampa
        # (ej. BPM1), no la propia -- la tendencia propia de la rampa
        # mezcla drift de reloj CON divergencia real del dispositivo (ver
        # historial extenso sobre la rampa en esta conversaciÃ³n), y restar
        # su propia pendiente se comerÃ­a tambiÃ©n esa divergencia real que
        # se busca preservar.
        offsets_residual_ms = offsets_audio_ms.copy()
        for label, idx_seccion in idx_por_seccion.items():
            if label == 'rampa':
                slope_a_restar = slope_referencia
            else:
                slope_a_restar = modelos_por_seccion.get(label, (None, None))[0]
            if slope_a_restar is None:
                continue
            offsets_residual_ms[idx_seccion] = (
                offsets_audio_ms[idx_seccion] - slope_a_restar * stim_times[idx_seccion])
        reporte['offsets_residual_ms'] = offsets_residual_ms.copy()
        reporte['idx_por_seccion_final'] = {k: v.tolist() for k, v in idx_por_seccion.items()}

        # mask_outliers_global se sigue usando para estimar la pendiente/rÂ²
        # de cada secciÃ³n de forma robusta (en _ajustar_recta_robusta, mÃ¡s
        # arriba). Para el resultado final, se distingue entre dos tipos de
        # "outlier":
        #
        # 1. VARIACIÃ“N LOCAL SOSTENIDA (bloques de VARIOS beats consecutivos,
        #    internamente estables): NO se descarta, se conserva la propia
        #    mediciÃ³n -- confirmado con evidencia directa en una sesiÃ³n real
        #    (7 beats seguidos con residuo â‰ˆ-99.8ms, despuÃ©s 4 seguidos en
        #    â‰ˆ-105.0ms, cada grupo internamente muy estable) -- no es ruido,
        #    es variaciÃ³n real que el modelo lineal grueso de la secciÃ³n no
        #    captura, y rellenarla con el intercepto generaba saltos
        #    artificiales en los bordes de esos grupos.
        #
        # 2. OUTLIER AISLADO Y EXTREMO (1-2 beats sueltos, muy alejados del
        #    resto -- tÃ­picamente el artefacto de borde final, sin audio
        #    suficiente despuÃ©s del Ãºltimo click): confirmado con evidencia
        #    directa en otra sesiÃ³n real -- un Ãºnico beat final con offset
        #    disparado a valores absurdos (~+200ms mÃ¡s que cualquier otro
        #    punto de la sesiÃ³n). AhÃ­ SÃ se descarta la mediciÃ³n de audio y
        #    se cae directo al .wav (sin correcciÃ³n) para ese beat puntual
        #    -- no al modelo, porque un solo punto no alcanza para saber si
        #    el residuo tÃ­pico de esa secciÃ³n sigue siendo vÃ¡lido ahÃ­.
        #
        # 3. OUTLIER CERCA DEL FINAL DE LA GRABACIÃ“N, sea cual sea la
        #    longitud del bloque: confirmado con evidencia directa en OTRA
        #    sesiÃ³n real -- un bloque de 3 beats consecutivos (todos con
        #    asincronÃ­a disparada a ~+590ms) en los Ãºltimos beats de la
        #    sesiÃ³n sobreviviÃ³ al criterio 2 (por ser mÃ¡s largo que
        #    max_bloque_aislado) y quedÃ³ mal corregido. El artefacto de "sin
        #    audio suficiente despuÃ©s del Ãºltimo click" es un fenÃ³meno
        #    conocido y recurrente en esta conversaciÃ³n -- puede afectar mÃ¡s
        #    de 2 beats seguidos cerca delborde, a diferencia de la
        #    variaciÃ³n local sostenida (que puede aparecer en cualquier
        #    punto de la secciÃ³n, no solo pegada al final de la grabaciÃ³n).
        #    Se fuerza a .wav cualquier outlier cuyo tiempo estÃ© a menos de
        #    margen_borde_grabacion_s del final del audio disponible,
        #    independientemente de la longitud de su bloque.
        #
        # La distinciÃ³n para el resto (no cerca del borde de grabaciÃ³n) es:
        # bloque CORTO (<=max_bloque_aislado consecutivos) Y EXTREMO (ya
        # venÃ­a marcado outlier por el ajuste robusto, que exige >4 MAD de
        # distancia) -> se fuerza .wav. Bloque mÃ¡s largo, aunque tambiÃ©n
        # haya sido marcado outlier -> se conserva (variaciÃ³n local real).
        max_bloque_aislado = 2
        margen_borde_grabacion_s = 2.0
        duracion_audio_disponible_s = len(audio_relevant) / sample_rate

        mask_forzar_wav = np.zeros(n, dtype=bool)
        for label, idx_seccion in idx_por_seccion.items():
            idx_outlier_seccion = idx_seccion[mask_outliers_global[idx_seccion]]
            if len(idx_outlier_seccion) == 0:
                continue
            saltos = np.where(np.diff(idx_outlier_seccion) > 1)[0] + 1
            corridas = np.split(idx_outlier_seccion, saltos)
            for corrida in corridas:
                cerca_del_final = (duracion_audio_disponible_s - stim_times[corrida].max()) <= margen_borde_grabacion_s
                if len(corrida) <= max_bloque_aislado or cerca_del_final:
                    mask_forzar_wav[corrida] = True

        # Bloques de un salto interno no dividido que tocan el final de la
        # sesiÃ³n (ver mÃ¡s arriba) -- se fuerzan a interpolaciÃ³n acÃ¡,
        # independientemente de su tamaÃ±o (pueden ser mÃ¡s de
        # max_bloque_aislado, como los 6 beats de una sesiÃ³n real).
        for bloque in idx_forzar_interpolacion_borde:
            mask_forzar_wav[bloque] = True

        mask_validos = ~np.isnan(offsets_residual_ms) & ~mask_forzar_wav
        stim_times_sync[mask_validos] = stim_times[mask_validos] + offsets_residual_ms[mask_validos] / 1000.0
        metodo_por_beat[mask_validos] = 'audio_directo' if paralelo else 'audio_directo_por_seccion'

        # --- Beats SIN mediciÃ³n confiable EN UNA SECCIÃ“N QUE YA SE CONFIRMÃ“
        # PARALELA: incluye tanto los que no tuvieron NINGUNA detecciÃ³n de
        # audio (NaN) como los outliers aislados/cerca del borde de
        # grabaciÃ³n (mask_forzar_wav, criterios 2 y 3 mÃ¡s arriba). Se
        # rellenan por INTERPOLACIÃ“N TEMPORAL entre los vecinos confiables
        # mÃ¡s cercanos de esa misma secciÃ³n -- NO con el intercept de la
        # regresiÃ³n, NI con la mediana de toda la secciÃ³n.
        #
        # Motivo del cambio (confirmado con evidencia directa, dos bugs
        # sucesivos): (1) el intercept es la recta evaluada en t=0, muy
        # lejos de los datos reales de una secciÃ³n tardÃ­a como BPM2 -- con
        # un ajuste poco sÃ³lido, esa extrapolaciÃ³n se dispara (llegÃ³ a dar
        # +720ms de relleno). (2) la MEDIANA de toda la secciÃ³n asume que
        # el residuo es aproximadamente CONSTANTE ahÃ­ -- vÃ¡lido para
        # BPM1/BPM2/ISO (que pasaron el test de paralelismo justo porque
        # su residuo es plano), pero NO para la rampa, que por diseÃ±o
        # tiene una tendencia CRECIENTE real (ver historial extenso sobre
        # la rampa en esta conversaciÃ³n) -- confirmado: el Ãºltimo beat de
        # la rampa, marcado outlier, se rellenÃ³ con la mediana de TODA la
        # rampa (que mezcla el principio bajo con el final alto) en vez de
        # seguir la progresiÃ³n creciente esperada ahÃ­, dando un valor
        # mucho menor al que le correspondÃ­a. Interpolar por tiempo entre
        # los vecinos mÃ¡s cercanos sigue la tendencia LOCAL real (plana o
        # creciente, lo que corresponda) en cualquier secciÃ³n, sin asumir
        # ninguna forma particular.
        mask_a_rellenar = np.isnan(offsets_residual_ms) | mask_forzar_wav
        n_rellenados = 0
        for label, idx_seccion in idx_por_seccion.items():
            idx_rellenar_seccion = idx_seccion[mask_a_rellenar[idx_seccion]]
            if len(idx_rellenar_seccion) == 0:
                continue
            idx_confiables_seccion = idx_seccion[~mask_a_rellenar[idx_seccion]]
            if len(idx_confiables_seccion) >= 2:
                orden = np.argsort(stim_times[idx_confiables_seccion])
                t_confiables = stim_times[idx_confiables_seccion][orden]
                res_confiables = offsets_residual_ms[idx_confiables_seccion][orden]
                residuos_relleno = np.interp(stim_times[idx_rellenar_seccion], t_confiables, res_confiables)
            elif len(idx_confiables_seccion) == 1:
                residuos_relleno = np.full(len(idx_rellenar_seccion), offsets_residual_ms[idx_confiables_seccion[0]])
            elif label in modelos_por_seccion:
                # Sin ningÃºn vecino confiable en toda la secciÃ³n (caso
                # extremo) -- Ãºltimo recurso, el intercept del modelo.
                residuos_relleno = np.full(len(idx_rellenar_seccion), modelos_por_seccion[label][1])
            else:
                continue
            stim_times_sync[idx_rellenar_seccion] = stim_times[idx_rellenar_seccion] + residuos_relleno / 1000.0
            metodo_por_beat[idx_rellenar_seccion] = 'audio_directo_modelo'
            n_rellenados += len(idx_rellenar_seccion)

        reporte['decision'] = 'audio_directo' if paralelo else 'audio_directo_por_seccion'
        reporte['slope_drift_removido_ms_s'] = {
            label: (slope_referencia if label == 'rampa' else modelos_por_seccion.get(label, (None,))[0])
            for label in idx_por_seccion}
        reporte['mask_forzar_wav'] = mask_forzar_wav.copy()
        n_forzados = int(mask_forzar_wav.sum())
        n_outliers_info = int(mask_outliers_global.sum()) - n_forzados
        print(f"    ({int(mask_validos.sum())}/{n} beats con detecciÃ³n de audio confiable (residuo, sin drift duplicado)"
              + (f", {n_outliers_info} usados igual pese a ser outlier en el ajuste de pendiente" if n_outliers_info > 0 else "")
              + (f", {n_rellenados} rellenados con el intercept de su secciÃ³n "
                 f"({n_forzados} por outlier aislado/borde + {n_rellenados - n_forzados} sin detecciÃ³n)" if n_rellenados else "") + ")")

    elif tipo == 'PR':
        # --- NO PARALELO en PR: hÃ­brido clÃ¡sico (bpm1=.wav, rampa
        # interpolada, bpm2 con ancla constante) --------------------------------
        stim_times_sync = stim_times.copy()
        metodo_por_beat[:] = 'wav_fallback'

        stim_times_rampa, reporte_rampa = _calcular_stim_times_hibrido_rampa(
            stim_times, metadata, audio_relevant, sample_rate, n_ancla=n_ancla,
            slope_drift_ms_s=slope_referencia)
        reporte['rampa'] = reporte_rampa

        if 'rampa' in idx_por_seccion:
            idx_rampa = idx_por_seccion['rampa']
            stim_times_sync[idx_rampa] = stim_times_rampa[idx_rampa]
            if reporte_rampa is not None and reporte_rampa.get('decision') == 'aplicado':
                metodo_por_beat[idx_rampa] = 'hibrido_rampa'

        if ('bpm2' in idx_por_seccion and reporte_rampa is not None
                and reporte_rampa.get('decision') == 'aplicado'):
            idx_bpm2 = idx_por_seccion['bpm2']
            ancla2_offset_ms = reporte_rampa['ancla2_offset_ms']
            stim_times_sync[idx_bpm2] = stim_times[idx_bpm2] + ancla2_offset_ms / 1000.0
            metodo_por_beat[idx_bpm2] = 'hibrido_bpm2_ancla'

        reporte['decision'] = 'hibrido_pr'
        print(f"    -- se usa mÃ©todo HÃBRIDO (bpm1=.wav, rampa interpolada, bpm2 con ancla).")

    else:
        # --- NO PARALELO en PA/ISO: .wav sin cambios ------------------------------
        stim_times_sync = stim_times.copy()
        metodo_por_beat[:] = 'wav_fallback'
        reporte['decision'] = 'wav_fallback'
        print(f"    -- se usa .wav sin cambios.")

    return stim_times_sync, metodo_por_beat, reporte


def run_analysis(video_path=None, metronome_path=None, config=None):
    """
    [C-10.1] Pipeline completo de anÃ¡lisis. En Colab se llama sin argumentos.
    En migraciÃ³n a mÃ³dulo, recibe rutas y config dict.

    Args:
        video_path     : Ruta al video. Si None, busca en CONTENT_DIR.
        metronome_path : Ruta al .wav del metrÃ³nomo. Si None, busca en CONTENT_DIR.
        config         : dict opcional para sobreescribir parÃ¡metros globales.
    Returns:
        dict con todos los resultados (idÃ©ntico al JSON guardado).
    """
    # --- Aplicar configuraciÃ³n externa ---
    global GRAFICAR, UMBRAL_POTENCIA, UMBRAL_INTERPOLACION_PCT
    global FC_LOW, FC_HIGH, FILTRO_ORDEN, ROTACION_VIDEO
    global D_MI_MM, D_MI_FI, D_MD_MM, D_MD_FI, TOLERANCIA_ESCALA_PCT
    global BPM_BASE, SAVGOL_POLYORDER, OUTPUT_DIR, TARGET_BPM_ISO
    if config:
        for k, v in config.items():
            if k in globals():
                globals()[k] = v

    # ==========================================================================
    # 1. DETECCIÃ“N Y CARGA DE ARCHIVOS [C-1.1]
    # ==========================================================================
    if video_path is None:
        videos = [f for f in os.listdir(CONTENT_DIR)
                  if f.lower().endswith(('.mp4', '.mov', '.avi', '.mkv'))]
        if not videos:
            raise VideoNotFoundError()
        if len(videos) > 1:
            raise MultipleVideosError(videos)
        video_path = os.path.join(CONTENT_DIR, videos[0])

    if metronome_path is None:
        wavs = [f for f in os.listdir(CONTENT_DIR) if f.lower().endswith('.wav')]
        if not wavs:
            raise AudioNotFoundError()
        if len(wavs) > 1:
            raise MultipleAudiosError(wavs)
        metronome_path = os.path.join(CONTENT_DIR, wavs[0])

    print(f"Video     : {video_path}")
    print(f"MetrÃ³nomo : {metronome_path}")

    # ==========================================================================
    # 2. METADATA DEL NOMBRE DE ARCHIVO [C-1.2, C-1.3, C-1.5]
    # ==========================================================================
    filename_base = os.path.basename(video_path)
    filename_base = re.sub(r'[^\x00-\x7F]', '_', filename_base)   # [C-1.5]
    metadata      = _extraer_metadata(filename_base)

    if not metadata:
        raise InvalidFilenameError(filename_base)
    print("\n--- Metadatos ---")
    for k, v in metadata.items():
        print(f"  {k}: {v}")

    try:
        verificar_audio_con_video(metadata, metronome_path)
    except ValueError as e:
        raise AudioMismatchError(str(e)) from e

    filename_stem = os.path.splitext(filename_base)[0]

    # ==========================================================================
    # 3. CARGA DE AUDIO
    # ==========================================================================
    print("\nCargando audio...")
    audio_data, sample_rate = _cargar_audio_de_video(video_path)
    metronome_clean, _      = librosa.load(metronome_path, sr=sample_rate, mono=True)
    if len(audio_data) / sample_rate < 5.0:
        raise CorruptVideoError("audio_short")
    print(f"  sr={sample_rate} Hz | video={len(audio_data)/sample_rate:.2f}s "
          f"| metrÃ³nomo={len(metronome_clean)/sample_rate:.2f}s")

    # ==========================================================================
    # 4. DETECCIÃ“N DEL SEGMENTO RÃTMICO
    # ==========================================================================
    start_index, end_index = find_rhythmic_segment(audio_data, sample_rate, metadata)

    # --- VerificaciÃ³n contra el ÃšLTIMO ESTÃMULO REAL esperado -----------------
    # find_rhythmic_segment corta el FIN del segmento por energÃ­a de audio del
    # VIDEO (Ãºltima ventana de 50ms con energÃ­a > 10% del mÃ¡ximo) -- un
    # criterio que puede fallar si los Ãºltimos tapeos bajan de volumen
    # (fatiga, cambio de superficie, mano mÃ¡s lejos del micrÃ³fono) aunque el
    # sujeto siga tapeando y el metrÃ³nomo siga sonando. Confirmado con
    # evidencia directa: una sesiÃ³n real con end_time cortado en tâ‰ˆ97.2s
    # (absoluto) mientras el Ãºltimo estÃ­mulo real, calculado directamente del
    # .wav del metrÃ³nomo -- que no depende de la energÃ­a de audio del video,
    # siempre estÃ¡ completo -- caÃ­a en tâ‰ˆ89.2s DESPUÃ‰S de start_time (â‰ˆ106s
    # absoluto) -- casi 9 segundos de tapeo real (y de audio) quedaron fuera
    # de la ventana analizada, sin haber ningÃºn error ni corte de video: ni
    # el tracking ni el audio del video llegaban a esos frames/muestras
    # porque directamente no se los incluÃ­a en audio_relevant/la ventana de
    # tracking.
    #
    # NO se extiende a ciegas hasta "start_time + Ãºltimo estÃ­mulo del .wav +
    # margen" -- el .wav del metrÃ³nomo siempre estÃ¡ completo, pero eso NO
    # confirma que la SESIÃ“N real haya seguido hasta ahÃ­ (la grabaciÃ³n puede
    # haberse cortado antes, ver el caso real de esta misma conversaciÃ³n:
    # el video terminaba en tâ‰ˆ98.8s absoluto mientras el .wav "esperaba"
    # estÃ­mulos hasta tâ‰ˆ106s). Extender ciegamente con un margen grande
    # arriesga incluir tracking de la mano ya en reposo (apoyada sobre la
    # mesa tras terminar de tapear) como si fuera una respuesta real al
    # Ãºltimo estÃ­mulo -- un falso positivo silencioso.
    #
    # En cambio, se VERIFICA con el propio audio de la grabaciÃ³n (bleed del
    # metrÃ³nomo, banda ~2000Hz, mismo detector que usa el resto del
    # pipeline) que los estÃ­mulos de la cola candidata realmente suenan ahÃ­
    # -- si el metrÃ³nomo se sigue escuchando, la sesiÃ³n siguiÃ³; si no, no se
    # extiende mÃ¡s allÃ¡ de lo que la propia grabaciÃ³n respalda. Solo se
    # agrega un margen CHICO (no 3s) despuÃ©s del Ãºltimo estÃ­mulo CONFIRMADO,
    # para la reacciÃ³n del sujeto a ese Ãºltimo click real.
    #
    # Se recalculan los stim_times CRUDOS acÃ¡ (mismo cÃ¡lculo que la secciÃ³n
    # 11 mÃ¡s abajo, pero solo para esta verificaciÃ³n -- se descartan
    # despuÃ©s, la secciÃ³n 11 los vuelve a calcular con el start_time ya
    # definitivo) para conocer el Ãºltimo estÃ­mulo esperado ANTES de correr
    # el tracking (que es lo costoso) -- asÃ­ end_time queda bien desde el
    # principio, no se corrige despuÃ©s de haber trackeado de menos.
    MARGEN_POST_ULTIMO_ESTIMULO_S = 1.0   # tiempo de reacciÃ³n tras el Ãºltimo click, ademÃ¡s del piso
    try:
        stim_times_check, _ = _construir_stim_times(metronome_clean, metadata, sample_rate)
        if len(stim_times_check) > 0:
            # --- PISO obligatorio: la duraciÃ³n completa del protocolo segÃºn
            # el .wav del metrÃ³nomo (siempre completo, no depende de energÃ­a
            # de audio del video) -- se analiza SIEMPRE al menos hasta acÃ¡,
            # sin necesidad de confirmaciÃ³n por audio. El .wav es la fuente
            # de verdad de cuÃ¡nto dura el protocolo en sÃ­; si el corte por
            # energÃ­a (find_rhythmic_segment) quedÃ³ antes de eso, es un
            # corte prematuro por definiciÃ³n, no una decisiÃ³n a verificar.
            end_index_piso = start_index + int(stim_times_check[-1] * sample_rate)
            end_index_piso = min(end_index_piso, len(audio_data) - 1)
            if end_index_piso > end_index:
                print(f"  [Segmento rÃ­tmico] end_time por energÃ­a de audio "
                      f"({end_index/sample_rate:.2f}s, absoluto) termina antes de que el protocolo "
                      f"llegue a su Ãºltimo estÃ­mulo -- el .wav dura {stim_times_check[-1]:.2f}s desde "
                      f"que arranca a tapear (start_time={start_index/sample_rate:.2f}s), asÃ­ que en el "
                      f"eje de tiempo del VIDEO el protocolo deberÃ­a llegar hasta "
                      f"{start_index/sample_rate + stim_times_check[-1]:.2f}s (absoluto) -- se extiende "
                      f"end_time a {end_index_piso/sample_rate:.2f}s (piso obligatorio, sin verificaciÃ³n "
                      f"-- el .wav siempre estÃ¡ completo).")
                end_index = end_index_piso

            # --- MARGEN EXTRA de reacciÃ³n tras el Ãºltimo click, MÃS ALLÃ del
            # piso de arriba: acÃ¡ sÃ­ se verifica con el audio real de la
            # grabaciÃ³n (bleed del metrÃ³nomo, mismo detector que el resto
            # del pipeline) -- extender el piso ya es seguro (es la duraciÃ³n
            # del protocolo), pero extender MÃS ALLÃ de eso arriesga
            # capturar tracking de la mano ya en reposo si la grabaciÃ³n
            # terminÃ³ justo ahÃ­. Se confirma que el ÃšLTIMO estÃ­mulo del
            # protocolo realmente suena en la grabaciÃ³n antes de darle ese
            # margen extra -- si ni el Ãºltimo click se escucha, es seÃ±al de
            # que la grabaciÃ³n se cortÃ³ ahÃ­, y no se extiende mÃ¡s.
            fin_candidato = start_index + int(
                (stim_times_check[-1] + MARGEN_POST_ULTIMO_ESTIMULO_S) * sample_rate)
            fin_candidato = min(fin_candidato, len(audio_data) - 1)
            if fin_candidato > end_index:
                audio_candidato = audio_data[start_index:fin_candidato]
                offsets_candidato = _detectar_offset_audio_bleed(
                    stim_times_check, audio_candidato, sample_rate)
                if not np.isnan(offsets_candidato[-1]):
                    print(f"  [Segmento rÃ­tmico] Ãšltimo estÃ­mulo del protocolo confirmado en el audio "
                          f"real -- se agrega margen de reacciÃ³n de {MARGEN_POST_ULTIMO_ESTIMULO_S:.1f}s "
                          f"(end_time -> {fin_candidato/sample_rate:.2f}s).")
                    end_index = fin_candidato
                else:
                    print(f"  [Segmento rÃ­tmico] El Ãºltimo estÃ­mulo del protocolo NO se pudo confirmar "
                          f"en el audio real de la grabaciÃ³n (metrÃ³nomo inaudible ahÃ­) -- no se agrega "
                          f"margen extra de reacciÃ³n, probablemente la grabaciÃ³n terminÃ³ justo en el "
                          f"lÃ­mite del protocolo.")
    except Exception as e:
        print(f"  [Segmento rÃ­tmico] No se pudo verificar end_time contra el Ãºltimo estÃ­mulo "
              f"esperado ({e}) -- se usa el end_time por energÃ­a de audio sin ajustar.")

    audio_relevant = audio_data[start_index:end_index]
    start_time     = start_index / sample_rate
    end_time       = end_index   / sample_rate
    print(f"\nSegmento rÃ­tmico: {start_time:.2f}s â†’ {end_time:.2f}s "
          f"({len(audio_relevant)/sample_rate:.2f}s)")

    # ==========================================================================
    # 5. FILTRADO DE AUDIO [C-2.1, C-2.2]
    # ==========================================================================
    nyquist  = sample_rate / 2
    Wn       = [FC_LOW / nyquist, min(FC_HIGH / nyquist, 0.9999)]
    b_bs, a_bs = signal.butter(N=FILTRO_ORDEN, Wn=Wn, btype='bandstop')
    audio_filtrado = signal.filtfilt(b_bs, a_bs, audio_relevant)
    print(f"\nFiltro bandstop: {FC_LOW}â€“{FC_HIGH} Hz (orden {FILTRO_ORDEN}).")

    # ==========================================================================
    # 6. POTENCIA Y NORMALIZACIÃ“N
    # ==========================================================================
    potencia = float(np.mean(audio_filtrado**2))
    metadata['potencia_audio'] = potencia

    if potencia < UMBRAL_POTENCIA:
        raise LowAudioPowerError()
    else:
        audio_normalizado = audio_filtrado / np.max(np.abs(audio_filtrado))
        print(f"Potencia suficiente ({potencia:.2e}). Audio normalizado.")

    # ==========================================================================
    # 7. MEDIAPIPE â€” TRACKING
    # ==========================================================================
    cap = cv2.VideoCapture(video_path)
    if not cap.isOpened():
        raise VideoOpenError(video_path)

    ret, primer_frame = cap.read()
    if not ret:
        raise VideoReadError()

    fps_reportado = cap.get(cv2.CAP_PROP_FPS)
    total_frames_video = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    if total_frames_video <= 0 or (fps_reportado > 0 and total_frames_video / fps_reportado < 2.0):
        raise CorruptVideoError("no_frames")
    duracion_audio_s = len(audio_data) / sample_rate
    fps = total_frames_video / duracion_audio_s if duracion_audio_s > 0 else fps_reportado
    print(f"  FPS contenedor={fps_reportado:.4f} | FPS real (por duraciÃ³n de audio)={fps:.4f} "
          f"| diferencia={100*(fps-fps_reportado)/fps_reportado:.3f}%")
    primer_frame_rot = cv2.rotate(primer_frame, ROTACION_VIDEO) \
                       if ROTACION_VIDEO is not None else primer_frame
    height, width, _ = primer_frame_rot.shape


    BaseOptions      = mp.tasks.BaseOptions
    HandLandmarker   = mp.tasks.vision.HandLandmarker
    HandLandmarkerOptions = mp.tasks.vision.HandLandmarkerOptions
    VisionRunningMode     = mp.tasks.vision.RunningMode

    options = HandLandmarkerOptions(
        base_options=BaseOptions(model_asset_path=HAND_LANDMARKER_MODEL_PATH),
        running_mode=VisionRunningMode.VIDEO,
        num_hands=1,
        min_hand_detection_confidence=0.01,
        min_tracking_confidence=0.01
    )
    detector = HandLandmarker.create_from_options(options)

    landmark_names = [
        'muÃ±eca', 'pulgar_cmc', 'pulgar_mcp', 'pulgar_ip', 'pulgar_tip',
        'indice_mcp', 'indice_pip', 'indice_dip', 'indice_tip',
        'medio_mcp', 'medio_pip', 'medio_dip', 'medio_tip',
        'anular_mcp', 'anular_pip', 'anular_dip', 'anular_tip',
        'meÃ±ique_mcp', 'meÃ±ique_pip', 'meÃ±ique_dip', 'meÃ±ique_tip'
    ]

    landmarks_list = []
    frame_index    = 0
    n_frames_leidos_total = 0
    print(f"\nTracking MediaPipe ({start_time:.2f}s -> {end_time:.2f}s, lectura secuencial "
          f"desde el frame 0, sin seek)...")

    while cap.isOpened():
        ret, frame = cap.read()
        if not ret:
            break
        n_frames_leidos_total += 1
        frame_ts_real_ms = cap.get(cv2.CAP_PROP_POS_MSEC)
        t_actual_s = frame_ts_real_ms / 1000.0
        if t_actual_s < start_time:
            continue   # todavÃ­a no llegamos a la ventana de interÃ©s -- descartar y seguir leyendo
        if t_actual_s > end_time:
            break
        if ROTACION_VIDEO is not None:
            frame = cv2.rotate(frame, ROTACION_VIDEO)
        rgb_frame         = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        mp_image          = mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb_frame)
        # Timestamp REAL del contenedor (no frame_index/fps, que asume fps
        # constante) -- MediaPipe en modo VIDEO requiere timestamps
        # monÃ³tonos crecientes para su filtrado temporal interno; un valor
        # sintÃ©tico basado en fps promedio degrada la precisiÃ³n del
        # tracking en VFR incluso antes de llegar al problema de corte.
        frame_ts_ms       = int(frame_ts_real_ms)
        resultado         = detector.detect_for_video(mp_image, frame_ts_ms)

        fdata = {'frame': frame_index, 'frame_ts_real_ms': frame_ts_real_ms}
        if resultado.hand_landmarks:
            for idx, lm in enumerate(resultado.hand_landmarks[0]):
                fdata[f'{landmark_names[idx]}_x'] = lm.x
                fdata[f'{landmark_names[idx]}_y'] = lm.y
        else:
            for name in landmark_names:
                fdata[f'{name}_x'] = np.nan
                fdata[f'{name}_y'] = np.nan

        landmarks_list.append(fdata)
        frame_index += 1

    cap.release()
    detector.close()
    df = pd.DataFrame(landmarks_list)
    print(f"Tracking completado. Frames en la ventana de interÃ©s: {len(df)} "
          f"(de {n_frames_leidos_total} frames leÃ­dos en total del archivo).")

    # ==========================================================================
    # 8. INTERPOLACIÃ“N DEL DATAFRAME [C-3.1, C-3.2]
    # ==========================================================================
    df = df.sort_values(by='frame').reset_index(drop=True)

    coord_cols = [c for c in df.columns if c.endswith('_x') or c.endswith('_y')]

    total_frames = len(df)
    df['sin_tracking'] = df[coord_cols].isna().all(axis=1)
    df['incompleto']   = df[coord_cols].isna().any(axis=1)
    frames_sin = int(df['sin_tracking'].sum())
    frames_inc = int(df['incompleto'].sum())
    pct_interp = (frames_inc / total_frames) * 100

    # ctrl_cols se calcula DESPUÃ‰S de agregar sin_tracking/incompleto, para
    # que sobrevivan a la reconstrucciÃ³n del dataframe mÃ¡s abajo -- se usan
    # despuÃ©s para diferenciar, en un tap con "piso alto", si MediaPipe
    # realmente detectÃ³ la mano ahÃ­ (meseta superficial genuina) o si
    # directamente no habÃ­a datos (no es una decisiÃ³n real, es falta de
    # dato -- debe completarse con audio, no bloquear ese respaldo).
    ctrl_cols  = [c for c in df.columns if c not in coord_cols]

    print(f"\n--- Tracking ---")
    print(f"  Total: {total_frames} | Sin detecciÃ³n: {frames_sin} | Incompletos: {frames_inc}")

    if frames_inc > 0:
        df_ctrl   = df[ctrl_cols].copy()
        df_interp = df[coord_cols].interpolate(method='linear', limit_direction='both')
        df = pd.concat([df_ctrl, df_interp], axis=1)
        print(f"  Interpolado: {pct_interp:.1f}% de los frames.")

    metadata['calidad_tracking'] = 'baja' if pct_interp > UMBRAL_INTERPOLACION_PCT \
                                   else 'alta'
    if metadata['calidad_tracking'] == 'baja':
        import warnings as _w
        _w.warn(f'Calidad de tracking baja ({pct_interp:.1f}% frames sin detecciÃ³n).', LowTrackingQualityWarning, stacklevel=2)

    # ==========================================================================
    # 9. ESCALA CM/PX (DOS REFERENCIAS) [C-4.1, C-4.2]
    # ==========================================================================
    mano = metadata.get('mano', '')
    D_MM, D_FI = (D_MI_MM, D_MI_FI) if 'MI' in mano else (D_MD_MM, D_MD_FI)

    for name in landmark_names:
        df[f'{name}_x_px'] = df[f'{name}_x'] * width
        df[f'{name}_y_px'] = df[f'{name}_y'] * height

    dx1 = df['medio_tip_x_px'] - df['muÃ±eca_x_px']
    dy1 = df['medio_tip_y_px'] - df['muÃ±eca_y_px']
    dist1_px  = np.sqrt(dx1**2 + dy1**2)
    escala_MM = D_MM / np.nanmean(dist1_px)

    dx2 = df['indice_tip_x_px'] - df['indice_dip_x_px']
    dy2 = df['indice_tip_y_px'] - df['indice_dip_y_px']
    dist2_px  = np.sqrt(dx2**2 + dy2**2)
    escala_FI = D_FI / np.nanmean(dist2_px)

    escala_final = escala_MM   # Solo muÃ±ecaâ†’medio_tip, consistente con cÃ³digo original
    # escala_FI (dipâ†’tip Ã­ndice) descartada: el segmento es muy corto en coordenadas
    # normalizadas y produce valores aberrantes (ej. 228 cm/ud vs 63 cm/ud de escala_MM).

    tol_abs    = TOLERANCIA_ESCALA_PCT / 100.0
    pct_MM     = float(100 * np.sum(np.abs(dist1_px * escala_MM - D_MM) > tol_abs * D_MM) / total_frames)
    pct_FI     = float(100 * np.sum(np.abs(dist2_px * escala_FI - D_FI) > tol_abs * D_FI) / total_frames)
    metadata['pct_frames_fuera_escala_MM'] = round(pct_MM, 2)
    metadata['pct_frames_fuera_escala_FI'] = round(pct_FI, 2)

    print(f"\n--- Escala ---")
    print(f"  escala_MM={escala_MM:.4f} | escala_FI={escala_FI:.4f} | escala_final={escala_final:.4f} cm/ud")

    for name in landmark_names:
        if f'{name}_y_px' in df.columns:
            df[f'{name}_y_cm'] = df[f'{name}_y_px'] * escala_final

    # ==========================================================================
    # 10. CENTROIDE TIP Y ÃNGULO DE POSTURA
    # ==========================================================================
    df = calcular_centroide_tip(df)
    df = calcular_angulo_postura(df)

    df['tip_x']    = df['promedio_tip_x']
    df['tip_y']    = df['promedio_tip_y']
    # tip_y_cm en coordenadas MediaPipe (crece hacia abajo).
    # Lo convertimos a "altura sobre la mesa": mesa = 0 cm, valores positivos = mano arriba.
    # 1) Convertir a cm (coordenada absoluta del frame)
    tip_y_abs_cm = df['tip_y'] * height * escala_final
    # 2) Referencia de mesa: promedio de tip_y_cm en los picos de impacto (definido despuÃ©s,
    #    se recalcula una vez detectados tip_peaks_b; aquÃ­ dejamos la coordenada absoluta
    #    y referenciaremos tras la detecciÃ³n de picos).
    df['tip_y_cm'] = tip_y_abs_cm

    # ==========================================================================
    # 11. ESTÃMULOS Y PICOS DEL METRÃ“NOMO [N-8]
    # ==========================================================================
    tipo    = metadata.get('tipo_metronomo', 'ISO')
    bpm_ref = metadata.get('bpm', metadata.get('bpm_1', BPM_BASE))

    stim_times, peaks_por_tramo = _construir_stim_times(
        metronome_clean, metadata, sample_rate)
    metadata['metronomo_beats'] = peaks_por_tramo
    if len(stim_times) == 0:
        raise CorruptVideoError("no_stimuli")

    print(f"\nEstÃ­mulos detectados: {len(stim_times)} | "
          f"Primero: {stim_times[0]:.3f}s | Ãšltimo: {stim_times[-1]:.3f}s")

    # ==========================================================================
    # ==========================================================================
    stim_times_wav = stim_times.copy()

    stim_times_sync, metodo_sync, reporte_sincronizacion = calcular_stim_times_sincronizacion(
        stim_times_wav, metadata, audio_relevant, sample_rate)
    metadata['sincronizacion'] = reporte_sincronizacion

    mask_sin_sync = np.isnan(stim_times_sync)
    metodo_sync = metodo_sync.copy()
    if mask_sin_sync.any():
        metodo_sync[mask_sin_sync] = 'wav_fallback_individual'
    n_sin_sync = int(mask_sin_sync.sum())

    stim_times = np.where(mask_sin_sync, stim_times_wav, stim_times_sync)

    print(f"  [SINCRONIZACIÃ“N] stim_times actualizado -- decisiÃ³n: {reporte_sincronizacion.get('decision')} "
          f"| {len(stim_times) - n_sin_sync}/{len(stim_times)} beats sincronizados"
          + (f", {n_sin_sync} con .wav de respaldo individual (sin audio confiable)" if n_sin_sync > 0 else "") + ".")
    print(f"  [SINCRONIZACIÃ“N] A partir de acÃ¡, todo el pipeline (matching, Tr, deriva, CV, "
          f"stats_por_bpm) usa este stim_times sincronizado -- no el .wav crudo.")

    # ==========================================================================
    # 12. DETECCIÃ“N DE PICOS TIP (CORREGIDA)
    # ==========================================================================
    bpm_ref_video = metadata.get('bpm', metadata.get('bpm_1', BPM_BASE))

    # 1. Distancia DinÃ¡mica: Relajamos al 60% del perÃ­odo para no perder tappeos dobles
    distance_video = int(fps * (60.0 / bpm_ref_video * 0.6))

    # 2. Prominencia DinÃ¡mica: Se adapta automÃ¡ticamente a la amplitud de este paciente
    senal_y = df['tip_y'].values
    # Usamos el 40% de la desviaciÃ³n estÃ¡ndar de la seÃ±al como umbral mÃ­nimo
    prom_dinamica = max(0.002, np.std(senal_y) * 0.4)

    print(f"\nParÃ¡metros de detecciÃ³n dinÃ¡micos -> Distancia: {distance_video} frames | Prominencia: {prom_dinamica:.4f}")

    # SeÃ±al
    df['tip_x'] = df['promedio_tip_x']
    df['tip_y'] = df['promedio_tip_y']

    signal_values = df['tip_y'].values

    # Picos altos
    # Prominencia FIJA (0.005) como primer intento -- es el valor ya
    # validado en la mayorÃ­a de las sesiones (un valor mÃ¡s alto generÃ³
    # fallos en otras sesiones en el pasado, segÃºn indicÃ³ el usuario, asÃ­
    # que NO se reemplaza el comportamiento general). Solo si ese umbral
    # fijo no encuentra NINGÃšN pico en esta sesiÃ³n puntual (confirmado con
    # evidencia directa: tip_peaks_a vacÃ­o, rompÃ­a el pipeline mÃ¡s
    # adelante al acceder a tip_peaks_a[-1]) se reintenta como red de
    # rescate con la prominencia DINÃMICA (adaptada a la amplitud real de
    # esta sesiÃ³n) -- nunca se usa la dinÃ¡mica de entrada, solo cuando la
    # fija deja la sesiÃ³n sin ningÃºn pico detectable.
    # distance_video (60% del perÃ­odo esperado, calculada arriba) se pasa acÃ¡
    # -- estaba calculada pero nunca conectada al llamado real. Sin ella,
    # ruido/oscilaciÃ³n mÃ­nima de MediaPipe con prominencia apenas por encima
    # de 0.005 puede colarse como un pico alto espurio muy pegado (a veces
    # <150ms) a un pico real, insertando un ciclo falso que corre en +1 todo
    # el matching ordinal de ahÃ­ en mÃ¡s -- confirmado con evidencia directa
    # (sesiÃ³n S5_MD_ISO120_Med11, beat 6): un pico espurio a solo 0.133s de
    # distancia del pico real siguiente (con ISI esperado de 0.5s) hizo que
    # la respuesta real de ese beat quedara asignada, por posiciÃ³n, al
    # estÃ­mulo equivocado (fuera de rango en el matching segmentado),
    # perdiÃ©ndose del todo.
    prominencia_usada = 0.005
    tip_peaks_a = detect_peaks(df['tip_y'], prominence=prominencia_usada, distance=distance_video)

    if len(tip_peaks_a) == 0:
        print(f"  [Picos TIP] Prominencia fija ({prominencia_usada}) no encontrÃ³ ningÃºn pico -- "
              f"reintentando con prominencia dinÃ¡mica ({prom_dinamica:.4f}, adaptada a esta sesiÃ³n).")
        prominencia_usada = prom_dinamica
        tip_peaks_a = detect_peaks(df['tip_y'], prominence=prominencia_usada, distance=distance_video)

    if len(tip_peaks_a) == 0:
        raise NoPeaksDetectedError()

    # Picos bajos (para VISUALIZACIÃ“N): centro de meseta entre cada par de
    # picos altos REALES consecutivos -- sin marcadores de hueco, solo
    # para los grÃ¡ficos de diagnÃ³stico (siguen mostrando exactamente lo
    # que se detectÃ³).
    tip_peaks_b = []
    for i in range(len(tip_peaks_a) - 1):
        centro = detect_valley_center(signal_values, tip_peaks_a[i], tip_peaks_a[i + 1], n_local=5)
        tip_peaks_b.append(centro)

    # Pico bajo final (despuÃ©s del Ãºltimo pico alto)
    pico_bajo_final_idx = detect_valley_center(signal_values, tip_peaks_a[-1], len(signal_values) - 1, n_local=5)
    tip_peaks_b.append(pico_bajo_final_idx)

    # --- Picos altos FALTANTES (para el PAREO downstream) -------------------
    # Si el hueco entre dos picos altos consecutivos es mucho mayor al
    # tÃ­pico, es seÃ±al de que el sujeto no llegÃ³ a producir un movimiento
    # con prominencia suficiente para registrarse como pico -- NO de que
    # ese ciclo dure el doble. Buscar el pico bajo abarcando todo el hueco
    # (como hace tip_peaks_b arriba, para graficar) fusiona ESE ciclo
    # faltante con el siguiente en un solo par -- exactamente el mismo bug
    # de fondo ya corregido para la meseta superficial (correr el conteo
    # ordinal de ahÃ­ en mÃ¡s para TODO lo que sigue), pero un paso antes,
    # en la detecciÃ³n del pico alto en sÃ­ (confirmado visualmente contra
    # el video: justo despuÃ©s de una perturbaciÃ³n, un pico alto no llega
    # a superar la prominencia esperada).
    #
    # Se arma acÃ¡ una versiÃ³n PARALELA de tip_peaks_a/b (con sufijo
    # _pareo) que inserta NaN explÃ­cito por cada ciclo faltante estimado
    # -- son las que consume _calcular_resp_times_por_cruce, no las que se
    # grafican ni se guardan en el resultado.
    # gap_tipico se calcula LOCALMENTE (ventana de gaps cercanos), no como
    # una mediana global de toda la sesiÃ³n -- confirmado con evidencia
    # directa: en una sesiÃ³n PA (tempos distintos entre BPM1 y BPM2), la
    # mediana global (22.0 frames, mezclando el ISI mÃ¡s corto de BPM1 con
    # el mÃ¡s largo de BPM2) diluÃ­a el umbral lo suficiente como para que
    # un hueco genuino de 30 frames (ratio 1.36 contra el global, pero
    # 2.0 contra el tÃ­pico LOCAL de ~15) no llegara a superar el 1.5x
    # requerido -- el hueco real quedaba sin detectar, corriendo el
    # conteo ordinal de ahÃ­ en mÃ¡s. Una ventana de gaps cercanos (no toda
    # la sesiÃ³n) refleja el tempo real de esa zona puntual, sea cual sea
    # la secciÃ³n en la que caiga.
    gaps = np.diff(tip_peaks_a) if len(tip_peaks_a) > 1 else np.array([])
    ventana_gap_local = 6

    def _gap_tipico_local(idx_gap):
        lo = max(0, idx_gap - ventana_gap_local)
        hi = min(len(gaps), idx_gap + ventana_gap_local + 1)
        vecinos = np.delete(gaps[lo:hi], idx_gap - lo) if hi > lo else np.array([])
        return float(np.median(vecinos)) if len(vecinos) > 0 else None

    tip_peaks_a_pareo = [tip_peaks_a[0]] if len(tip_peaks_a) > 0 else []
    n_picos_faltantes = 0
    for i in range(1, len(tip_peaks_a)):
        gap = tip_peaks_a[i] - tip_peaks_a[i - 1]
        gap_tipico_local = _gap_tipico_local(i - 1)
        if gap_tipico_local is not None and gap_tipico_local > 0:
            n_ciclos = max(1, round(gap / gap_tipico_local))
            if n_ciclos >= 2 and gap > 1.5 * gap_tipico_local:
                for _ in range(n_ciclos - 1):
                    tip_peaks_a_pareo.append(np.nan)
                    n_picos_faltantes += 1
        tip_peaks_a_pareo.append(tip_peaks_a[i])

    if n_picos_faltantes > 0:
        print(f"  [Picos TIP] {n_picos_faltantes} pico(s) alto(s) faltante(s) detectado(s) (hueco "
              f"muy superior al tÃ­pico entre picos consecutivos, probable ausencia de reacciÃ³n) -- "
              f"se insertan como ciclos EXPLÃCITAMENTE sin dato, en vez de fusionarlos con el "
              f"ciclo siguiente (evita correr el conteo ordinal de ahÃ­ en mÃ¡s).")

    def _es_hueco(v):
        return v is None or (isinstance(v, float) and np.isnan(v))

    tip_peaks_b_pareo = []
    n_pareo = len(tip_peaks_a_pareo)
    for i in range(n_pareo - 1):
        pa_i = tip_peaks_a_pareo[i]
        if _es_hueco(pa_i):
            tip_peaks_b_pareo.append(np.nan)
            continue
        # Buscar el PRÃ“XIMO PICO REAL como lÃ­mite derecho para el valle --
        # no alcanza con mirar solo la posiciÃ³n siguiente: si esa posiciÃ³n
        # es un hueco (ciclo faltante insertado por el algoritmo de picos
        # faltantes), no hay ninguna razÃ³n para descartar el valle de ESTE
        # pico, que sigue siendo real. Confirmado con evidencia directa: un
        # pico real (t=10.43s) seguido de un hueco insertado (por un gap
        # grande hasta el prÃ³ximo pico real, t=11.40s) se quedaba con
        # pb=NaN -- perdiendo por completo la respuesta al estÃ­mulo de la
        # perturbaciÃ³n, aunque la seÃ±al SÃ cruzaba el umbral con claridad
        # en ese tramo (visible en el grÃ¡fico crudo) y habÃ­a audio de
        # respaldo disponible. Se busca hacia adelante hasta el prÃ³ximo
        # pico real (saltando huecos consecutivos si los hubiera) y se usa
        # ESE como lÃ­mite -- el valle real puede estar mÃ¡s allÃ¡ del hueco,
        # no desaparece porque el ciclo inmediato siguiente se haya
        # perdido.
        j = i + 1
        while j < n_pareo and _es_hueco(tip_peaks_a_pareo[j]):
            j += 1
        if j >= n_pareo:
            tip_peaks_b_pareo.append(
                detect_valley_center(signal_values, int(pa_i), len(signal_values) - 1, n_local=5))
        else:
            pa_sig = tip_peaks_a_pareo[j]
            tip_peaks_b_pareo.append(detect_valley_center(signal_values, int(pa_i), int(pa_sig), n_local=5))

    ultimo = tip_peaks_a_pareo[-1] if len(tip_peaks_a_pareo) > 0 else None
    if _es_hueco(ultimo):
        tip_peaks_b_pareo.append(np.nan)
    else:
        tip_peaks_b_pareo.append(detect_valley_center(signal_values, int(ultimo), len(signal_values) - 1, n_local=5))

    tip_peaks_b = np.array(tip_peaks_b)


    # Prints
    if metadata['tipo_metronomo'] == 'ISO':
        print(f"Se detectaron {len(tip_peaks_a)} picos altos en la punta de los dedos")
        print(f"Se detectaron {len(tip_peaks_b)} picos bajos en la punta de los dedos \n")

    if metadata['tipo_metronomo'] == 'PA':
        total_clics = metadata['clics_1'] + metadata['clics_2']
        print(f"Clics no sincronizados: {total_clics - len(tip_peaks_a)}")

    if metadata['tipo_metronomo'] == 'PR':
        total_clics = metadata['clics_1'] + metadata['clics_rampa'] + metadata['clics_2']
        print(f"Clics no sincronizados: {total_clics - len(tip_peaks_a)}")

    # tapping_signal ya se puede armar acÃ¡ (audio_normalizado ya estÃ¡
    # calculado mÃ¡s arriba) para poder calibrar el umbral dinÃ¡mico contra
    # el audio -- se vuelve a armar mÃ¡s abajo, en la secciÃ³n de audio,
    # sin problema (misma cuenta, redundante pero no rompe nada).
    tapping_signal_calib = np.abs(audio_normalizado) if audio_normalizado is not None else None

    resp_times_video, resp_times_s, cruces_video, umbral_cruce, umbral_base, mask_meseta_superficial = _calcular_resp_times_por_cruce(
        df, tip_peaks_a_pareo, tip_peaks_b_pareo, fps, start_time,
        tapping_signal=tapping_signal_calib, metadata=metadata,
        sample_rate=sample_rate, stim_times=stim_times)

    # CorrecciÃ³n del sesgo de tasa del reloj de la cÃ¡mara (compartido entre
    # audio y video del mismo dispositivo), calibrado con el estÃ­mulo real
    # (.wav CRUDO, no el ya sincronizado -- ver nota en el paso 11.5) contra
    # el estÃ­mulo tal como lo capta el micrÃ³fono de la cÃ¡mara (banda
    # ~2000Hz, la frecuencia del click del metrÃ³nomo).
    calibracion_reloj = calibrar_deriva_reloj_camara(audio_relevant, sample_rate, stim_times_wav)

    if not calibracion_reloj['aplicable']:
        umbral_r2_respaldo = 0.8
        mejor_label, mejor_r2, mejor_calib = None, umbral_r2_respaldo, None
        for label, calib_seccion in reporte_sincronizacion.get('calibracion_por_seccion', {}).items():
            r2_seccion = calib_seccion.get('r2')
            if r2_seccion is not None and calib_seccion.get('slope_ms_s') is not None and r2_seccion > mejor_r2:
                mejor_r2, mejor_label, mejor_calib = r2_seccion, label, calib_seccion
        if mejor_calib is not None:
            calibracion_reloj = {
                'slope_ms_s': mejor_calib['slope_ms_s'], 'r2': mejor_r2,
                'n_detectados': mejor_calib.get('n_detectados'), 'aplicable': True,
                'respaldo_de_seccion': mejor_label,
            }
            print(f"  [CalibraciÃ³n de reloj] La calibraciÃ³n de toda la sesiÃ³n no era confiable -- "
                  f"se usa como respaldo la pendiente de '{mejor_label}' (rÂ²={mejor_r2:.4f}, ya "
                  f"calibrada aparte) en vez de dejar resp_times_s sin corregir.")

    if calibracion_reloj['aplicable']:
        tasa = calibracion_reloj['slope_ms_s'] / 1000.0   # ms/s -> fracciÃ³n adimensional
        resp_times_s = resp_times_s / (1 + tasa)
        print(f"  [CalibraciÃ³n de reloj] resp_times_s corregido por tasa {tasa*100:+.4f}%")

    df = generar_senal_ideal(df, metadata, fps)

    primer_reaccion = tip_peaks_b[0] / fps
    beats_antes_reaccion = int(np.sum(stim_times < primer_reaccion))
    print(f"Primer movimiento en t={primer_reaccion:.2f}s | Beats antes de reaccionar: {beats_antes_reaccion}")

   # ==========================================================================
    # 14. AMPLITUD [cm] Y TIEMPOS DE ASCENSO/DESCENSO
    # ==========================================================================
    cambios = graficar_cambios_bpm(metadata, start_time, ax=None)

    amplitudes_por_tramo  = _calcular_amplitudes_por_tramo(
        df, tip_peaks_a, tip_peaks_b, metadata, fps, cambios)
    tiempos_por_tramo     = _calcular_tiempos_ascenso_descenso(
        df, tip_peaks_a, tip_peaks_b, metadata, fps, cambios)
    tiempo_apoyo_ms, tiempo_alzada_ms, mask_apoyo, mask_alzada = _calcular_tiempos_apoyo_alzada(
        df, tip_peaks_a, tip_peaks_b, fps, umbral_base)

    # ==========================================================================
    # 15. CINEMÃTICA [C-8.1 â€“ C-8.5]
    # ==========================================================================
    bpm_cinem = metadata.get('bpm', metadata.get('bpm_1', BPM_BASE))
    ciclo_frames = max(1, int(fps * 60.0 / bpm_cinem))
    wl = max(SAVGOL_POLYORDER + 2, ciclo_frames // 3)
    if wl % 2 == 0:
        wl += 1

    sm_r, ha_r, cu_r = calcular_metricas_movimiento(df, 'tip',   fps, wl, SAVGOL_POLYORDER)
    sm_i, ha_i, cu_i = calcular_metricas_movimiento(df, 'ideal', fps, wl, SAVGOL_POLYORDER)

    def _ratio(a, b):
        return round(float(a) / float(b), 4) if b and b > 1e-10 else None

    print(f"  Suavidad  real/ideal: {sm_r:.4f}/{sm_i:.4f} -> {_ratio(sm_r, sm_i)}")
    print(f"  Armonia   real/ideal: {ha_r:.4f}/{ha_i:.4f} -> {_ratio(ha_r, ha_i)}")
    print(f"  Curvatura real/ideal: {cu_r:.4f}/{cu_i:.4f} -> {_ratio(cu_r, cu_i)}")

    # ==========================================================================
    # 16. ASINCRONÃA DESDE VIDEO (stim_times vs resp_times) [N-7, N-4]
    # ==========================================================================
    output_video, resp_iso_v, stim_iso_v = procesar_asincronias_sesion(
        stim_times, resp_times_s, metadata, TARGET_BPM_ISO, usar_ordinal=True)
    salto_segmentado_track = dict(ULTIMO_SALTO_SEGMENTADO)   # copia, antes de que otra llamada lo pise

    # [MESETA SUPERFICIAL -> por estÃ­mulo] resp_times_s trae huecos (NaN) en
    # los taps descartados por no representar un apoyo real (ver
    # _calcular_resp_times_por_cruce). output_video['assigned_stim'] ahora
    # conserva a quÃ© estÃ­mulo le corresponde CADA posiciÃ³n, incluidos esos
    # huecos (ver compute_asyn_ordinal) -- se usa para marcar, por
    # ESTÃMULO, cuÃ¡les tuvieron un tap real que se descartÃ³ a propÃ³sito
    # (distinto de "no hubo ningÃºn tap cerca", que es una falla de
    # tracking genuina). Esto se usa mÃ¡s abajo en la fusiÃ³n track+audio:
    # un descarte a propÃ³sito NO debe taparse con un respaldo de audio --
    # el track ya "sabe" que ese tap no fue una respuesta real, y el
    # audio puede confundirse con ruido/bleed justo en esas zonas
    # (confirmado con evidencia directa: un candidato de audio "pegado" a
    # ~30ms en un beat donde el sujeto, segÃºn el video, no llegÃ³ a bajar
    # la mano -- un falso positivo).
    mask_resp_es_hueco = np.isnan(resp_times_s) & mask_meseta_superficial
    idx_stim_meseta = output_video.loc[mask_resp_es_hueco, 'assigned_stim'].astype(int).values
    idx_stim_meseta = idx_stim_meseta[idx_stim_meseta >= 0]
    mask_meseta_por_estimulo = np.zeros(len(stim_times), dtype=bool)
    mask_meseta_por_estimulo[idx_stim_meseta] = True

    asinc_video_ms = output_video['asyn'].dropna().values
    # VersiÃ³n alineada con stim_times (mantiene NaN): necesaria para calcular_todos_los_cuantificadores
    asinc_video_ms_aligned = output_video['asyn'].values
    stats_asinc_video = calcular_estadisticas(asinc_video_ms)

    iti_video_ms   = np.diff(resp_times_s) * 1000.0
    bpm_iti_ref    = metadata.get('bpm', metadata.get('bpm_1', BPM_BASE))
    iti_video_desv = iti_video_ms - 60.0 * 1000.0 / bpm_iti_ref
    stats_iti_video = calcular_estadisticas(iti_video_desv)

    print(f"\n--- AsincronÃ­a desde VIDEO ---")
    print(f"  Respuestas: {len(resp_times_s)} | Pareadas: {len(asinc_video_ms)}")
    print(f"  Media: {stats_asinc_video.get('mean_ms', 0):.2f} ms | "
          f"std: {stats_asinc_video.get('std_ms', 0):.2f} ms")
    print(f"  NOTA: ResoluciÃ³n temporal del video = Â±{1000/(2*fps):.1f} ms a {fps:.1f} fps")

    graficos = {}

    # ==========================================================================
    # 17. ASINCRONÃA DESDE AUDIO [N-7, N-4]
    # ==========================================================================
    resultados_tramos_audio = []
    resp_times_audio_all    = np.array([])
    picos_estimulo_audio    = np.array([])
    picos_respuesta_audio   = np.array([])
    asinc_audio_all         = np.array([])
    salto_segmentado_audio  = {'detectado': False, 'idx_estimulo': None, 'tiempo_s': None, 'magnitud_ms': None}

    if audio_normalizado is not None:
        tapping_signal = np.abs(audio_normalizado)

        # SegmentaciÃ³n de tapping segÃºn tipo
        tramos_seg = _segmentar_tapping(tapping_signal, metadata, sample_rate)

        # Construir stim_times unificado (ya calculado arriba) y resp_times por tramo
        resp_times_audio_all_list = []

        # --- AsincronÃ­a TOTAL (todos los tappeos juntos) para PA y PR ---
        if tipo in ('PA', 'PR'):
            # Recolectamos todos los tiempos de tapping antes del loop
            t_tapping_all_list = []
            for tramo in tramos_seg:
                offset = tramo['offset_muestras']
                t_s    = tramo['tapping_peaks'] / sample_rate + (
                         offset / sample_rate if offset > 0 else 0.0)
                t_tapping_all_list.append(t_s)
            t_tapping_total = np.sort(np.concatenate(t_tapping_all_list)) \
                              if t_tapping_all_list else np.array([])

            if len(t_tapping_total) > 0:
                out_total, _, _ = procesar_asincronias_sesion(
                    stim_times, t_tapping_total, metadata, TARGET_BPM_ISO)
                asinc_total   = out_total['asyn'].dropna().values
                stats_total   = calcular_estadisticas(asinc_total)

                print(f"\n--- AsincronÃ­a audio TOTAL ({tipo}) ---")
                print(f"  Tappeos: {len(t_tapping_total)} | Pareados: {len(asinc_total)}")
                print(f"  media={stats_total.get('mean_ms', 0):.2f} ms  "
                      f"std={stats_total.get('std_ms', 0):.2f} ms")

                pass  # grÃ¡fico de asincronÃ­a audio total removido a propÃ³sito

        for tramo in tramos_seg:
            label_t   = tramo['label']
            bpm_t     = tramo['bpm']
            tapping_t = tramo['tapping_peaks']   # en muestras
            offset    = tramo['offset_muestras']

            # Tiempos absolutos de tapping en segundos (referenciados al inicio del metrÃ³nomo)
            t_tapping_s = tapping_t / sample_rate + (offset / sample_rate
                          if offset > 0 else 0.0)
            resp_times_audio_all_list.append(t_tapping_s)

            # Detectar repetidos [N-10]
            repetidos = calcular_repetidos_tramo(tapping_t, bpm_t, sample_rate)

            # AsincronÃ­a del tramo con el metrÃ³nomo (subset de stim_times)
            # Usamos stim_times global y procesar_asincronias_sesion con los resp del tramo
            out_tramo, _, _ = procesar_asincronias_sesion(
                stim_times, t_tapping_s, metadata, TARGET_BPM_ISO)
            asinc_t   = out_tramo['asyn'].dropna().values
            stats_a   = calcular_estadisticas(asinc_t)

            iti_t     = np.diff(tapping_t) * 1000.0 / sample_rate \
                        if len(tapping_t) > 1 else np.array([])
            iti_desv  = iti_t - 60.0 * 1000.0 / bpm_t \
                        if iti_t.size > 0 else np.array([])
            stats_iti_a = calcular_estadisticas(iti_desv)

            print(f"\n--- Tramo audio: {label_t} ---")
            print(f"  Tappeos: {len(tapping_t)} | Repetidos: {repetidos} | "
                  f"Pareados: {len(asinc_t)}")
            print(f"  AsincronÃ­a: media={stats_a.get('mean_ms', 0):.2f} ms "
                  f"std={stats_a.get('std_ms', 0):.2f} ms")

            resultados_tramos_audio.append({
                'label':           label_t,
                'bpm':             bpm_t,
                'n_tappeos':       int(len(tapping_t)),
                'n_repetidos':     int(repetidos),
                'n_pareados':      int(len(asinc_t)),
                'asincronia_audio': stats_a,
                'iti_audio':       stats_iti_a
            })

        resp_times_audio_all = np.concatenate(resp_times_audio_all_list) \
                               if resp_times_audio_all_list else np.array([])
        asinc_audio_all = np.array(
            [t['asincronia_audio'].get('mean_ms', np.nan)
             for t in resultados_tramos_audio
             if t['asincronia_audio']] if resultados_tramos_audio else [])


        picos_estimulo_audio, picos_respuesta_audio = _separar_estimulo_respuesta_audio(
            tapping_signal, stim_times, sample_rate)

        if len(picos_estimulo_audio) >= 3:
            n_comparables = min(len(picos_estimulo_audio), len(stim_times))
            desfasaje_estimulo_ms = (picos_estimulo_audio[:n_comparables] -
                                     stim_times[:n_comparables]) * 1000.0
            print(f"\n--- [Punto 2] VerificaciÃ³n del estÃ­mulo en el audio del video ---")
            print(f"  Clicks de metrÃ³nomo detectados en el audio del video: {len(picos_estimulo_audio)}")
            print(f"  Desfasaje estÃ­mulo-audio vs. stim_times (.wav): "
                  f"mediana={np.median(desfasaje_estimulo_ms):+.2f} ms | "
                  f"std={np.std(desfasaje_estimulo_ms):.2f} ms | "
                  f"n comparados={n_comparables}")
            if abs(np.median(desfasaje_estimulo_ms)) > 50:
                print(f"  AVISO: el desfasaje mediana supera Â±50ms -- revisar si start_time "
                      f"estÃ¡ bien calibrado.")
        else:
            print(f"\n--- [Punto 2] No se detectÃ³ bleed del metrÃ³nomo en el audio del video "
                  f"(menos de 3 clicks encontrados) -- no se puede verificar el estÃ­mulo por esta vÃ­a.")

    else:
        print("\nAudio insuficiente. AnÃ¡lisis solo desde video.")



    # ==========================================================================
    # 20. MÃ‰TRICAS DE VIDEO [C-9.3]
    # ==========================================================================
    metricas_video = {
        'amplitudes_por_tramo':        amplitudes_por_tramo,
        'tiempos_por_tramo':           tiempos_por_tramo,
        'tiempo_apoyo_ms':             round(float(tiempo_apoyo_ms),  2),
        'tiempo_alzada_ms':            round(float(tiempo_alzada_ms), 2),
        'smoothness_real':             round(float(sm_r), 6),
        'harmony_real':                round(float(ha_r), 6),
        'curvature_real':              round(float(cu_r), 6),
        'smoothness_relativo':         _ratio(sm_r, sm_i),
        'harmony_relativo':            _ratio(ha_r, ha_i),
        'curvature_relativo':          _ratio(cu_r, cu_i),
        'beats_antes_reaccion':        beats_antes_reaccion,
        'calibracion_reloj_camara':    calibracion_reloj,
        'salto_segmentado_track':      salto_segmentado_track,
        'salto_segmentado_audio':      salto_segmentado_audio,
        'calidad_tracking':            metadata['calidad_tracking'],
        'pct_fuera_escala_MM':         metadata['pct_frames_fuera_escala_MM'],
        'pct_fuera_escala_FI':         metadata['pct_frames_fuera_escala_FI'],
        'resolucion_temporal_video_ms': round(1000.0 / fps, 2),
        'nota_video': (f"ResoluciÃ³n temporal Â±{1000/(2*fps):.1f} ms "
                       f"(Nyquist a {fps:.1f} fps)."),
    }


    t_pert = cambios if isinstance(cambios, float) else (cambios[0] if cambios else None)
    t_r_ini = cambios[0] if isinstance(cambios, tuple) else None
    t_r_fin = cambios[1] if isinstance(cambios, tuple) else None

    # Construir array de asincronÃ­a indexado por estÃ­mulo (len == len(stim_times)),
    # con NaN donde no hubo respuesta asignada. Esto permite que calcular_pendiente_adaptacion
    # y calcular_tiempo_restablecimiento hagan la mÃ¡scara temporal correctamente.
    output_video_comp = output_video   # sin compensaciÃ³n A/V (secciÃ³n de concordancia removida)
    asinc_por_stim_track = construir_asyn_por_estimulo(output_video_comp, len(stim_times))
    asinc_por_stim_track = _reasignar_o_descartar_tras_hueco(asinc_por_stim_track, stim_times)

    # ==========================================================================
    # [FUSIÃ“N] ComparaciÃ³n y combinaciÃ³n track (video) + audio del video
    # ==========================================================================
    # Track = fuente primaria (mÃ¡s confiable, no depende del micrÃ³fono ni de
    # ruido ambiente). Audio del video = respaldo, solo para los beats donde
    # el track no tiene dato (mano fuera de cuadro, tracking perdido, etc.).
    #
    # Se matchea el audio contra stim_times con el mismo esquema ordinal que
    # el track (1:1 por orden, no por ventana), asÃ­ queda directamente
    # comparable beat a beat con asinc_por_stim_track.
    #
    # Como ambas fuentes miden el "mismo" contacto por mÃ©todos fÃ­sicos
    # distintos (cruce de umbral en posiciÃ³n vs. sonido del impacto), es
    # esperable un desfasaje sistemÃ¡tico CONSTANTE entre ellas, no ausencia
    # de desfasaje. Por eso el sesgo se estima (mediana, robusta a outliers)
    # y se descuenta antes de decidir si un beat puntual es "discrepante".
    resp_times_audio_todos = np.sort(resp_times_audio_all) if len(resp_times_audio_all) else np.array([])

    if len(resp_times_audio_todos) > 0:
        # CorrecciÃ³n de reloj de cÃ¡mara (misma calibraciÃ³n que ya se aplicÃ³
        # a resp_times_s/track): los tiempos de audio detectados tambiÃ©n
        # estÃ¡n medidos con el reloj SIN corregir de la cÃ¡mara -- sin esto,
        # comparar contra el track (ya corregido) genera una pendiente
        # falsa que no tiene que ver con quÃ© tan bien se detecta el golpe,
        # sino con estar comparando dos relojes distintos.
        if calibracion_reloj['aplicable']:
            tasa_audio = calibracion_reloj['slope_ms_s'] / 1000.0
            resp_times_audio_todos = resp_times_audio_todos / (1 + tasa_audio)

        # Vuelta a compute_asyn_ordinal (correspondencia posiciÃ³n-a-posiciÃ³n
        # con offset global): la detecciÃ³n original (_segmentar_tapping,
        # ventana ancha) tiene cobertura casi completa (~118/120 en la
        # sesiÃ³n de prueba), a diferencia del intento de prominencia de 2
        # niveles (44-79% de cobertura) que rompÃ­a este mÃ©todo por huecos
        # dispersos -- con cobertura casi completa, compute_asyn_ordinal
        # es apropiado de nuevo.
        # Matching SEGMENTADO (igual criterio que ya se validÃ³ para track):
        # si hay un salto de nivel sostenido en la asincronÃ­a por audio
        # (una respuesta perdida/de mÃ¡s en el matching, corriendo el
        # offset para todo lo que sigue), re-matchea por separado antes y
        # despuÃ©s del salto en vez de un Ãºnico offset para toda la sesiÃ³n.
        output_audio_ordinal = compute_asyn_ordinal_segmentado(stim_times, resp_times_audio_todos)
        salto_segmentado_audio = dict(ULTIMO_SALTO_SEGMENTADO)   # copia, antes de que otra llamada lo pise
        asinc_por_stim_audio = construir_asyn_por_estimulo(output_audio_ordinal, len(stim_times))
        asinc_por_stim_audio = _reasignar_o_descartar_tras_hueco(asinc_por_stim_audio, stim_times)

        if beats_antes_reaccion > 0:
            asinc_por_stim_audio[:beats_antes_reaccion] = np.nan
    else:
        asinc_por_stim_audio = np.full(len(stim_times), np.nan)

    if mask_resp_es_hueco.any():
        tasa_camara_meseta = calibracion_reloj['slope_ms_s'] / 1000.0 if calibracion_reloj['aplicable'] else 0.0
        UMBRAL_MESETA_DISCREPANCIA_MS = 80.0
        idx_hueco_meseta = np.where(mask_resp_es_hueco)[0]
        assigned_meseta = output_video.loc[idx_hueco_meseta, 'assigned_stim'].astype(int).values
        resp_crudo_meseta = resp_times_video[idx_hueco_meseta]
        mask_meseta_pero_discrepante = np.zeros(len(stim_times), dtype=bool)
        for tap_pos, stim_idx, t_resp_crudo in zip(idx_hueco_meseta, assigned_meseta, resp_crudo_meseta):
            if stim_idx < 0 or stim_idx >= len(stim_times) or np.isnan(t_resp_crudo):
                continue
            audio_val = asinc_por_stim_audio[stim_idx]
            if np.isnan(audio_val):
                continue
            t_resp_corregido_s = (t_resp_crudo - start_time) / (1 + tasa_camara_meseta)
            asinc_crudo_ms = (t_resp_corregido_s - stim_times[stim_idx]) * 1000.0
            if abs(asinc_crudo_ms - audio_val) <= UMBRAL_MESETA_DISCREPANCIA_MS:
                mask_meseta_pero_discrepante[stim_idx] = True
        n_meseta_rescatada = int(mask_meseta_pero_discrepante.sum())
        if n_meseta_rescatada > 0:
            print(f"  [Meseta superficial] {n_meseta_rescatada} beat(s) marcados como meseta "
                  f"superficial, pero el cruce crudo (antes de excluirse) coincide con el audio "
                  f"(dentro de {UMBRAL_MESETA_DISCREPANCIA_MS:.0f}ms) -- probable apoyo real con "
                  f"tracking impreciso, no meseta genuina. Se libera el respaldo de audio ahÃ­.")

        # --- [PISO TRUNCADO POR GAP] El "piso" de un candidato a meseta puede
        # no ser el contacto real, sino el borde de entrada a un gap de
        # MediaPipe justo despuÃ©s del pico bajo (tip_peaks_b) --
        # detect_valley_center toma el punto mÃ¡s bajo DISPONIBLE entre dos
        # picos altos, y si el prÃ³ximo dato real ya estÃ¡ en la subida (el
        # tramo intermedio se perdiÃ³), el verdadero mÃ­nimo -- mÃ¡s profundo,
        # el contacto real -- quedÃ³ escondido en el gap y nunca se midiÃ³.
        # Confirmado con evidencia directa (sesiÃ³n S5_MD_ISO132_Med9, beats
        # 105-115): en 9 de 9 candidatos a meseta consecutivos, el gap de
        # MediaPipe arrancaba exactamente 1 frame despuÃ©s de tip_peaks_b --
        # el "piso" registrado era el Ãºltimo frame antes de perder tracking,
        # no un mÃ­nimo real.
        #
        # Este caso es DISTINTO del rescate por discrepancia de arriba: ahÃ­
        # se exige que el cruce crudo estÃ© a â‰¤80ms de audio, pero un piso
        # truncado sesga el cruce crudo sistemÃ¡ticamente TEMPRANO (confirmado
        # en la misma sesiÃ³n: ~110-150ms antes que audio, por encima del
        # umbral de 80ms), asÃ­ que ese rescate puede fallar aunque el apoyo
        # haya sido real. AcÃ¡ el criterio no depende de quÃ© tan lejos cae el
        # cruce crudo: si el piso estÃ¡ truncado por un gap Y hay una
        # respuesta de audio disponible para ese estÃ­mulo, se libera -- el
        # audio es la mejor fuente disponible en ese caso, coincida o no
        # estrechamente con el cruce crudo (que ya sabemos que puede venir
        # sesgado por el mismo motivo).
        #
        # MARGEN_POST_PB_FRAMES: ventana de frames despuÃ©s de tip_peaks_b
        # donde se busca el gap. 5 frames es un valor conservador (en la
        # sesiÃ³n de referencia el gap arrancaba a 1 frame en el 100% de los
        # casos) -- ajustar si en otras sesiones el patrÃ³n difiere.
        MARGEN_POST_PB_FRAMES = 5
        sin_tracking_arr_meseta = df['sin_tracking'].to_numpy()
        mask_meseta_piso_truncado = np.zeros(len(stim_times), dtype=bool)
        for tap_pos, stim_idx in zip(idx_hueco_meseta, assigned_meseta):
            if stim_idx < 0 or stim_idx >= len(stim_times):
                continue
            if mask_meseta_pero_discrepante[stim_idx]:
                continue  # ya rescatado por el criterio de discrepancia, no duplicar
            audio_val = asinc_por_stim_audio[stim_idx]
            if np.isnan(audio_val):
                continue
            if tap_pos >= len(tip_peaks_b_pareo):
                continue
            pb_j = tip_peaks_b_pareo[tap_pos]
            if pb_j is None or (isinstance(pb_j, float) and np.isnan(pb_j)):
                continue
            pb_j = int(pb_j)
            fin_ventana = min(pb_j + 1 + MARGEN_POST_PB_FRAMES, len(sin_tracking_arr_meseta))
            if sin_tracking_arr_meseta[pb_j + 1:fin_ventana].any():
                mask_meseta_piso_truncado[stim_idx] = True
        n_piso_truncado = int(mask_meseta_piso_truncado.sum())
        if n_piso_truncado > 0:
            print(f"  [Meseta superficial] {n_piso_truncado} beat(s) con el piso posiblemente "
                  f"truncado por un gap de MediaPipe justo despuÃ©s del valle (dentro de "
                  f"{MARGEN_POST_PB_FRAMES} frames) -- se libera el respaldo de audio (no se exige "
                  f"coincidencia estrecha con el cruce crudo, que puede estar sesgado por el mismo "
                  f"motivo).")

        mask_meseta_por_estimulo = (mask_meseta_por_estimulo
                                     & ~mask_meseta_pero_discrepante
                                     & ~mask_meseta_piso_truncado)

    mask_ambos = ~np.isnan(asinc_por_stim_track) & ~np.isnan(asinc_por_stim_audio)
    discrepancia_video_audio = asinc_por_stim_track - asinc_por_stim_audio

    UMBRAL_DISCREPANCIA_MS = 25.0   # â‰ˆ1.5x la resoluciÃ³n temporal del video (Â±1000/(2Â·fps))
    VENTANA_SESGO_BEATS    = 15     # ventana mÃ³vil para el sesgo local (drift de reloj A/V)

    # Sesgo GLOBAL (mediana), se guarda como referencia/diagnÃ³stico pero ya
    # NO se usa para la bandera -- el sesgo track-audio puede derivar a lo
    # largo de la sesiÃ³n (reloj de audio y de video no perfectamente
    # sincronizados), asÃ­ que comparar contra un Ãºnico valor fijo marca
    # como "discrepantes" beats que en realidad siguen un patrÃ³n local
    # consistente, solo que distinto del promedio de toda la sesiÃ³n.
    sesgo_video_audio_ms = float(np.nanmedian(discrepancia_video_audio[mask_ambos])) \
                           if mask_ambos.sum() >= 3 else None

    # Sesgo LOCAL (mediana en ventana mÃ³vil centrada en cada beat): sÃ­ se
    # usa para la bandera, porque sigue el drift en vez de compararlo contra
    # un valor Ãºnico.
    sesgo_local_ms = np.full(len(stim_times), np.nan)
    idx_validos = np.where(mask_ambos)[0]
    if len(idx_validos) >= 3:
        for i in range(len(stim_times)):
            lo, hi = i - VENTANA_SESGO_BEATS, i + VENTANA_SESGO_BEATS + 1
            vecinos = idx_validos[(idx_validos >= lo) & (idx_validos < hi)]
            if len(vecinos) >= 3:
                sesgo_local_ms[i] = np.median(discrepancia_video_audio[vecinos])

    bandera_discrepante = np.zeros(len(stim_times), dtype=bool)
    residual_discrepancia = discrepancia_video_audio - sesgo_local_ms
    mask_residual_valido = mask_ambos & ~np.isnan(sesgo_local_ms)
    bandera_discrepante[mask_residual_valido] = \
        np.abs(residual_discrepancia[mask_residual_valido]) > UMBRAL_DISCREPANCIA_MS

    # FusiÃ³n: track primero; donde el track no tiene dato, se usa audio --
    # pero solo a partir de beats_antes_reaccion (calculado independiente
    # por video). Antes de eso, un "candidato" de audio es mÃ¡s probable que
    # sea ruido/remanente del bleed que una respuesta real -- el sujeto
    # todavÃ­a no habÃ­a reaccionado, asÃ­ que no hay nada que sustituir.
    #
    # TAMPOCO se sustituye en los estÃ­mulos marcados en
    # mask_meseta_por_estimulo -- ahÃ­ el track SÃ tuvo un tap, pero se
    # descartÃ³ a propÃ³sito por no representar un apoyo real (confirmado
    # visualmente contra el video: el sujeto no llegÃ³ a bajar la mano).
    # Es una falla DISTINTA de "no hay tap cerca" (que sÃ­ amerita
    # respaldo de audio) -- acÃ¡ el track ya tiene la respuesta correcta
    # ("no hubo apoyo real"), y el audio puede confundir un falso
    # positivo (ruido, bleed) con una respuesta genuina justo en esa
    # ambigÃ¼edad.
    #
    # --- Track puede fallar produciendo un valor IMPLAUSIBLE (no solo
    # ausencia de dato) -- ej. un salto de tracking que da 1000-3500ms de
    # "asincronÃ­a", claramente imposible como reacciÃ³n real. Confirmado
    # con evidencia directa: en tramos donde el tracking falla (varios
    # beats consecutivos), track puede seguir devolviendo UN valor (no
    # NaN) pero completamente errÃ³neo, mientras el audio se mantiene
    # estable durante todo ese tramo -- la fusiÃ³n existente (basada solo
    # en NaN) nunca detectaba esto, track seguÃ­a usÃ¡ndose sin cuestionar
    # aunque ya existÃ­a bandera_discrepante calculada (nunca se actuaba
    # sobre ella). Se prefiere audio tambiÃ©n en estos beats, no solo
    # cuando track es NaN -- y al ser una decisiÃ³n por beat individual
    # (no por bloque), retoma track automÃ¡ticamente apenas vuelve a dar
    # valores plausibles, sin necesidad de lÃ³gica de "bloque" aparte.
    UMBRAL_TRACK_IMPLAUSIBLE_MS = 500.0
    mask_track_implausible = (~np.isnan(asinc_por_stim_track)
                               & (np.abs(asinc_por_stim_track) > UMBRAL_TRACK_IMPLAUSIBLE_MS))

    # --- AdemÃ¡s del umbral absoluto de arriba (fijo, pensado para
    # cualquier BPM), una asincronÃ­a que supera la MITAD DEL ISI LOCAL
    # probablemente no es una asincronÃ­a real -- es una respuesta que en
    # realidad le pertenece a OTRO estÃ­mulo (el anterior o el siguiente),
    # asignada mal por el matching ordinal (ver discusiÃ³n extensa en esta
    # conversaciÃ³n: un ciclo espurio o faltante corre el conteo, y el
    # sÃ­ntoma es una asincronÃ­a consistentemente cercana a Â±ISI en el
    # tramo afectado). Confirmado con evidencia directa (sesiÃ³n PA real):
    # ~18 beats seguidos en BPM1 (120bpm, ISI=500ms) con asincronÃ­a de
    # track entre +409 y +452ms -- por debajo del umbral absoluto de
    # 500ms (nunca se marcaban implausibles) pero muy por encima de lo que
    # una asincronÃ­a real puede ser sin ambigÃ¼edad de a quÃ© estÃ­mulo
    # pertenece.
    #
    # El lÃ­mite es proporcional al ISI de CADA estÃ­mulo (no un ms fijo),
    # usando el mismo criterio de ambigÃ¼edad Â±ISI/2 que ya usa
    # compute_asyn (asyn_max) -- asÃ­ corrige automÃ¡ticamente para
    # cualquier BPM del protocolo (80/108/120/132/160, o lo que sea),
    # incluidos tramos con tempo distinto dentro de la misma sesiÃ³n
    # (PA/PR). El ISI local de cada estÃ­mulo se toma como la distancia al
    # vecino mÃ¡s cercano (anterior o siguiente) -- no un ISI global fijo
    # de toda la sesiÃ³n -- para que sea vÃ¡lido tambiÃ©n en los bordes de un
    # cambio de tempo.
    n_stim_local = len(stim_times)
    mask_track_fuera_isi = np.zeros(n_stim_local, dtype=bool)
    isi_local_s = np.full(n_stim_local, np.nan)   # default -- se completa abajo si hay >=2 estÃ­mulos
    if n_stim_local >= 2:
        diffs_stim = np.diff(stim_times)
        isi_local_s[0] = diffs_stim[0]
        isi_local_s[-1] = diffs_stim[-1]
        if n_stim_local > 2:
            isi_local_s[1:-1] = np.minimum(diffs_stim[:-1], diffs_stim[1:])
        umbral_isi_medio_ms = 1000.0 * isi_local_s / 2.0
        mask_track_fuera_isi = (~np.isnan(asinc_por_stim_track)
                                 & (np.abs(asinc_por_stim_track) > umbral_isi_medio_ms))
    n_fuera_isi = int((mask_track_fuera_isi & ~mask_track_implausible).sum())
    if n_fuera_isi > 0:
        print(f"  [FusiÃ³n] {n_fuera_isi} beat(s) de track con |asincronÃ­a| > ISI_local/2 -- "
              f"probable respuesta asignada al estÃ­mulo equivocado (no una asincronÃ­a real de "
              f"esa magnitud) -- tratados como sospechosos, se prefiere audio si estÃ¡ disponible.")

    # --- Track tambiÃ©n puede fallar de forma AISLADA, con un salto que NO
    # llega al umbral absoluto de arriba pero tampoco es real -- un beat
    # puntual donde el tracking se distrajo momentÃ¡neamente. Se combinan
    # DOS condiciones para identificarlo con confianza (una sola no
    # alcanza): que track se aparte de su PROPIA tendencia local (outlier
    # dentro de su propia secuencia, no solo distinto de audio) Y que
    # ademÃ¡s discrepe del audio mÃ¡s allÃ¡ del desfasaje sistemÃ¡tico normal
    # entre ambas fuentes (bandera_discrepante, ya calculada arriba,
    # corrige ese sesgo local antes de comparar). Exigir ambas evita
    # confundir esto con la variabilidad normal punto a punto de track,
    # que por sÃ­ sola no alcanza para desconfiar de Ã©l.
    ventana_outlier_track = 5
    umbral_outlier_track_ms = 80.0
    mask_track_outlier_local = np.zeros(len(stim_times), dtype=bool)
    for i in np.where(~np.isnan(asinc_por_stim_track) & ~mask_track_implausible)[0]:
        lo, hi = max(0, i - ventana_outlier_track), min(len(stim_times), i + ventana_outlier_track + 1)
        idx_vecinos = np.array([k for k in range(lo, hi) if k != i])
        vecinos = asinc_por_stim_track[idx_vecinos]
        vecinos = vecinos[~np.isnan(vecinos) & ~mask_track_implausible[idx_vecinos]]
        if len(vecinos) < 3:
            continue
        if abs(asinc_por_stim_track[i] - np.median(vecinos)) > umbral_outlier_track_ms:
            mask_track_outlier_local[i] = True
    mask_track_sospechoso = (mask_track_implausible | mask_track_fuera_isi
                              | (mask_track_outlier_local & bandera_discrepante))

    asinc_por_stim = asinc_por_stim_track.copy()
    idx_beat = np.arange(len(stim_times))
    puede_sustituir = idx_beat >= beats_antes_reaccion
    mask_fallback_audio = ((np.isnan(asinc_por_stim_track) | mask_track_sospechoso)
                           & ~np.isnan(asinc_por_stim_audio)
                           & puede_sustituir & ~mask_meseta_por_estimulo)
    n_meseta_bloqueado = int(np.sum(np.isnan(asinc_por_stim_track) & mask_meseta_por_estimulo
                                     & ~np.isnan(asinc_por_stim_audio) & puede_sustituir))
    if n_meseta_bloqueado > 0:
        print(f"  [FusiÃ³n] {n_meseta_bloqueado} candidato(s) de audio NO usado(s) -- el track ya "
              f"habÃ­a descartado esos beats a propÃ³sito (meseta superficial, sin apoyo real).")
    n_track_implausible = int((mask_track_implausible & mask_fallback_audio).sum())
    if n_track_implausible > 0:
        print(f"  [FusiÃ³n] {n_track_implausible} beat(s) donde track tenÃ­a un valor implausible "
              f"(>{UMBRAL_TRACK_IMPLAUSIBLE_MS:.0f}ms, probable falla de tracking) -- se usa audio "
              f"en su lugar, si pasa la validaciÃ³n.")
    n_track_outlier_aislado = int((mask_track_outlier_local & bandera_discrepante & mask_fallback_audio
                                    & ~mask_track_implausible).sum())
    if n_track_outlier_aislado > 0:
        print(f"  [FusiÃ³n] {n_track_outlier_aislado} beat(s) donde track se apartaba de su propia "
              f"tendencia local Y discrepaba del audio (falla aislada de tracking, no extrema) -- "
              f"se usa audio en su lugar, si pasa la validaciÃ³n.")

    # --- Validar cada candidato de audio antes de sustituir. -----------------
    # Si el motivo es "track=NaN": validar contra el contexto LOCAL de
    # TRACK (un candidato de audio aislado, sin ningÃºn track que lo
    # confirme, puede estar enganchado a un remanente de bleed/movimiento
    # previo -- ver historial).
    # Si el motivo es "track implausible": NO conviene validar contra
    # track vecino (puede ser parte del mismo tramo fallido) -- se valida
    # contra AUDIO vecino (autoconsistencia): si el audio de esa zona es
    # internamente estable, es mÃ¡s confiable que comparar contra un track
    # que ya sabemos que estÃ¡ fallando ahÃ­ mismo.
    ventana_validacion_audio = 5
    # LÃ­mites de secciÃ³n por beat (mismo criterio por clics que seccion_por_beat
    # mÃ¡s abajo, pero calculado ACÃ porque hace falta antes) -- para que la
    # ventana de vecinos nunca cruce un cambio de tempo. Confirmado con
    # evidencia directa (dos sesiones PA distintas): un candidato de audio
    # justo en el primer beat de una secciÃ³n nueva se rechazaba porque la
    # ventana de Â±5 mezclaba vecinos de la secciÃ³n VIEJA (otro tempo, otra
    # lÃ­nea base de asincronÃ­a) -- la comparaciÃ³n en sÃ­ no tenÃ­a sentido,
    # no es que el candidato fuera malo.
    tipo_metro_val = metadata.get('tipo_metronomo', 'ISO')
    limite_ini_seccion = np.zeros(len(stim_times), dtype=int)
    limite_fin_seccion = np.full(len(stim_times), len(stim_times), dtype=int)
    if tipo_metro_val == 'PA':
        c1 = metadata['clics_1']
        limite_ini_seccion[c1:] = c1
        limite_fin_seccion[:c1] = c1
    elif tipo_metro_val == 'PR':
        c1, cr = metadata['clics_1'], metadata['clics_rampa']
        limite_fin_seccion[:c1] = c1
        limite_ini_seccion[c1:c1 + cr] = c1
        limite_fin_seccion[c1:c1 + cr] = c1 + cr
        limite_ini_seccion[c1 + cr:] = c1 + cr
    # Umbral proporcional al ISI local (piso 80ms, nunca mÃ¡s estricto que
    # antes) -- mismo motivo que el criterio de Â±ISI/2 para track: un
    # valor fijo de 80ms es demasiado estricto en tempos lentos o en
    # zonas de transiciÃ³n de BPM, donde la variabilidad LOCAL esperable
    # (incluso entre puntos genuinamente buenos) es mayor. Confirmado con
    # evidencia directa: 4 de 5 candidatos de audio rechazados en una
    # sesiÃ³n PA (98.8, 131.4, -54.6, -89.2ms) caÃ­an justo en la
    # transiciÃ³n BPM1->BPM2, con diferencias de 100-200ms contra la
    # mediana local -- razonables para esa zona, pero por encima del
    # umbral fijo. FRAC_UMBRAL_DESVIO_AUDIO=0.3 da 225ms a 80bpm (ISI
    # 750ms), 150ms a 120bpm -- suficiente margen sin dejar de filtrar
    # candidatos genuinamente descolgados (el quinto caso rechazado,
    # +500ms de salto puntual, sigue superando incluso este umbral mÃ¡s
    # generoso).
    FRAC_UMBRAL_DESVIO_AUDIO = 0.3
    idx_candidatos_audio = np.where(mask_fallback_audio)[0]
    mask_audio_rechazado = np.zeros(len(stim_times), dtype=bool)
    for i in idx_candidatos_audio:
        lo = max(0, i - ventana_validacion_audio, limite_ini_seccion[i])
        hi = min(len(stim_times), i + ventana_validacion_audio + 1, limite_fin_seccion[i])
        isi_local_ms_i = isi_local_s[i] * 1000.0 if i < len(isi_local_s) and not np.isnan(isi_local_s[i]) else 500.0
        umbral_desvio_audio_ms = max(80.0, FRAC_UMBRAL_DESVIO_AUDIO * isi_local_ms_i)
        if mask_track_sospechoso[i]:
            idx_vecinos = np.array([k for k in range(lo, hi) if k != i])
            vecinos_audio = asinc_por_stim_audio[idx_vecinos]
            vecinos_audio = vecinos_audio[~np.isnan(vecinos_audio)]
            if len(vecinos_audio) < 2:
                continue   # sin contexto suficiente para validar -- se deja sustituir como antes
            mediana_local = np.median(vecinos_audio)
        else:
            vecinos_track = asinc_por_stim_track[lo:hi]
            mask_vecinos_validos = ~np.isnan(vecinos_track) & ~mask_track_sospechoso[lo:hi]
            vecinos_track = vecinos_track[mask_vecinos_validos]
            if len(vecinos_track) < 2:
                continue   # sin contexto suficiente para validar -- se deja sustituir como antes
            mediana_local = np.median(vecinos_track)
        if abs(asinc_por_stim_audio[i] - mediana_local) > umbral_desvio_audio_ms:
            mask_audio_rechazado[i] = True

    n_audio_rechazado = int(mask_audio_rechazado.sum())
    mask_fallback_audio = mask_fallback_audio & ~mask_audio_rechazado

    # --- Track SOSPECHOSO cuyo candidato de audio se rechazÃ³: dejar SIN
    # DATO, no volver en silencio al valor de track ya descartado --------
    # mask_track_sospechoso (implausible, fuera de Â±ISI/2, u outlier local
    # discrepante) ya identificÃ³ estos valores como no confiables -- ese
    # fue justamente el motivo por el que se buscÃ³ reemplazarlos con
    # audio. Si el candidato de audio se rechaza por el chequeo de
    # contexto (mask_audio_rechazado), el cÃ³digo simplemente mantenÃ­a el
    # valor de track original al no estar incluido en mask_fallback_audio
    # -- reapareciendo como si fuera confiable, aunque ya se habÃ­a
    # decidido lo contrario. Confirmado con evidencia directa: beats con
    # asincronÃ­a de track de -628 a -799ms (varias veces el ISI/2 de la
    # secciÃ³n) terminaban en fuente_respuesta='track' con ese mismo valor
    # extremo, porque el candidato de audio razonable (ej. -55 a 131ms)
    # habÃ­a sido rechazado por diferir de una ventana de vecinos con
    # mucha variabilidad propia (justo la transiciÃ³n BPM1->BPM2).
    mask_track_descartado_sin_reemplazo = (mask_track_sospechoso & puede_sustituir
                                            & ~mask_meseta_por_estimulo & ~mask_fallback_audio)
    n_track_descartado_sin_reemplazo = int(mask_track_descartado_sin_reemplazo.sum())
    if n_track_descartado_sin_reemplazo > 0:
        print(f"  [FusiÃ³n] {n_track_descartado_sin_reemplazo} beat(s) de track sospechoso sin "
              f"reemplazo vÃ¡lido de audio (rechazado por contexto, o sin audio disponible) -- "
              f"quedan sin dato en vez de mantener el valor de track ya descartado.")

    fuente_por_beat = np.where(mask_fallback_audio, 'audio',
                       np.where(mask_track_descartado_sin_reemplazo, 'ninguno',
                       np.where(~np.isnan(asinc_por_stim_track), 'track', 'ninguno')))
    asinc_por_stim[mask_fallback_audio] = asinc_por_stim_audio[mask_fallback_audio]
    asinc_por_stim[mask_track_descartado_sin_reemplazo] = np.nan

    n_track          = int(np.sum(fuente_por_beat == 'track'))
    n_audio_fallback  = int(mask_fallback_audio.sum())
    n_sin_dato        = int(np.sum(fuente_por_beat == 'ninguno'))
    n_discrepantes    = int(bandera_discrepante.sum())

    if n_audio_rechazado > 0:
        print(f"  [FusiÃ³n] {n_audio_rechazado} candidato(s) de audio rechazado(s) por no coincidir "
              f"con el contexto local de track (> {umbral_desvio_audio_ms}ms de diferencia) -- "
              f"quedan sin dato en vez de sustituir.")

    print(f"\n--- FusiÃ³n track + audio (respuesta por beat) ---")
    print(f"  Beats con track: {n_track} | Beats con respaldo de audio: {n_audio_fallback} | "
          f"Sin dato en ninguna fuente: {n_sin_dato}")
    if sesgo_video_audio_ms is not None:
        print(f"  Sesgo global track-audio (referencia, no usado para la bandera): "
              f"{sesgo_video_audio_ms:+.2f} ms (n={int(mask_ambos.sum())} beats)")
        print(f"  Beats discrepantes (residual sobre sesgo LOCAL, ventana Â±{VENTANA_SESGO_BEATS} beats, "
              f"> Â±{UMBRAL_DISCREPANCIA_MS:.0f} ms): {n_discrepantes}")
    else:
        print("  No hay suficientes beats con ambas fuentes para estimar el sesgo.")

    # ==========================================================================
    # 20. TIEMPO DE RESTABLECIMIENTO (Tr) Y COMPARACIÃ“N BPM1 vs BPM2
    # ==========================================================================
    tipo_metro = metadata['tipo_metronomo']

    if tipo_metro in ('PA', 'PR'):
        idx_fin_bpm1  = metadata['clics_1']
        idx_ini_bpm2  = metadata['clics_1'] if tipo_metro == 'PA' \
                        else metadata['clics_1'] + metadata['clics_rampa']

        seccion_bpm1 = asinc_por_stim[:idx_fin_bpm1]
        stim_bpm1    = stim_times[:idx_fin_bpm1]
        seccion_bpm2 = asinc_por_stim[idx_ini_bpm2:]
        stim_bpm2    = stim_times[idx_ini_bpm2:]

        resultado_Tr_bpm1 = _calcular_tr_por_seccion(seccion_bpm1, stim_bpm1)
        resultado_Tr_bpm2 = _calcular_tr_por_seccion(seccion_bpm2, stim_bpm2)
        resultado_Tr_bpm1['idx_offset_global'] = 0
        resultado_Tr_bpm2['idx_offset_global'] = idx_ini_bpm2

        bpm_valor_1, bpm_valor_2 = metadata['bpm_1'], metadata['bpm_2']
        label_1, label_2 = f"{bpm_valor_1} bpm", f"{bpm_valor_2} bpm"
        for label, res in [(label_1, resultado_Tr_bpm1), (label_2, resultado_Tr_bpm2)]:
            print(f"\nâ”€â”€ {label} â”€â”€")
            print(f"  Baseline (n vÃ¡lido)  : {res['n_baseline_valido']} beats")
            print(f"  Î¼ baseline           : {res['mu_baseline_ms']} ms")
            print(f"  Ïƒ baseline           : {res['sigma_baseline_ms']} ms")
            print(f"  Banda aceptaciÃ³n     : [{res['lim_inf_ms']}, {res['lim_sup_ms']}] ms")
            print(f"  Tr (beats)           : {res['Tr_beats']}")
            print(f"  Tr (ms)              : {res['Tr_ms']}")

        tr_beats_reportado = resultado_Tr_bpm2['Tr_beats']
        if resultado_Tr_bpm1['mu_baseline_ms'] is not None and resultado_Tr_bpm2['mu_baseline_ms'] is not None:
            diferencia_bpm2_bpm1 = resultado_Tr_bpm2['mu_baseline_ms'] - resultado_Tr_bpm1['mu_baseline_ms']
            print(f"\n  Diferencia (BPM2 - BPM1): {diferencia_bpm2_bpm1:+.2f} ms")
        else:
            diferencia_bpm2_bpm1 = None

        # Compatibilidad con el resto del pipeline (JSON, CSV, cache de grÃ¡ficos)
        resultado_secciones = {
            'diferencia':  diferencia_bpm2_bpm1,
            'media_bpm1':  resultado_Tr_bpm1['mu_baseline_ms'],
            'media_bpm2':  resultado_Tr_bpm2['mu_baseline_ms'],
        }

        # [AD-3] Pendiente de adaptaciÃ³n durante la rampa (solo PR)
        resultado_slope_rampa = None
        if tipo_metro == 'PR' and idx_ini_bpm2 < len(stim_times):
            t_rampa_ini_s = stim_times[idx_fin_bpm1]
            t_rampa_fin_s = stim_times[idx_ini_bpm2]
            resultado_slope_rampa = calcular_pendiente_adaptacion(
                asinc_por_stim, stim_times, t_rampa_ini_s, t_rampa_fin_s)
            print(f"\nâ”€â”€ Pendiente de adaptaciÃ³n (rampa) â”€â”€")
            print(f"  slope   : {resultado_slope_rampa['slope_ms_per_s']} ms/s")
            print(f"  rÂ²      : {resultado_slope_rampa['r_squared']}")
            print(f"  n beats : {resultado_slope_rampa['n']}")
            print(f"  media asincronÃ­a en rampa: {resultado_slope_rampa['mean_asinc_rampa_ms']} ms")

        secciones_clasif = [
            {'nombre': 'bpm1', 'bpm': bpm_valor_1, 'label': label_1, 'res': resultado_Tr_bpm1},
            {'nombre': 'bpm2', 'bpm': bpm_valor_2, 'label': label_2, 'res': resultado_Tr_bpm2},
        ]
    else:
        resultado_slope_rampa = None
        resultado_Tr_bpm1   = _calcular_tr_por_seccion(asinc_por_stim, stim_times)
        resultado_Tr_bpm1['idx_offset_global'] = 0
        resultado_Tr_bpm2   = None
        resultado_secciones = None
        tr_beats_reportado  = resultado_Tr_bpm1['Tr_beats']
        diferencia_bpm2_bpm1 = None

        secciones_clasif = [
            {'nombre': 'bpm1', 'bpm': metadata['bpm'], 'label': f"{metadata['bpm']} bpm",
             'res': resultado_Tr_bpm1},
        ]

    # â”€â”€ Î¼, Ïƒ, CV y clasificaciÃ³n INDIVIDUAL por cada BPM (no global) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    print(f"\n--- Nivel funcional por BPM ---")
    for sec in secciones_clasif:
        res = sec['res']
        mu_bpm    = res.get('mu_baseline_ms', np.nan)
        sigma_bpm = res.get('sigma_baseline_ms', np.nan)
        cv_bpm    = (sigma_bpm / abs(mu_bpm) * 100.0) \
                    if (mu_bpm not in (None, 0) and not np.isnan(mu_bpm)) else np.nan
        tr_bpm    = res.get('Tr_beats')
        deriva_bpm   = res.get('deriva_ms_s')
        deriva_r_bpm = res.get('deriva_r')

        sec['mu_ms']           = mu_bpm
        sec['sigma_ms']        = sigma_bpm
        sec['cv_pct']          = cv_bpm
        sec['tr_beats']        = tr_bpm
        sec['deriva_ms_s']     = deriva_bpm
        sec['deriva_r']        = deriva_r_bpm

        print(f"  {sec['label']}: |mu|={abs(mu_bpm):.2f} ms | sigma={sigma_bpm:.2f} ms | "
              f"CV={cv_bpm:.2f}% | Tr={tr_bpm} beats | "
              f"deriva={deriva_bpm} ms/s (r={deriva_r_bpm})")

    if diferencia_bpm2_bpm1 is not None:
        print(f"\n  Diferencia (BPM2 - BPM1): {diferencia_bpm2_bpm1:+.2f} ms")

    # ==========================================================================
    # 21. ARMADO DE RESULTADO Y EXPORTACIÃ“N A CSV (con auto-descarga en Colab)
    # ==========================================================================
    resultado = {
        'filename':                filename_stem,
        'metadata':                metadata,
        'stats_asincronia_video':  stats_asinc_video,
        'stats_iti_video':         stats_iti_video,
        'metricas_video':          metricas_video,
        'tramos_audio':            resultados_tramos_audio,
        'n_resp_video':            int(len(resp_times_s)),
        'n_pareados_video':        int(len(asinc_video_ms)),
        'resultado_Tr_bpm1':       resultado_Tr_bpm1,
        'resultado_Tr_bpm2':       resultado_Tr_bpm2,
        'resultado_secciones':     resultado_secciones,
        'resultado_slope_rampa':   resultado_slope_rampa,
        'fusion_track_audio': {
            'n_track':                 n_track,
            'n_audio_fallback':        n_audio_fallback,
            'n_sin_dato':              n_sin_dato,
            'n_discrepantes':          n_discrepantes,
            'sesgo_video_audio_ms':    round(sesgo_video_audio_ms, 3) if sesgo_video_audio_ms is not None else None,
            'umbral_discrepancia_ms':  UMBRAL_DISCREPANCIA_MS,
        },
        'stats_por_bpm':           [{k: v for k, v in sec.items() if k != 'res'} for sec in secciones_clasif],
    }

    # ==========================================================================
    # ==========================================================================
    offsets_audio_ms_csv = _detectar_offset_audio_bleed(stim_times_wav, audio_relevant, sample_rate)
    stim_times_audio_csv = stim_times_wav + offsets_audio_ms_csv / 1000.0   # NaN donde no hay detecciÃ³n confiable

    # --- Columna diagnÃ³stica: % de frames sin detecciÃ³n real de MediaPipe
    # en la ventana esperada de cada beat -- puramente informativa, NO
    # afecta ninguna decisiÃ³n del pipeline. Permite diferenciar, cuando no
    # hay respuesta en track, entre "MediaPipe no detectÃ³ nada ahÃ­" (sin
    # dato) y "MediaPipe sÃ­ detectÃ³, pero no hubo un tap real" (meseta
    # superficial genuina, u otro motivo). Se reporta como porcentaje (no
    # un booleano con un umbral fijo elegido a priori) para que quede
    # disponible toda la informaciÃ³n al revisar el CSV, sin forzar un
    # corte arbitrario.
    #
    # Usa la ventana del TAP mÃ¡s cercano a cada estÃ­mulo (no la ventana
    # genÃ©rica entre dos estÃ­mulos consecutivos) cuando existe uno dentro
    # de una proximidad razonable -- confirmado con evidencia directa: la
    # ventana genÃ©rica (todo el intervalo entre estÃ­mulos) agarra de
    # rebote los problemas de detecciÃ³n de taps VECINOS, aunque el tap
    # que realmente corresponde a ese estÃ­mulo estÃ© perfectamente
    # trackeado -- dando un % inflado que sugiere falta de dato donde en
    # realidad es una meseta superficial genuina. Si no hay ningÃºn tap
    # cerca (hueco real), se usa la ventana genÃ©rica como respaldo.
    pct_frames_sin_mediapipe = np.full(len(stim_times), np.nan)
    if 'sin_tracking' in df.columns:
        tasa_diag = calibracion_reloj['slope_ms_s'] / 1000.0 if calibracion_reloj['aplicable'] else 0.0
        t_frames_diag = ((df['frame_ts_real_ms'].to_numpy() / 1000.0) - start_time) / (1 + tasa_diag)
        sin_tracking_arr_diag = df['sin_tracking'].to_numpy()

        isi_tipico = float(np.median(np.diff(stim_times))) if len(stim_times) > 1 else 1.0
        t_picos_bajos = t_frames_diag[tip_peaks_b] if len(tip_peaks_b) > 0 else np.array([])

        for i in range(len(stim_times)):
            ventana_usada = None
            if len(t_picos_bajos) > 0:
                j_cercano = int(np.argmin(np.abs(t_picos_bajos - stim_times[i])))
                if abs(t_picos_bajos[j_cercano] - stim_times[i]) <= 0.6 * isi_tipico:
                    pa, pb = int(tip_peaks_a[j_cercano]), int(tip_peaks_b[j_cercano])
                    if pa < pb <= len(sin_tracking_arr_diag):
                        ventana_usada = sin_tracking_arr_diag[pa:pb + 1]
            if ventana_usada is None:
                # Sin ningÃºn tap cerca -- respaldo: ventana genÃ©rica entre
                # este estÃ­mulo y el siguiente (hueco real, no hay un tap
                # propio del cual tomar la ventana exacta).
                t_ini = stim_times[i]
                if i + 1 < len(stim_times):
                    t_fin = stim_times[i + 1]
                else:
                    isi_prev = stim_times[i] - stim_times[i - 1] if i > 0 else 1.0
                    t_fin = stim_times[i] + isi_prev
                mask_ventana = (t_frames_diag >= t_ini) & (t_frames_diag < t_fin)
                if mask_ventana.sum() > 0:
                    ventana_usada = sin_tracking_arr_diag[mask_ventana]
            if ventana_usada is not None and len(ventana_usada) > 0:
                pct_frames_sin_mediapipe[i] = 100.0 * ventana_usada.mean()

    # --- SecciÃ³n del protocolo a la que pertenece cada beat -----------------
    # Se calcula por CANTIDAD DE CLICS (metadata), no por tiempo -- stim_times
    # ya pasÃ³ por la sincronizaciÃ³n (11.5 mÃ¡s arriba) y sus valores absolutos
    # ya no coinciden necesariamente con los cortes "de diseÃ±o" del
    # protocolo, asÃ­ que un corte por tiempo serÃ­a frÃ¡gil. Por clics es
    # exacto siempre: el beat_idx N-Ã©simo es, por construcciÃ³n, el N-Ã©simo
    # click emitido por el metrÃ³nomo, en el orden en que se armÃ³ stim_times
    # (ver _construir_stim_times) -- ISO / PA(1,2) / PR(1,rampa,2).
    #
    # Se incluye el BPM en la etiqueta (ej. 'iso_120', 'bpm1_120', 'bpm2_80')
    # -- asÃ­ queda visible sin tener que cruzar con metadata aparte. La
    # rampa no tiene un BPM Ãºnico (varÃ­a de forma continua de bpm_1 a
    # bpm_2), asÃ­ que en su lugar se etiqueta con el porcentaje de cambio
    # del protocolo (ej. 'rampa_+33%', 'rampa_-10%'), tomado directo de
    # metadata['porcentaje_cambio'] -- ya viene con el signo correcto desde
    # _extraer_metadata (soporta '+', '-' o '_' en el nombre de archivo).
    tipo_metro_seccion = metadata.get('tipo_metronomo', 'ISO')
    seccion_por_beat = np.full(len(stim_times), 'iso', dtype=object)
    if tipo_metro_seccion == 'ISO':
        seccion_por_beat[:] = f"iso_{metadata['bpm']}"
    elif tipo_metro_seccion == 'PA':
        c1 = metadata['clics_1']
        seccion_por_beat[:c1] = f"bpm1_{metadata['bpm_1']}"
        seccion_por_beat[c1:] = f"bpm2_{metadata['bpm_2']}"
    elif tipo_metro_seccion == 'PR':
        c1, cr = metadata['clics_1'], metadata['clics_rampa']
        pct = metadata['porcentaje_cambio']
        seccion_por_beat[:c1] = f"bpm1_{metadata['bpm_1']}"
        seccion_por_beat[c1:c1 + cr] = f"rampa_{pct:+d}%"
        seccion_por_beat[c1 + cr:] = f"bpm2_{metadata['bpm_2']}"


    guardar_sesion(resultado, f"{filename_stem}_datos_sesion.json")

    # ==========================================================================
    # Cache de series crudas para el mÃ³dulo de grÃ¡ficos (celda aparte)
    # ==========================================================================
    ULTIMO_ANALISIS_RAW.clear()
    ULTIMO_ANALISIS_RAW.update({
        'filename_stem':        filename_stem,
        'video_path':           video_path,
        'beats_antes_reaccion':  beats_antes_reaccion,
        'calibracion_reloj_camara': calibracion_reloj,
        'salto_segmentado_track': salto_segmentado_track,
        'salto_segmentado_audio': salto_segmentado_audio,
        'metronome_path':       metronome_path,
        'start_time':           start_time,
        'end_time':             end_time,
        'metadata':             metadata,
        'fps':                  fps,
        'frame':                df['frame'].values,
        'frame_ts_real_ms':     df['frame_ts_real_ms'].values if 'frame_ts_real_ms' in df.columns else None,
        'tip_y':                df['tip_y'].values,
        'sin_tracking':          df['sin_tracking'].values if 'sin_tracking' in df.columns else None,
        'tip_y_cm':              df['tip_y_cm'].values,
        # Landmarks individuales de cada dedo (SIN combinar), para
        # diagnÃ³stico -- ver si el centroide ponderado diluye un
        # movimiento real que sÃ­ aparece en un dedo individual.
        'tip_y_por_dedo': {
            dedo: df[f'{dedo}_y'].values for dedo in
            ['indice_tip', 'medio_tip', 'anular_tip', 'meÃ±ique_tip']
            if f'{dedo}_y' in df.columns
        },
        # Landmarks en PÃXELES CRUDOS (antes de cualquier conversiÃ³n a cm
        # o normalizaciÃ³n de escala) -- para diagnÃ³stico, separar si un
        # problema estÃ¡ en el tracking en sÃ­ o en la conversiÃ³n posterior.
        'tip_y_por_dedo_px': {
            dedo: df[f'{dedo}_y_px'].values for dedo in
            ['indice_tip', 'medio_tip', 'anular_tip', 'meÃ±ique_tip']
            if f'{dedo}_y_px' in df.columns
        },
        'ideal_y':              df['ideal_y'].values if 'ideal_y' in df.columns else None,
        'tip_peaks_a':          tip_peaks_a,
        # _pareo: mismos ciclos PERO con NaN insertado donde el pipeline
        # detectÃ³ un pico alto faltante (ver comentario en run_analysis,
        # secciÃ³n "Picos altos FALTANTES") -- son los que indexan
        # resp_times_s/mask_meseta_superficial mÃ¡s abajo, y pueden estar
        # DESALINEADOS en Ã­ndice respecto a tip_peaks_a/tip_peaks_b (los
        # planos, sin huecos) si hubo algÃºn ciclo faltante antes de cierto
        # punto de la sesiÃ³n. Se guardan aparte para diagnÃ³stico -- nunca
        # asumir que la posiciÃ³n j es la misma en ambos pares de arrays.
        'tip_peaks_a_pareo':    tip_peaks_a_pareo,
        'tip_peaks_b_pareo':    tip_peaks_b_pareo,
        'tip_peaks_b':          tip_peaks_b,
        'umbral_cruce':         umbral_cruce,
        'mask_meseta_superficial': mask_meseta_superficial,
        'cruces_video':         cruces_video,
        'stim_times':           stim_times,
        'stim_times_wav':       stim_times_wav,
        'resp_times_s':         resp_times_s,
        'asinc_por_stim':       asinc_por_stim,
        'asinc_video_ms':       asinc_video_ms,
        'iti_video_ms':         iti_video_ms,
        'iti_video_desv':       iti_video_desv,
        'amplitudes_por_tramo': amplitudes_por_tramo,
        'tiempos_por_tramo':    tiempos_por_tramo,
        'tiempo_apoyo_ms':      tiempo_apoyo_ms,
        'tiempo_alzada_ms':     tiempo_alzada_ms,
        'mask_apoyo':           mask_apoyo,
        'mask_alzada':          mask_alzada,
        'resultado_Tr_bpm1':    resultado_Tr_bpm1,
        'resultado_Tr_bpm2':    resultado_Tr_bpm2,
        'resultado_secciones':  resultado_secciones,
        'resultado_slope_rampa': resultado_slope_rampa,
        'asinc_por_stim_track':  asinc_por_stim_track,
        'asinc_por_stim_audio':  asinc_por_stim_audio,
        'asinc_por_stim_fusion': asinc_por_stim,
        'fuente_por_beat':       fuente_por_beat,
        'mask_meseta_por_estimulo': mask_meseta_por_estimulo,
        'mask_track_implausible':   mask_track_implausible,
        'mask_track_fuera_isi':     mask_track_fuera_isi,
        'mask_track_outlier_local': mask_track_outlier_local,
        'mask_track_sospechoso':    mask_track_sospechoso,
        'mask_audio_rechazado':     mask_audio_rechazado,
        'bandera_discrepante':   bandera_discrepante,
        'sesgo_video_audio_ms':  sesgo_video_audio_ms,
        'sesgo_local_ms':        sesgo_local_ms,
        'tramos_audio':         resultados_tramos_audio,
        'picos_estimulo_audio':  picos_estimulo_audio,
        'picos_respuesta_audio': picos_respuesta_audio,
        'stats_asincronia_video': stats_asinc_video,
        'stats_por_bpm':        secciones_clasif,
    })

    return resultado



# ==============================================================================
# FUNCIONES AUXILIARES DEL PIPELINE
# ==============================================================================

def _obtener_offset_audio_stream(video_path):
    """
    Devuelve el start_time declarado del stream de AUDIO del contenedor
    (en segundos) -- el "encoder delay"/priming tÃ­pico de AAC, que hace
    que la primera muestra de audio decodificada corresponda a un tiempo
    real posterior al frame 0 de video (el stream de video declara
    start_time=0, el de audio no siempre).

    Sin compensar esto, todo lo calculado a partir del audio (start_time
    de la sesiÃ³n, stim_times, detecciÃ³n de estÃ­mulo/respuesta) queda
    corrido respecto al video en esa misma magnitud -- confirmado
    empÃ­ricamente: offset de stream 0.1636s, diferencia medida entre
    duraciÃ³n de contenedor y duraciÃ³n de audio extraÃ­do 0.1630s,
    coinciden a menos de 1ms.

    Si ffprobe falla o no hay info del stream de audio, devuelve 0 (sin
    compensaciÃ³n, comportamiento igual al de antes).
    """
    try:
        resultado = subprocess.run(
            [FFPROBE_CMD, '-v', 'quiet', '-print_format', 'json', '-show_streams', video_path],
            capture_output=True, text=True, timeout=15
        )
        info = json.loads(resultado.stdout)
        for stream in info.get('streams', []):
            if stream.get('codec_type') == 'audio':
                return max(0.0, float(stream.get('start_time', 0.0)))
    except Exception as e:
        print(f"  (No se pudo leer el offset del stream de audio con ffprobe: {e})")
    return 0.0


def _cargar_audio_de_video(video_path):
    """
    Extrae el audio embebido en el video. Si librosa no puede leerlo
    directamente (contenedor/codec no reconocido por soundfile/audioread),
    usa ffmpeg para volcarlo a un .wav temporal y lo carga desde ahÃ­.

    Compensa el offset de inicio del stream de audio del contenedor
    (encoder delay/priming, tÃ­pico de AAC) agregando silencio al
    principio, para que el Ã­ndice 0 del audio quede alineado con el
    tiempo real 0 del video (que declara start_time=0).
    """
    try:
        audio_data, sample_rate = librosa.load(video_path, sr=None, mono=True)
    except Exception as e:
        print(f"  librosa no pudo leer el audio del video directamente ({type(e).__name__}); "
              f"extrayendo con ffmpeg...")
        tmp_wav = os.path.join(OUTPUT_DIR, '_tmp_audio_de_video.wav')
        cmd = [FFMPEG_CMD, '-y', '-i', video_path, '-vn', '-acodec', 'pcm_s16le', tmp_wav]
        resultado = subprocess.run(cmd, capture_output=True, text=True)
        if resultado.returncode != 0:
            raise AudioExtractionError() from e
        audio_data, sample_rate = librosa.load(tmp_wav, sr=None, mono=True)

    offset_s = _obtener_offset_audio_stream(video_path)
    if offset_s > 0.001:   # ignorar offsets despreciables (<1ms), probablemente ruido de metadata
        n_padding = int(round(offset_s * sample_rate))
        audio_data = np.concatenate([np.zeros(n_padding, dtype=audio_data.dtype), audio_data])
        print(f"  [Audio] Offset de stream compensado (encoder delay): {offset_s*1000:.1f}ms "
              f"({n_padding} muestras de silencio agregadas al inicio)")

    return audio_data, sample_rate


def _extraer_metadata(filename):
    """
    Extrae metadatos del nombre del archivo.
    Acepta '+', '-' o '_' como signo del porcentaje en PA/PR.
    Tolera guion medio '-' o guion bajo '_' antes del nÃºmero de mediciÃ³n.
    """
    # --- ISO ---
    # Cambio: _([A-Za-z]+\d+) -> [_-]([A-Za-z]+\d+)
    m = re.search(r'(S\d+)_([A-Z]+)_ISO(\d+)[_-]([A-Za-z]+\d+)', filename)
    if m:
        return {'sujeto': re.sub(r'\D', '', m.group(1)),
                'mano': m.group(2), 'tipo_metronomo': 'ISO',
                'bpm': int(m.group(3)),
                'medicion': re.sub(r'\D', '', m.group(4))}

    # --- PA ---
    # Cambio: _([A-Za-z]+\d+) -> [_-]([A-Za-z]+\d+)
    m = re.search(r'(S\d+)_([A-Z]+)_(PA)([+\-_]\d+)_+(\d+)-(\d+)[_-]([A-Za-z]+\d+)', filename)
    if m:
        pct = int(m.group(4).replace('_', '+') if m.group(4).startswith('_') else m.group(4))
        return {'sujeto': re.sub(r'\D', '', m.group(1)),
                'mano': m.group(2), 'tipo_metronomo': 'PA',
                'porcentaje_cambio': pct,
                'bpm_1': BPM_BASE, 'bpm_2': round(BPM_BASE * (1 + pct / 100.0)),
                'clics_1': int(m.group(5)), 'clics_2': int(m.group(6)),
                'medicion': re.sub(r'\D', '', m.group(7))}

    # --- PR ---
    # Cambio: _([A-Za-z]+\d+) -> [_-]([A-Za-z]+\d+)
    m = re.search(r'(S\d+)_([A-Z]+)_(PR)([+\-_]\d+)_+(\d+)-(\d+)-(\d+)[_-]([A-Za-z]+\d+)', filename)
    if m:
        pct = int(m.group(4).replace('_', '+') if m.group(4).startswith('_') else m.group(4))
        return {'sujeto': re.sub(r'\D', '', m.group(1)),
                'mano': m.group(2), 'tipo_metronomo': 'PR',
                'porcentaje_cambio': pct,
                'bpm_1': BPM_BASE, 'bpm_2': round(BPM_BASE * (1 + pct / 100.0)),
                'clics_1': int(m.group(5)), 'clics_rampa': int(m.group(6)),
                'clics_2': int(m.group(7)),
                'medicion': re.sub(r'\D', '', m.group(8))}

    return {}


def verificar_audio_con_video(metadata, audio_path):
    """
    Verifica que el archivo de audio corresponda al video segÃºn los
    metadatos extraÃ­dos del nombre del video.

    Lanza ValueError si el audio no corresponde al video.
    """
    audio_name = os.path.splitext(os.path.basename(audio_path))[0].lower()

    if metadata['tipo_metronomo'] == 'ISO':
        patron = r"metronomo[_ ]?is[oÃ³]crono(\d+)bpm"
        match = re.search(patron, audio_name)
        if match is None:
            raise ValueError(
                f"ERROR: El archivo de audio no tiene el formato esperado para un "
                f"metrÃ³nomo isÃ³crono.\nArchivo de audio: {os.path.basename(audio_path)}")

        bpm_audio = int(match.group(1))
        if bpm_audio != metadata['bpm']:
            raise ValueError(
                f"ERROR: El audio no corresponde al video.\n"
                f"Video : {metadata['bpm']} BPM\nAudio : {bpm_audio} BPM\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")

    elif metadata['tipo_metronomo'] == 'PA':
        patron = r"pa([+-]\d+)__?(\d+)-(\d+)"
        match = re.search(patron, audio_name)
        if match is None:
            raise ValueError(
                f"ERROR: El archivo de audio no tiene el formato esperado para un "
                f"estÃ­mulo PA.\nArchivo de audio: {os.path.basename(audio_path)}")

        porcentaje, clics1, clics2 = int(match.group(1)), int(match.group(2)), int(match.group(3))
        if porcentaje != metadata['porcentaje_cambio']:
            raise ValueError(
                f"ERROR: El porcentaje de cambio no coincide.\n"
                f"Video : {metadata['porcentaje_cambio']}%\nAudio : {porcentaje}%\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")
        if clics1 != metadata['clics_1']:
            raise ValueError(
                f"ERROR: La cantidad de clics iniciales no coincide.\n"
                f"Video : {metadata['clics_1']}\nAudio : {clics1}\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")
        if clics2 != metadata['clics_2']:
            raise ValueError(
                f"ERROR: La cantidad de clics finales no coincide.\n"
                f"Video : {metadata['clics_2']}\nAudio : {clics2}\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")

    elif metadata['tipo_metronomo'] == 'PR':
        patron = r"pr([+-]\d+)__?(\d+)-(\d+)-(\d+)"
        match = re.search(patron, audio_name)
        if match is None:
            raise ValueError(
                f"ERROR: El archivo de audio no tiene el formato esperado para un "
                f"estÃ­mulo PR.\nArchivo de audio: {os.path.basename(audio_path)}")

        porcentaje = int(match.group(1))
        clics1, clics_rampa, clics2 = int(match.group(2)), int(match.group(3)), int(match.group(4))
        if porcentaje != metadata['porcentaje_cambio']:
            raise ValueError(
                f"ERROR: El porcentaje de cambio no coincide.\n"
                f"Video : {metadata['porcentaje_cambio']}%\nAudio : {porcentaje}%\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")
        if clics1 != metadata['clics_1']:
            raise ValueError(
                f"ERROR: La cantidad de clics iniciales no coincide.\n"
                f"Video : {metadata['clics_1']}\nAudio : {clics1}\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")
        if clics_rampa != metadata['clics_rampa']:
            raise ValueError(
                f"ERROR: La cantidad de clics de la rampa no coincide.\n"
                f"Video : {metadata['clics_rampa']}\nAudio : {clics_rampa}\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")
        if clics2 != metadata['clics_2']:
            raise ValueError(
                f"ERROR: La cantidad de clics finales no coincide.\n"
                f"Video : {metadata['clics_2']}\nAudio : {clics2}\n"
                f"Archivo de audio: {os.path.basename(audio_path)}")

    else:
        raise ValueError(f"Tipo de metrÃ³nomo desconocido: {metadata['tipo_metronomo']}")

    print("El archivo de audio corresponde correctamente al video.")


def _num_estimulos_esperados(metadata):
    """
    Cantidad TOTAL de estÃ­mulos que el protocolo dice que deberÃ­a haber,
    segÃºn metadata -- solo se conoce de antemano para PA/PR (vienen los
    clics en el nombre del archivo); para ISO no hay forma de saberlo sin
    la duraciÃ³n real de la grabaciÃ³n, asÃ­ que devuelve None.
    """
    tipo = metadata.get('tipo_metronomo', 'ISO')
    if tipo == 'PA':
        return metadata.get('clics_1', 0) + metadata.get('clics_2', 0)
    elif tipo == 'PR':
        return (metadata.get('clics_1', 0) + metadata.get('clics_rampa', 0)
                + metadata.get('clics_2', 0))
    return None


def find_largest_amplitude_change(audio_data, sample_rate, metadata,
                                  back_search_s=2.0, smooth_ms=10, min_run_peaks=3,
                                  gap_maximo_fusion_s=3.0, banda_click_hz=(1800, 2200)):
    """
    DetecciÃ³n robusta del Ã­ndice de inicio del patrÃ³n rÃ­tmico (metrÃ³nomo).
    Retorna el Ã­ndice (sample) del onset.

    La envolvente se calcula sobre el audio FILTRADO a la banda del click
    del metrÃ³nomo (~2000Hz, misma banda que ya usa el resto del pipeline
    en calibrar_deriva_reloj_camara/_detectar_offset_audio_bleed) en vez
    del audio de banda ancha completo -- confirmado con evidencia
    directa: ruido ambiental al principio de una grabaciÃ³n (manipulaciÃ³n
    del celular, voces) puede tener, sobre el espectro completo,
    suficiente energÃ­a y una periodicidad casual como para confundir al
    detector de rachas -- pero ese tipo de ruido casi no tiene energÃ­a en
    la banda angosta donde vive especÃ­ficamente el click (los golpes de
    mano/voces son de banda mucho mÃ¡s ancha y mÃ¡s grave) -- filtrar ahÃ­
    elimina la mayorÃ­a de esos falsos candidatos de raÃ­z, en vez de
    depender de que la periodicidad casual del ruido no alcance a
    parecerse a la del metrÃ³nomo.
    """
    audio = np.array(audio_data)
    if audio.ndim > 1:
        audio = np.mean(audio, axis=1)
    if audio.size == 0:
        return 0

    max_abs = np.max(np.abs(audio))
    if max_abs == 0:
        return 0
    audio_n = audio / max_abs

    nyquist = sample_rate / 2
    if banda_click_hz[1] < nyquist:
        b_bp, a_bp = signal.butter(4, [banda_click_hz[0] / nyquist, banda_click_hz[1] / nyquist],
                                    btype='band')
        audio_filtrada = signal.filtfilt(b_bp, a_bp, audio_n)
    else:
        # Sample rate demasiado bajo para la banda pedida -- respaldo al
        # audio de banda ancha en vez de fallar (caso extremo, no deberÃ­a
        # pasar con las tasas de muestreo tÃ­picas de video).
        audio_filtrada = audio_n

    smooth_win = max(1, int(sample_rate * smooth_ms / 1000.0))
    env = np.abs(audio_filtrada)
    env = np.convolve(env, np.ones(smooth_win) / smooth_win, mode='same')
    if np.max(env) > 0:
        env = env / np.max(env)   # renormalizar -- el filtro banda angosta reduce la amplitud general

    tipo = metadata.get('tipo_metronomo', 'ISO')
    if tipo in ('PA', 'PR'):
        bpm = metadata.get('bpm_1', metadata.get('bpm', None))
    else:
        bpm = metadata.get('bpm', None)
    if bpm is None or bpm <= 0:
        period_samples = int(0.5 * sample_rate)
    else:
        period_samples = int(round(sample_rate * 60.0 / float(bpm)))

    distance = max(1, int(0.6 * period_samples))
    h    = np.percentile(env, 75)
    prom = 0.20 * np.max(env)

    peaks, props = find_peaks(env, height=h, distance=distance, prominence=prom)
    for pct in (70, 60, 50, 40, 30):
        if len(peaks) >= min_run_peaks:
            break
        h    = np.percentile(env, pct)
        prom = max(0.05 * np.max(env), 0.1 * prom)
        peaks, props = find_peaks(env, height=h, distance=distance, prominence=prom)

    if len(peaks) == 0:
        return int(np.argmax(env))

    peaks = np.sort(peaks)

    diffs = np.diff(peaks)
    tol   = max(int(0.25 * period_samples), 1)
    # Un solo gap aislado, apenas fuera de tolerancia, no deberÃ­a romper una
    # racha larga y limpia -- confirmado con evidencia directa: una racha
    # de 54 diferencias perfectamente consistentes se cortÃ³ en dos por un
    # Ãºnico gap que se pasaba de la tolerancia por menos del 1% del
    # perÃ­odo, quedÃ¡ndose el algoritmo con la mitad equivocada (mÃ¡s corta
    # en duraciÃ³n real, pero "mÃ¡s larga" en cantidad de picos porque la
    # racha genuina se habÃ­a partido injustamente). Se perdona una
    # anomalÃ­a AISLADA (no dos seguidas) dentro de una racha ya en curso,
    # con un margen mÃ¡s generoso (tol_extendida) para no descartar algo
    # que sigue siendo, de forma razonable, "un beat perdido o mal
    # detectado" y no un cambio genuino de periodicidad.
    tol_extendida = 2 * tol
    runs = []   # lista de (idx_inicio_en_diffs, largo) -- TODAS las rachas, no solo la mejor
    run_start  = None
    run_len    = 0
    anomalia_previa = False
    for i, d in enumerate(diffs):
        if abs(d - period_samples) <= tol:
            if run_start is None:
                run_start = i
                run_len   = 1
            else:
                run_len += 1
            anomalia_previa = False
        elif run_start is not None and not anomalia_previa and abs(d - period_samples) <= tol_extendida:
            # AnomalÃ­a aislada dentro de una racha en curso -- se perdona
            # sin resetear (tampoco suma al largo, no hay certeza de que
            # haya un beat real ahÃ­).
            anomalia_previa = True
        else:
            if run_start is not None:
                runs.append((run_start, run_len))
            run_start = None
            run_len   = 0
            anomalia_previa = False
    if run_start is not None:
        runs.append((run_start, run_len))

    # --- Fusionar rachas separadas por una interrupciÃ³n CORTA (ej. ruido
    # puntual, un golpe/sonido fuerte ajeno al tapeo) -----------------------
    # Un ruido fuerte de un par de segundos puede romper VARIAS diferencias
    # seguidas (mÃ¡s de lo que la tolerancia de "anomalÃ­a aislada" de arriba
    # perdona), partiendo en dos una racha que en realidad es una Ãºnica
    # sesiÃ³n de tapeo continua. Confirmado con evidencia directa: un ruido
    # puntual de ~2s partiÃ³ una racha limpia en dos, y el algoritmo se
    # quedaba con la mitad mÃ¡s corta (la de DESPUÃ‰S del ruido), perdiendo
    # ~23 segundos de sesiÃ³n real al principio -- la mitad descartada era
    # mÃ¡s larga en duraciÃ³n real, pero el corte injusto no dejaba
    # comparar eso directamente.
    #
    # Dos rachas cuya periodicidad ya es individualmente consistente
    # (confirmado por el propio bucle de arriba), separadas por un hueco de
    # tiempo CHICO entre el Ãºltimo pico de una y el primero de la
    # siguiente, son casi con certeza la misma sesiÃ³n interrumpida -- no
    # dos sesiones de tapeo distintas. gap_maximo_fusion_s es generoso
    # (3s) para cubrir un ruido/golpe puntual, pero no tanto como para
    # fusionar pausas reales largas del sujeto.
    #
    # Se exige ademÃ¡s que las dos rachas sean COMPARABLES en tamaÃ±o (no
    # que una sea una fracciÃ³n chica de la otra) para poder fusionarse --
    # confirmado con evidencia directa: un ruido AMBIENTE al principio de
    # la grabaciÃ³n (manipulaciÃ³n del celular, voces) puede tener, por
    # pura casualidad, una periodicidad que cae dentro de la tolerancia
    # esperada del metrÃ³nomo durante unos pocos picos, formando una racha
    # CORTA que pasa el chequeo de periodicidad individual sin ser real
    # -- y si el hueco hasta el patrÃ³n real (que sÃ­ es largo) cae por
    # casualidad por debajo del umbral de fusiÃ³n, esa racha corta y
    # espuria termina fusionÃ¡ndose con la real, corriendo el inicio
    # elegido varios segundos antes de lo que deberÃ­a.
    #
    # Un nÃºmero FIJO de picos como piso no generaliza -- una grabaciÃ³n con
    # mÃ¡s ruido ambiental al principio podrÃ­a producir una racha espuria
    # mÃ¡s larga que cualquier piso fijo razonable, y seguirÃ­a colÃ¡ndose.
    # En cambio, una PROPORCIÃ“N respecto a la racha con la que se
    # fusionarÃ­a es relativa a la evidencia real disponible en cada
    # video: una racha genuina partida por un ruido puntual (el caso que
    # este mecanismo busca arreglar) dejan de cada lado partes de tamaÃ±o
    # similar entre sÃ­, mientras que ruido ambiental casual, aunque sea
    # mÃ¡s largo en un video mÃ¡s ruidoso, sigue siendo chico EN RELACIÃ“N
    # al patrÃ³n real de esa misma sesiÃ³n (que dura toda la grabaciÃ³n).
    RATIO_MINIMO_FUSION = 0.5
    rachas_fusionadas = []
    for start_i, len_i in runs:
        if rachas_fusionadas:
            prev_start, prev_len = rachas_fusionadas[-1]
            idx_fin_prev    = peaks[prev_start + prev_len]
            idx_inicio_esta = peaks[start_i]
            gap_s = (idx_inicio_esta - idx_fin_prev) / sample_rate
            ratio_tamanos = min(prev_len, len_i) / max(prev_len, len_i) if max(prev_len, len_i) > 0 else 0.0
            son_comparables = prev_len >= min_run_peaks and len_i >= min_run_peaks and ratio_tamanos >= RATIO_MINIMO_FUSION
            if gap_s <= gap_maximo_fusion_s and son_comparables:
                rachas_fusionadas[-1] = (prev_start, (start_i + len_i) - prev_start)
                continue
        rachas_fusionadas.append((start_i, len_i))

    n_fusiones = len(runs) - len(rachas_fusionadas)
    if n_fusiones > 0:
        print(f"  [Inicio de sesiÃ³n] {n_fusiones} racha(s) fusionada(s) tras una interrupciÃ³n corta "
              f"(<= {gap_maximo_fusion_s:.1f}s, probable ruido puntual) -- evita perder el inicio real "
              f"de la sesiÃ³n por un golpe/sonido ajeno al tapeo.")

    # Elegir la racha final: si se conoce la cantidad TOTAL de estÃ­mulos
    # esperada (PA/PR, viene de los clics del nombre de archivo), preferir
    # la racha cuya cantidad de picos quede mÃ¡s cerca de ese nÃºmero --
    # mÃ¡s especÃ­fico que "la mÃ¡s larga a secas", porque una racha espuria
    # (ruido con periodicidad casual) rara vez coincide por casualidad con
    # el nÃºmero exacto de clics del protocolo. Para ISO (sin cantidad
    # conocida de antemano) se mantiene el criterio de "la mÃ¡s larga".
    n_esperado = _num_estimulos_esperados(metadata)
    best_start, best_len = None, 0
    if n_esperado is not None and n_esperado > 0:
        mejor_diff = None
        for start_i, len_i in rachas_fusionadas:
            n_picos_racha = len_i + 1
            diff_vs_esperado = abs(n_picos_racha - n_esperado)
            if mejor_diff is None or diff_vs_esperado < mejor_diff:
                mejor_diff = diff_vs_esperado
                best_start, best_len = start_i, len_i
        print(f"  [Inicio de sesiÃ³n] Cantidad de estÃ­mulos esperada (metadata): {n_esperado} -- "
              f"racha elegida con {best_len + 1} picos (diferencia={mejor_diff}).")
    else:
        for start_i, len_i in rachas_fusionadas:
            if len_i > best_len:
                best_len   = len_i
                best_start = start_i

    if best_start is not None and best_len >= (min_run_peaks - 1):
        inicio_metronomo = peaks[best_start]
    else:
        inicio_metronomo = peaks[0]

    search_start = max(0, inicio_metronomo - int(back_search_s * sample_rate))
    segmento     = env[search_start: inicio_metronomo + 1]
    if segmento.size > 0:
        local_thr = np.percentile(segmento, 60)
        pseg, _   = find_peaks(segmento, height=local_thr,
                               distance=max(1, int(0.3 * period_samples)))
        if len(pseg) > 0:
            inicio_metronomo = int(search_start + pseg[-1])

    return int(inicio_metronomo)


def find_rhythmic_segment(audio_data, sample_rate, metadata,
                           back_search_s=2.0, smooth_ms=10, min_run_peaks=3):
    """
    DetecciÃ³n robusta de inicio y fin del patrÃ³n rÃ­tmico.
    - Inicio: find_largest_amplitude_change() (lÃ³gica original probada).
    - Fin:    Ãºltima ventana de 50 ms con energÃ­a > 10% del mÃ¡ximo.
    """
    audio = np.asarray(audio_data)
    if audio.ndim > 1:
        audio = np.mean(audio, axis=1)
    if audio.size == 0:
        return 0, len(audio_data)

    # --- INICIO: lÃ³gica original ---
    inicio_ritmo = find_largest_amplitude_change(
        audio, sample_rate, metadata,
        back_search_s=back_search_s,
        smooth_ms=smooth_ms,
        min_run_peaks=min_run_peaks
    )

    # --- FIN: Ãºltima ventana de 50 ms con energÃ­a > 10% del mÃ¡ximo ---
    audio_post = audio[inicio_ritmo:]
    win_fin    = max(1, int(0.05 * sample_rate))
    energia_fin = np.array([
        np.sum(np.abs(audio_post[i: i + win_fin]))
        for i in range(0, len(audio_post), win_fin)
    ])
    umbral_fin   = 0.10 * np.max(energia_fin)
    idxs_validos = np.where(energia_fin > umbral_fin)[0]
    if len(idxs_validos) > 0:
        fin_ritmo = inicio_ritmo + min(len(audio_post), (int(idxs_validos[-1]) + 1) * win_fin)
    else:
        fin_ritmo = len(audio)
    fin_ritmo = min(len(audio) - 1, fin_ritmo)

    return int(inicio_ritmo), int(fin_ritmo)


def calcular_centroide_tip(df, pesos=None):
    tips  = ['indice_tip', 'medio_tip', 'anular_tip', 'meÃ±ique_tip']
    if pesos is None:
        pesos = {'indice_tip': 0.4, 'medio_tip': 0.4, 'anular_tip': 0.1, 'meÃ±ique_tip': 0.1}
    total = sum(pesos.values())
    df['promedio_tip_x'] = sum(df[f'{t}_x'] * pesos[t] for t in tips) / total
    df['promedio_tip_y'] = sum(df[f'{t}_y'] * pesos[t] for t in tips) / total
    return df


def calcular_angulo_postura(df):
    mcps = ['indice_mcp', 'medio_mcp', 'anular_mcp', 'meÃ±ique_mcp']
    df['promedio_mcp_x'] = df[[f'{m}_x' for m in mcps]].mean(axis=1)
    df['promedio_mcp_y'] = df[[f'{m}_y' for m in mcps]].mean(axis=1)
    Ax = df['promedio_tip_x'] - df['promedio_mcp_x']
    Ay = df['promedio_tip_y'] - df['promedio_mcp_y']
    Bx = df['promedio_mcp_x'] - df['muÃ±eca_x']
    By = df['promedio_mcp_y'] - df['muÃ±eca_y']
    dot   = Ax * Bx + Ay * By
    magA  = np.sqrt(Ax**2 + Ay**2)
    magB  = np.sqrt(Bx**2 + By**2)
    denom = np.where(magA * magB == 0, 1e-10, magA * magB)
    df['angulo_postura'] = np.degrees(np.arccos(np.clip(dot / denom, -1.0, 1.0)))
    return df

def _calcular_tiempos_apoyo_alzada(df, tip_peaks_a, tip_peaks_b, fps, umbral_base,
                                    savgol_win=11, savgol_poly=5, min_dur_ms=30):
    col = 'tip_y'
    # tip_peaks_a â†’ picos ALTOS de tip_y (mano en el aire).
    # tip_peaks_b â†’ picos BAJOS de tip_y (impacto en mesa).
    #
    # Un solo umbral (umbral_base: mÃ¡ximo robusto de los picos bajos, sin el
    # margen de tolerancia de la detecciÃ³n de cruce puntual): apoyo y alzada
    # son estados complementarios de ese mismo corte, sin zona intermedia.
    umbral_apoyo = umbral_base

    min_frames = max(1, int(np.ceil(min_dur_ms / 1000.0 * fps)))

    y  = df[col].ffill().bfill().to_numpy()
    wl = savgol_win if len(y) >= savgol_win else (len(y) if len(y) % 2 == 1 else len(y) - 1)
    y_s = savgol_filter(y, wl, savgol_poly)

    # DetecciÃ³n vectorizada: apoyo = zona baja de tip_y (mesa); alzada = todo lo demÃ¡s.
    en_apoyo = y_s <= umbral_apoyo
    alzada   = ~en_apoyo

    en_apoyo = binary_closing(en_apoyo, np.ones(min_frames))
    alzada   = binary_closing(alzada,   np.ones(min_frames))

    print(f"  umbral_apoyo={umbral_apoyo:.4f} (alzada = todo lo que no estÃ¡ en apoyo)")
    print(f"  frames en apoyo: {en_apoyo.sum()}  frames en alzada: {alzada.sum()}")

    def _dur(mask):
        lbl, n = _ndimage_label(mask)
        durs   = []
        for sid in range(1, n + 1):
            idx = np.where(lbl == sid)[0]
            if len(idx) >= min_frames:
                durs.append(len(idx) / fps * 1000)
        return float(np.mean(durs)) if durs else 0.0

    t_a = _dur(en_apoyo)
    t_z = _dur(alzada)
    print(f"\nApoyo: {t_a:.1f} ms | Alzada: {t_z:.1f} ms")
    return t_a, t_z, en_apoyo, alzada


def _calcular_amplitudes_por_tramo(df, tip_peaks_a, tip_peaks_b, metadata, fps, cambios):
    tipo = metadata.get('tipo_metronomo', 'ISO')
    # Usamos indice_tip_y_cm (solo el dedo Ã­ndice) para la amplitud,
    # consistente con el cÃ³digo original. El centroide de 4 dedos suaviza
    # el rango de movimiento y da valores distintos.
    if 'indice_tip_y_cm' in df.columns:
        y_cm = df['indice_tip_y_cm']
    else:
        y_cm = df['tip_y_cm']   # fallback si no existe la columna
    resultados = []

    def _amp(ini_s, fin_s, lbl):
        ini_f, fin_f = int(ini_s * fps), int(fin_s * fps)
        amps = []
        for pa in tip_peaks_a:
            if not (ini_f <= pa <= fin_f):
                continue
            bajos = tip_peaks_b[(tip_peaks_b > pa) & (tip_peaks_b <= fin_f)]
            if len(bajos):
                amps.append(abs(y_cm.iloc[bajos[0]] - y_cm.iloc[pa]))
        media = float(np.mean(amps)) if amps else 0.0
        print(f"  Amplitud {lbl}: {media:.2f} cm")
        return {'label': lbl, 'amplitud_media_cm': round(media, 3)}

    if tipo == 'ISO':
        resultados.append(_amp(0, len(df) / fps, 'ISO'))
    elif tipo == 'PA':
        c = cambios
        resultados += [_amp(0, c, f"{metadata['bpm_1']} bpm"),
                       _amp(c, len(df)/fps, f"{metadata['bpm_2']} bpm")]
    elif tipo == 'PR':
        c1, c2 = cambios
        resultados += [_amp(0, c1, f"{metadata['bpm_1']} bpm"),
                       _amp(c1, c2, "Rampa"),
                       _amp(c2, len(df)/fps, f"{metadata['bpm_2']} bpm")]
    return resultados


def _calcular_tiempos_ascenso_descenso(df, tip_peaks_a, tip_peaks_b, metadata, fps, cambios):
    tipo  = metadata.get('tipo_metronomo', 'ISO')
    resultados = []

    def _t(ini_s, fin_s, lbl):
        ini_f, fin_f = int(ini_s*fps), int(fin_s*fps)
        pa_t = tip_peaks_a[(tip_peaks_a >= ini_f) & (tip_peaks_a <= fin_f)]
        pb_t = tip_peaks_b[(tip_peaks_b >= ini_f) & (tip_peaks_b <= fin_f)]
        desc, asc = [], []
        for pa in pa_t:
            pb = pb_t[pb_t > pa]
            if len(pb): desc.append((pb[0] - pa) * 1000.0 / fps)
        for pb in pb_t:
            pa = pa_t[pa_t > pb]
            if len(pa): asc.append((pa[0] - pb) * 1000.0 / fps)
        td = float(np.mean(desc)) if desc else np.nan
        ta = float(np.mean(asc))  if asc  else np.nan
        suma = (td + ta) if not (np.isnan(td) or np.isnan(ta)) else np.nan
        pd_  = round(td / suma * 100, 2) if suma else None
        pa_  = round(ta / suma * 100, 2) if suma else None
        print(f"  {lbl} â€” Descenso: {td:.1f} ms | Ascenso: {ta:.1f} ms")
        return {'label': lbl, 't_desc_ms': round(td, 2), 't_asc_ms': round(ta, 2),
                'pct_desc': pd_, 'pct_asc': pa_}

    if tipo == 'ISO':
        resultados.append(_t(0, len(df)/fps, 'ISO'))
    elif tipo == 'PA':
        c = cambios
        resultados += [_t(0, c, f"{metadata['bpm_1']} bpm"),
                       _t(c, len(df)/fps, f"{metadata['bpm_2']} bpm")]
    elif tipo == 'PR':
        c1, c2 = cambios
        resultados += [_t(0, c1, f"{metadata['bpm_1']} bpm"),
                       _t(c1, c2, "Rampa"),
                       _t(c2, len(df)/fps, f"{metadata['bpm_2']} bpm")]
    return resultados


# ==============================================================================
# PROCESAMIENTO POR LOTE â€” mÃºltiples videos + audios en la misma carpeta
# ==============================================================================

def run_analysis_batch(content_dir=None):
    """
    Corre run_analysis() automÃ¡ticamente para cada video encontrado en
    content_dir (por default, CONTENT_DIR), emparejando cada uno con su
    .wav correspondiente -- reusa verificar_audio_con_video para probar,
    de todos los .wav disponibles, cuÃ¡l coincide con la metadata de cada
    video (mismo tipo de metrÃ³nomo, BPM, clics, etc.), en vez de asumir
    un Ãºnico .wav para toda la carpeta.

    La descarga automÃ¡tica por sesiÃ³n ya existe dentro de run_analysis(),
    asÃ­ que cada CSV se descarga apenas termina esa sesiÃ³n, sin esperar a
    que se procesen todos los videos.

    Videos que fallan (metadata no reconocida, ningÃºn .wav coincide, o
    cualquier error durante el anÃ¡lisis) se saltean con un aviso, sin
    interrumpir el resto del lote.
    """
    carpeta = content_dir or CONTENT_DIR
    videos = sorted([f for f in os.listdir(carpeta)
                     if f.lower().endswith(('.mp4', '.mov', '.avi', '.mkv'))])
    wavs = sorted([f for f in os.listdir(carpeta) if f.lower().endswith('.wav')])

    print(f"Encontrados {len(videos)} video(s) y {len(wavs)} audio(s) en {carpeta}")
    if not videos:
        print("No se encontraron videos para procesar.")
        return []

    resultados = []
    for n, video_file in enumerate(videos, start=1):
        video_path = os.path.join(carpeta, video_file)
        print(f"\n{'='*70}\n[{n}/{len(videos)}] Procesando: {video_file}\n{'='*70}")

        metadata = _extraer_metadata(video_file)
        if not metadata:
            print(f"  AVISO: no se pudo extraer metadata de '{video_file}' -- se salta.")
            continue

        metronome_path = None
        for wav_file in wavs:
            wav_path = os.path.join(carpeta, wav_file)
            try:
                verificar_audio_con_video(metadata, wav_path)
                metronome_path = wav_path
                break
            except ValueError:
                continue

        if metronome_path is None:
            print(f"  AVISO: ningÃºn .wav de la carpeta coincide con '{video_file}' -- se salta.")
            continue

        try:
            resultado = run_analysis(video_path=video_path, metronome_path=metronome_path)
            resultados.append(resultado)
        except Exception as e:
            print(f"  ERROR procesando '{video_file}': {e} -- se salta y se sigue con el resto.")
            continue

    print(f"\n{'='*70}")
    print(f"Lote terminado: {len(resultados)}/{len(videos)} sesiones procesadas con Ã©xito")
    print(f"{'='*70}")
    return resultados


